import { ModuleBoundary } from '@/app/ModuleBoundary';
import { SharedWorkspace } from '@/app/SharedWorkspace';
import { useApplicationModel } from '@/app/useApplicationModel';
import { WorkspaceDialogs } from '@/app/WorkspaceDialogs';
