import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Activity, ArrowUpRight, Camera, CameraOff, CheckCircle2, Clock, FileText, Flame,
  Inbox, MessageSquare, Pause, Phone, PhoneCall, PhoneForwarded, PhoneIncoming,
  Search, Send, ShieldCheck, Sparkles, Users, Video, XCircle,
} from 'lucide-react';
import { authFetch } from '@/utils/auth-fetch';
import { startSerialPoll } from '@/utils/serial-poll';
import { formatPhone } from '@/utils/privacy';

type QueueRecord = {
  id: string; consumer_name: string; consumer_phone: string;
  consumer_address?: string; duration_seconds: number; ai_summary: string;
  transfer_status?: string; queue: string; created_at: string;
  agent_disposition?: string; callback_requested?: boolean;
};

export interface AgentTodayStats {
  human_drops: number;
  fire_transfers: number;
  voice_messages: number;
  failed_transfers: number;
  callbacks_due: number;
  completed_callbacks: number;
  new_voicemails: number;
  live_humans?: number;
  active_calls_now?: number;
  today_total?: number;
  completed_today?: number;
}

type V2Message = {
  id: string; sender_agent_id: string | null; sender_name: string;
  message_kind: 'agent' | 'system' | 'transfer' | 'callback';
  body: string; created_at: string;
};

type V2Workspace = {
  route?: {
    bland_number?: string; talkroute_number?: string; transfer_certified?: boolean;
    inbound_configured?: boolean;
  };
  settings?: {
    personal_dialer_state?: string; number_certification_state?: string;
    camera_state?: string; camera_verified_at?: string | null;
  };
  messages?: V2Message[];
  active_client?: {
    contact_key: string; client_name: string; client_phone?: string;
    client_snapshot?: Record<string, unknown>; updated_at: string;
  } | null;
  client_notes?: Array<{ id: string; agent_id: string; client_name: string; body: string; created_at: string }>;
};

export interface AgentCockpitProps {
  agentName: string;
  agentId?: string;
  available: boolean;
  togglingAvail: boolean;
  onToggleAvail: () => void;
  fireTransfers: QueueRecord[];
  humanDrops: QueueRecord[];
  todayStats: AgentTodayStats | null;
  onNavTo: (tab: string) => void;
  activeNav: string;
  providerUrl?: string;
  sessionToken?: string;
  onUnauthorized?: () => void;
}

function fmtClock(iso: string) {
  return new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

function routeState(workspace: V2Workspace | null) {
  if (!workspace?.route) return { label: 'Checking route', tone: 'checking' };
  if (!workspace.route.transfer_certified) return { label: 'Certification required', tone: 'warn' };
  return { label: 'Personal route protected', tone: 'ready' };
}

export function AgentCockpit(props: AgentCockpitProps) {
  const {
    agentName, agentId, available, togglingAvail, onToggleAvail, fireTransfers,
    humanDrops, todayStats, onNavTo, providerUrl, sessionToken, onUnauthorized,
  } = props;
  const [workspace, setWorkspace] = useState<V2Workspace | null>(null);
  const [chatText, setChatText] = useState('');
  const [chatSending, setChatSending] = useState(false);
  const [chatError, setChatError] = useState('');
  const [cameraState, setCameraState] = useState<'idle' | 'requesting' | 'live' | 'blocked'>('idle');
  const [isMobile, setIsMobile] = useState(false);
  const [dialerChanging, setDialerChanging] = useState(false);
  const [dialerError, setDialerError] = useState('');
  const [clientNote, setClientNote] = useState('');
  const [noteSaving, setNoteSaving] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const auth = useRef(onUnauthorized);
  auth.current = onUnauthorized;

  useEffect(() => {
    if (!providerUrl || !sessionToken) return;
    const mobile = window.matchMedia('(max-width: 760px)').matches;
    setIsMobile(mobile);
    const poll = startSerialPoll(async signal => {
      const result = await authFetch<V2Workspace>(providerUrl, {
        body: { action: 'get_federal_one_v2', session_token: sessionToken },
        signal, onUnauthorized: () => auth.current?.(),
      });
      if (!signal.aborted && result.ok && result.data) setWorkspace(result.data);
      return result.ok;
    }, 5000, { paused: () => document.visibilityState === 'hidden' });
    let deviceKey = window.localStorage.getItem('federal-one-device-key');
    if (!deviceKey) {
      deviceKey = crypto.randomUUID();
      window.localStorage.setItem('federal-one-device-key', deviceKey);
    }
    const heartbeatPoll = startSerialPoll(async signal => {
      const result = await authFetch(providerUrl, {
        body: { action: 'device_heartbeat', session_token: sessionToken, device_key: deviceKey, device_kind: mobile ? 'phone' : 'desktop' },
        signal, onUnauthorized: () => auth.current?.(),
      });
      return result.ok;
    }, 15000, { maxBackoffMs: 30000 });
    const visible = () => { if (document.visibilityState !== 'hidden') poll.refresh(); };
    document.addEventListener('visibilitychange', visible);
    return () => { poll.stop(); heartbeatPoll.stop(); document.removeEventListener('visibilitychange', visible); };
  }, [providerUrl, sessionToken]);

  const changeDialerState = async () => {
    if (!providerUrl || !sessionToken || dialerChanging) return;
    const current = workspace?.settings?.personal_dialer_state || 'stopped';
    const state = current === 'running' ? 'paused' : 'running';
    setDialerChanging(true);
    setDialerError('');
    const result = await authFetch<{ state: string }>(providerUrl, {
      body: { action: 'set_personal_dialer_state', session_token: sessionToken, state },
      onUnauthorized: () => onUnauthorized?.(),
    });
    if (result.ok) setWorkspace(currentWorkspace => ({
      ...currentWorkspace,
      settings: { ...currentWorkspace?.settings, personal_dialer_state: result.data?.state || state },
    }));
    else setDialerError(result.error || 'Dialer could not be updated');
    setDialerChanging(false);
  };

  const saveClientNote = async () => {
    if (!workspace?.active_client || !clientNote.trim() || !providerUrl || !sessionToken || noteSaving) return;
    setNoteSaving(true);
    const result = await authFetch<{ note: { id: string; agent_id: string; client_name: string; body: string; created_at: string } }>(providerUrl, {
      body: { action: 'add_client_note', session_token: sessionToken, client_name: workspace.active_client.client_name, client_phone: workspace.active_client.client_phone, note: clientNote.trim() },
      onUnauthorized: () => onUnauthorized?.(),
    });
    if (result.ok && result.data?.note) {
      setClientNote('');
      setWorkspace(current => ({ ...current, client_notes: [result.data!.note, ...(current?.client_notes || [])] }));
    }
    setNoteSaving(false);
  };

  const setRemoteCameraState = useCallback(async (state: 'disconnected' | 'requesting' | 'connected' | 'blocked') => {
    if (!providerUrl || !sessionToken) return;
    await authFetch(providerUrl, {
      body: { action: 'set_federal_one_camera_state', session_token: sessionToken, camera_state: state },
      onUnauthorized: () => onUnauthorized?.(),
    });
  }, [providerUrl, sessionToken, onUnauthorized]);

  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks().forEach(track => track.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
    setCameraState('idle');
    void setRemoteCameraState('disconnected');
  }, [setRemoteCameraState]);

  useEffect(() => () => {
    streamRef.current?.getTracks().forEach(track => track.stop());
  }, []);

  const startCamera = async () => {
    if (isMobile || !navigator.mediaDevices?.getUserMedia) return;
    setCameraState('requesting');
    void setRemoteCameraState('requesting');
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'user' },
        audio: false,
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }
      setCameraState('live');
      void setRemoteCameraState('connected');
    } catch {
      setCameraState('blocked');
      void setRemoteCameraState('blocked');
    }
  };

  const sendMessage = async () => {
    const message = chatText.trim();
    if (!message || !providerUrl || !sessionToken || chatSending) return;
    setChatSending(true);
    setChatError('');
    const result = await authFetch<{ message: V2Message }>(providerUrl, {
      body: { action: 'send_federal_one_message', session_token: sessionToken, message },
      onUnauthorized: () => onUnauthorized?.(),
    });
    if (result.ok && result.data?.message) {
      setChatText('');
      setWorkspace(current => ({ ...current, messages: [...(current?.messages || []), result.data!.message] }));
    } else {
      setChatError(result.error || 'Message could not be sent');
    }
    setChatSending(false);
  };

  const pipeline = useMemo(() => [
    { label: 'Active now', value: todayStats?.active_calls_now ?? '—', icon: PhoneCall },
    { label: 'Live humans', value: todayStats?.live_humans ?? todayStats?.human_drops ?? '—', icon: Users },
    { label: 'Transfers', value: todayStats?.fire_transfers ?? '—', icon: PhoneForwarded },
    { label: 'Callbacks', value: todayStats?.callbacks_due ?? '—', icon: PhoneIncoming },
    { label: 'Completed', value: todayStats?.completed_today ?? '—', icon: CheckCircle2 },
    { label: 'Needs review', value: todayStats?.failed_transfers ?? '—', icon: XCircle },
  ], [todayStats, fireTransfers.length, humanDrops.length]);

  const firstName = agentName.split(' ')[0] || 'Agent';
  const greeting = new Date().getHours() < 12 ? 'Good morning' : new Date().getHours() < 17 ? 'Good afternoon' : 'Good evening';
  const route = routeState(workspace);
  const messages = workspace?.messages || [];
  const recent = [...fireTransfers, ...humanDrops].sort((a, b) => +new Date(b.created_at) - +new Date(a.created_at)).slice(0, 4);

  if (isMobile) {
    return (
      <div className="f1-mobile-companion">
        <div className="f1-mobile-orb"><ShieldCheck size={24} /></div>
        <span className="f1-overline">FEDERAL ONE 2.0</span>
        <h2>{firstName}'s Client Companion</h2>
        <p>Your phone follows the client open on your computer. Calling and camera controls stay on your computer.</p>
        {workspace?.active_client ? <div className="f1-mobile-active-client">
          <small>OPEN ON YOUR COMPUTER</small>
          <strong>{workspace.active_client.client_name}</strong>
          <span>{workspace.active_client.client_phone ? formatPhone(workspace.active_client.client_phone) : 'Client record'}</span>
          <button onClick={() => onNavTo('contacts')}>Open client <ArrowUpRight size={15} /></button>
          <div className="f1-mobile-note"><input value={clientNote} onChange={event => setClientNote(event.target.value)} placeholder="Add a note…" maxLength={2000} /><button onClick={() => void saveClientNote()} disabled={!clientNote.trim() || noteSaving}><Send size={14} /></button></div>
          {(workspace.client_notes || []).slice(0, 2).map(note => <p className="f1-mobile-note-row" key={note.id}>{note.body}</p>)}
        </div> : <div className="f1-mobile-active-client empty"><strong>No client open</strong><span>Open a client on your computer and it will appear here.</span></div>}
        <div className="f1-mobile-actions">
          <button onClick={() => onNavTo('extra')}><FileText size={18} /><span>Extra Info</span><ArrowUpRight size={16} /></button>
          <button onClick={() => onNavTo('contacts')}><Search size={18} /><span>Find a client</span><ArrowUpRight size={16} /></button>
          <button onClick={() => onNavTo('inbox')}><Inbox size={18} /><span>Incoming alerts</span><ArrowUpRight size={16} /></button>
          <button onClick={() => onNavTo('saved')}><Clock size={18} /><span>Callbacks & saved</span><ArrowUpRight size={16} /></button>
        </div>
      </div>
    );
  }

  return (
    <div className="f1-command-center" role="region" aria-label="Federal One agent command center">
      <section className="f1-command-hero">
        <div className="f1-command-copy">
          <span className="f1-overline"><Sparkles size={12} /> MY WORKSPACE</span>
          <h2>{greeting}, <em>{firstName}</em></h2>
          <p>Everything you need to find clients, make calls, and get help.</p>
        </div>
        <button className={`f1-availability ${available ? 'is-ready' : 'is-away'}`} onClick={onToggleAvail} disabled={togglingAvail}>
          <span />
          <div><small>WORK STATUS</small><strong>{togglingAvail ? 'Updating' : available ? 'Available' : 'Away'}</strong></div>
        </button>
      </section>

      <section className="f1-readiness-rail">
        <div className="f1-readiness-item"><span className="f1-readiness-icon"><Activity size={15} /></span><div><small>WORKSTATION</small><strong>Connected</strong></div></div>
        <div className="f1-readiness-item"><span className="f1-readiness-icon"><Phone size={15} /></span><div><small>BLAND.AI LINE</small><strong>{workspace?.route?.bland_number ? formatPhone(workspace.route.bland_number) : 'Checking'}</strong></div></div>
        <div className="f1-readiness-item"><span className="f1-readiness-icon"><PhoneForwarded size={15} /></span><div><small>ZADARMA</small><strong>{workspace?.route?.talkroute_number ? formatPhone(workspace.route.talkroute_number) : 'Checking'}</strong></div></div>
        <div className={`f1-readiness-item ${route.tone}`}><span className="f1-readiness-icon"><ShieldCheck size={15} /></span><div><small>ROUTE STATUS</small><strong>{route.label}</strong></div></div>
      </section>

      <button className={`f1-simple-dialer ${workspace?.settings?.personal_dialer_state === 'running' ? 'running' : ''}`} onClick={() => void changeDialerState()} disabled={dialerChanging || !workspace?.route?.transfer_certified}>
        <span>{workspace?.settings?.personal_dialer_state === 'running' ? <Pause size={19} /> : <PhoneCall size={19} />}</span>
        <div><small>MY DIALER</small><strong>{dialerChanging ? 'Updating…' : workspace?.settings?.personal_dialer_state === 'running' ? 'Pause my calls' : 'Start my calls'}</strong></div>
        <ArrowUpRight size={17} />
      </button>
      {dialerError && <div className="f1-simple-error">{dialerError}</div>}

      <div className="f1-command-grid">
        <main className="f1-command-main">
          <div className="f1-primary-actions">
            <button className="f1-primary-action extra-info-cockpit" onClick={() => onNavTo('extra')}>
              <span className="f1-action-icon"><FileText size={24} /></span><div><small>RESEARCH</small><strong>Extra Info</strong><p>Find more on a live call</p></div><ArrowUpRight size={18} />
            </button>
            <button className="f1-primary-action dialer" onClick={() => onNavTo('calls')}>
              <span className="f1-action-icon"><Flame size={24} /></span><div><small>CALLS</small><strong>My Calls</strong><p>See live calls and history</p></div><ArrowUpRight size={18} />
            </button>
            <button className="f1-primary-action secretary" onClick={() => onNavTo('secretary')}>
              <span className="f1-action-icon"><Send size={24} /></span><div><small>HELP</small><strong>Ask Elizabeth</strong><p>Have Elizabeth call first</p></div><ArrowUpRight size={18} />
            </button>
            <button className="f1-primary-action intelligence" onClick={() => onNavTo('contacts')}>
              <span className="f1-action-icon"><Search size={24} /></span><div><small>SEARCH</small><strong>Find a Client</strong><p>Search records and public sources</p></div><ArrowUpRight size={18} />
            </button>
          </div>

          <div className="f1-metric-panel">
            <div className="f1-panel-heading"><div><small>TODAY</small><strong>Personal performance</strong></div><span>LIVE DATA</span></div>
            <div className="f1-metric-grid">
              {pipeline.map(({ label, value, icon: Icon }) => <div className="f1-metric" key={label}><Icon size={15} /><strong>{value}</strong><span>{label}</span></div>)}
            </div>
          </div>

          <div className="f1-activity-panel">
            <div className="f1-panel-heading"><div><small>OPERATIONS PULSE</small><strong>Recent client activity</strong></div><button onClick={() => onNavTo('calls')}>View all <ArrowUpRight size={13} /></button></div>
            {recent.length === 0 ? <div className="f1-empty-pulse"><Activity size={19} /><span>New client activity will appear here in real time.</span></div> : recent.map(item => (
              <button className="f1-activity-row" key={item.id} onClick={() => onNavTo('calls')}>
                <span className="f1-client-monogram">{item.consumer_name?.split(' ').map(p => p[0]).join('').slice(0, 2) || '?'}</span>
                <div><strong>{item.consumer_name || 'Unknown client'}</strong><small>{item.queue === 'fire_transfer' ? 'Transfer ready' : 'Live response'} · {fmtClock(item.created_at)}</small></div>
                <span className={item.queue === 'fire_transfer' ? 'hot' : 'warm'}>{item.queue === 'fire_transfer' ? 'TRANSFER' : 'HUMAN'}</span>
              </button>
            ))}
          </div>
        </main>

        <aside className="f1-collaboration-rail">
          <div className="f1-workroom-card">
            <div className="f1-panel-heading"><div><small>FEDERAL ONE WORKROOM</small><strong>Camera verification</strong></div><Video size={16} /></div>
            <div className={`f1-camera-stage ${cameraState}`}>
              <video ref={videoRef} muted playsInline />
              {cameraState !== 'live' && <div className="f1-camera-placeholder">{cameraState === 'blocked' ? <CameraOff size={26} /> : <Camera size={26} />}<strong>{cameraState === 'requesting' ? 'Requesting permission' : cameraState === 'blocked' ? 'Camera permission blocked' : 'Camera is off'}</strong><span>Permission is requested before activation.</span></div>}
              {cameraState === 'live' && <span className="f1-camera-live"><i /> CAMERA CONNECTED</span>}
            </div>
            {cameraState === 'live' ? <button className="f1-camera-button stop" onClick={stopCamera}><CameraOff size={15} /> Leave workroom</button> : <button className="f1-camera-button" onClick={startCamera} disabled={cameraState === 'requesting'}><Camera size={15} /> {cameraState === 'blocked' ? 'Try camera again' : 'Join workroom'}</button>}
          </div>

          <div className="f1-team-card">
            <div className="f1-panel-heading"><div><small>TEAM ROOM</small><strong>Federal One Chat</strong></div><MessageSquare size={16} /></div>
            <div className="f1-chat-feed">
              {messages.length === 0 ? <div className="f1-chat-empty">Team messages and system alerts will appear here.</div> : messages.slice(-8).map(message => (
                <div className={`f1-chat-message ${message.sender_agent_id === agentId ? 'mine' : ''}`} key={message.id}>
                  <div><strong>{message.sender_name}</strong><time>{fmtClock(message.created_at)}</time></div><p>{message.body}</p>
                </div>
              ))}
            </div>
            {chatError && <div className="f1-chat-error">{chatError}</div>}
            <div className="f1-chat-compose">
              <input value={chatText} onChange={event => setChatText(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void sendMessage(); }} placeholder="Message the team..." maxLength={2000} />
              <button onClick={sendMessage} disabled={!chatText.trim() || chatSending} aria-label="Send message"><Send size={15} /></button>
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}

src/components/AgentInbox.tsx:
import { useState, useEffect, useCallback, useRef } from 'react';
import { Inbox, Search, RefreshCw, ChevronDown, ChevronUp, Phone, PhoneOff, Clock, Check, Calendar, AlertTriangle, X, MapPin, DollarSign, Home, FileText, Copy } from 'lucide-react';
import { authFetch } from '@/utils/auth-fetch';
import { RecordingPlayer } from './RecordingPlayer';

type InboxItem = {
  id: string;
  call_id: string;
  status: string;
  consumer_name: string;
  consumer_phone: string;
  consumer_address: string | null;
  consumer_home_value: string | null;
  consumer_income_range: string | null;
  consumer_property_info: string | null;
  direction: string | null;
  transfer_requested: boolean;
  talkroute_leg_created: boolean;
  talkroute_answered: boolean;
  bridge_confirmed: boolean;
  outcome: string | null;
  notes: string | null;
  callback_at: string | null;
  callback_completed_at: string | null;
  recording_url: string | null;
  transcript: string | null;
  created_at: string;
  updated_at: string;
};

interface AgentInboxProps {
  sessionToken: string;
  onUnauthorized: () => void;
  providerUrl: string;
  agentId: string;
}

const TABS = [
  { id: 'all', label: 'All' },
  { id: 'active', label: 'Active' },
  { id: 'answered', label: 'Answered' },
  { id: 'missed', label: 'Missed' },
  { id: 'callback_needed', label: 'Callbacks' },
  { id: 'completed', label: 'Completed' },
] as const;

function fmtPhone(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  const last10 = digits.slice(-10);
  if (last10.length === 10) return `(${last10.slice(0, 3)}) ${last10.slice(3, 6)}-${last10.slice(6)}`;
  return phone;
}

function timeAgo(iso: string): string {
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ${m % 60}m ago`;
  return `${Math.floor(h / 24)}d ago`;
}

function isOverdue(callbackAt: string | null): boolean {
  if (!callbackAt) return false;
  return new Date(callbackAt).getTime() < Date.now();
}

const STATUS_STEPS = ['transfer_requested', 'talkroute_leg_created', 'talkroute_answered', 'bridge_confirmed'] as const;

function InboxItemCard({
  item, providerUrl, sessionToken, onUnauthorized, onRefresh,
}: {
  item: InboxItem;
  providerUrl: string;
  sessionToken: string;
  onUnauthorized: () => void;
  onRefresh: () => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showSchedule, setShowSchedule] = useState(false);
  const [cbDate, setCbDate] = useState('');
  const [cbTime, setCbTime] = useState('');
  const [copied, setCopied] = useState(false);

  const handleAction = useCallback(async (action: string, extra: Record<string, unknown> = {}) => {
    setSubmitting(true);
    setError(null);
    const result = await authFetch(providerUrl, {
      body: { action, session_token: sessionToken, alert_id: item.id, notes, ...extra },
      onUnauthorized,
    });
    if (result.ok) { onRefresh(); }
    else { setError(result.error || 'Action failed'); }
    setSubmitting(false);
  }, [providerUrl, sessionToken, onUnauthorized, item.id, notes, onRefresh]);

  const handleSchedule = useCallback(async () => {
    if (!cbDate || !cbTime) return;
    const iso = new Date(`${cbDate}T${cbTime}`).toISOString();
    await handleAction('schedule_alert_callback', { callback_at: iso });
    setShowSchedule(false);
  }, [cbDate, cbTime, handleAction]);

  const handleComplete = useCallback(async () => {
    await handleAction('complete_callback');
  }, [handleAction]);

  const copyPhone = () => {
    navigator.clipboard.writeText(item.consumer_phone).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  const overdue = item.status === 'callback_needed' && isOverdue(item.callback_at);
  const outcomeDotClass = item.outcome === 'answered' ? 'inbox-outcome-answered'
    : item.outcome === 'missed' ? 'inbox-outcome-missed'
    : item.status === 'callback_needed' ? 'inbox-outcome-callback'
    : 'inbox-outcome-pending';

  return (
    <div className={`inbox-item ${overdue ? 'inbox-item-overdue' : ''}`}>
      <div className="inbox-item-header" onClick={() => setExpanded(v => !v)}>
        <div className="inbox-item-left">
          <span className={`inbox-outcome-dot ${outcomeDotClass}`} />
          <div className="inbox-item-info">
            <div className="inbox-item-name">
              {item.consumer_name || 'Unknown'}
              {item.bridge_confirmed && <span className="inbox-bridge-badge">BRIDGED</span>}
            </div>
            <div className="inbox-item-phone">{fmtPhone(item.consumer_phone)}</div>
            <div className="inbox-item-meta">
              <span className="inbox-item-time">{timeAgo(item.created_at)}</span>
              {item.direction && <span className="inbox-item-direction">{item.direction}</span>}
            </div>
          </div>
        </div>
        <div className="inbox-item-right">
          {item.status === 'callback_needed' && item.callback_at && (
            item.callback_completed_at
              ? <span className="inbox-cb-done"><Check size={12} /> Done</span>
              : <span className={`inbox-cb-badge ${overdue ? 'inbox-cb-overdue' : ''}`}>
                  <Calendar size={12} />
                  {overdue ? 'OVERDUE' : new Date(item.callback_at).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}
                </span>
          )}
          {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </div>
      </div>

      {expanded && (
        <div className="inbox-item-body">
          <div className="inbox-client-details">
            {item.consumer_address && (
              <div className="inbox-detail"><MapPin size={13} /><span>{item.consumer_address}</span></div>
            )}
            {item.consumer_home_value && (
              <div className="inbox-detail"><Home size={13} /><span>Home: {item.consumer_home_value}</span></div>
            )}
            {item.consumer_income_range && (
              <div className="inbox-detail"><DollarSign size={13} /><span>Income: {item.consumer_income_range}</span></div>
            )}
            {item.consumer_property_info && (
              <div className="inbox-detail"><FileText size={13} /><span>{item.consumer_property_info}</span></div>
            )}
            <div className="inbox-detail">
              <Phone size={13} />
              <span>{fmtPhone(item.consumer_phone)}</span>
              <button style={{ background: 'none', border: 'none', color: copied ? '#ef4444' : 'rgba(255,255,255,0.3)', cursor: 'pointer', padding: 0 }} onClick={copyPhone}>
                {copied ? <Check size={12} /> : <Copy size={12} />}
              </button>
            </div>
          </div>

          <div className="inbox-status-line">
            {STATUS_STEPS.map(step => (
              <span key={step} className={`inbox-status-step ${item[step] ? 'inbox-step-active' : ''}`}>
                {item[step] && <Check size={9} style={{ marginRight: 2 }} />}
                {step.replace(/_/g, ' ')}
              </span>
            ))}
          </div>

          {item.notes && <div className="inbox-notes"><FileText size={12} /> {item.notes}</div>}

          {item.recording_url && (
            <div className="inbox-recording">
              <RecordingPlayer url={item.recording_url} />
            </div>
          )}

          {item.transcript && (
            <div className="inbox-transcript"><FileText size={12} /><span>{item.transcript.slice(0, 300)}{item.transcript.length > 300 ? '...' : ''}</span></div>
          )}

          {error && (
            <div className="inbox-error">
              <AlertTriangle size={12} /><span>{error}</span>
              <button onClick={() => setError(null)}><X size={12} /></button>
            </div>
          )}

          <div className="inbox-actions">
            {(item.status === 'active' || !item.outcome) && (
              <>
                <textarea
                  className="inbox-notes-input"
                  placeholder="Notes..."
                  value={notes}
                  onChange={e => setNotes(e.target.value)}
                  rows={2}
                />
                <div className="inbox-action-btns">
                  <button className="inbox-btn inbox-btn-answered" disabled={submitting} onClick={() => handleAction('acknowledge_alert', { outcome: 'answered' })}>
                    {submitting ? <RefreshCw size={12} className="ica-spin" /> : <Phone size={12} />} Answered
                  </button>
                  <button className="inbox-btn inbox-btn-missed" disabled={submitting} onClick={() => handleAction('acknowledge_alert', { outcome: 'missed' })}>
                    <PhoneOff size={12} /> Missed
                  </button>
                  <button className="inbox-btn inbox-btn-callback" disabled={submitting} onClick={() => setShowSchedule(v => !v)}>
                    <Clock size={12} /> Callback
                  </button>
                </div>
              </>
            )}

            {item.status === 'callback_needed' && !item.callback_completed_at && (
              <div className="inbox-action-btns">
                <button className="inbox-btn inbox-btn-complete" disabled={submitting} onClick={handleComplete}>
                  <Check size={12} /> Complete Callback
                </button>
                <button className="inbox-btn inbox-btn-reschedule" disabled={submitting} onClick={() => setShowSchedule(v => !v)}>
                  <Calendar size={12} /> Reschedule
                </button>
              </div>
            )}

            {showSchedule && (
              <div className="inbox-schedule-form">
                <input type="date" className="inbox-input" value={cbDate} onChange={e => setCbDate(e.target.value)} />
                <input type="time" className="inbox-input" value={cbTime} onChange={e => setCbTime(e.target.value)} />
                <button className="inbox-btn-schedule" disabled={submitting || !cbDate || !cbTime} onClick={handleSchedule}>
                  {submitting ? <RefreshCw size={12} className="ica-spin" /> : <Calendar size={12} />} Schedule
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export function AgentInbox({ sessionToken, onUnauthorized, providerUrl }: AgentInboxProps) {
  const [items, setItems] = useState<InboxItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<string>('all');
  const [search, setSearch] = useState('');
  const refreshTimer = useRef<ReturnType<typeof setInterval> | null>(null);

  const load = useCallback(async () => {
    const result = await authFetch(providerUrl, {
      body: { action: 'get_agent_inbox', session_token: sessionToken, category: tab, limit: 50, offset: 0 },
      onUnauthorized,
    });
    if (result.ok && result.data) {
      const d = result.data as Record<string, unknown>;
      setItems((d.items || d.inbox || []) as InboxItem[]);
    }
    setLoading(false);
  }, [providerUrl, sessionToken, tab, onUnauthorized]);

  useEffect(() => {
    setLoading(true);
    load();
    refreshTimer.current = setInterval(load, 15000);
    return () => { if (refreshTimer.current) clearInterval(refreshTimer.current); };
  }, [load]);

  const filtered = search
    ? items.filter(i =>
        i.consumer_name?.toLowerCase().includes(search.toLowerCase()) ||
        i.consumer_phone?.includes(search)
      )
    : items;

  return (
    <div className="agent-inbox">
      <div className="inbox-header">
        <div className="inbox-header-left">
          <Inbox size={18} />
          <h3>Transfer Inbox</h3>
          {items.length > 0 && <span className="inbox-total-badge">{items.length}</span>}
        </div>
        <button className="inbox-refresh" onClick={() => { setLoading(true); load(); }} title="Refresh">
          <RefreshCw size={16} className={loading ? 'ica-spin' : ''} />
        </button>
      </div>

      <div className="inbox-tabs">
        {TABS.map(t => (
          <button key={t.id} className={`inbox-tab ${tab === t.id ? 'inbox-tab-active' : ''}`} onClick={() => setTab(t.id)}>
            {t.label}
          </button>
        ))}
      </div>

      <div className="inbox-search">
        <Search size={14} />
        <input placeholder="Search by name or phone..." value={search} onChange={e => setSearch(e.target.value)} />
        {search && <button onClick={() => setSearch('')}><X size={14} /></button>}
      </div>

      <div className="inbox-list">
        {filtered.length === 0 && !loading && (
          <div className="inbox-empty">
            <Inbox size={32} />
            <span>{search ? 'No results match your search' : 'No items in this category'}</span>
          </div>
        )}
        {loading && filtered.length === 0 && (
          <div className="inbox-empty">
            <RefreshCw size={24} className="ica-spin" />
            <span>Loading...</span>
          </div>
        )}
        {filtered.map(item => (
          <InboxItemCard
            key={item.id}
            item={item}
            providerUrl={providerUrl}
            sessionToken={sessionToken}
            onUnauthorized={onUnauthorized}
            onRefresh={load}
          />
        ))}
      </div>
    </div>
  );
}

src/components/AgentWorkspaceView.tsx:
import { useState, useCallback, useEffect, useRef } from 'react';
import {
  ChevronDown, ChevronRight, Clock, Flame, Phone, Send, Check, Bookmark,
  RefreshCw, AlertTriangle, Calendar, Radio, Archive, Mail,
} from 'lucide-react';
import { StatusPill, queueToPillVariant } from '@/components/StatusPill';
import { RecordingPlayer } from '@/components/RecordingPlayer';
import { formatPhone } from '@/utils/privacy';
import { authFetch } from '@/utils/auth-fetch';

// ── Types ──────────────────────────────────────────────────────────────
export type WorkspaceCall = {
  id: string; consumer_name: string; consumer_phone: string;
  consumer_address?: string; consumer_home_value?: string;
  consumer_income_range?: string; consumer_property_info?: string;
  consumer_custom_fields?: Record<string, unknown> | null;
  queue: string; transfer_status?: string;
  duration_seconds: number; ai_summary?: string; transcript?: string;
  recording_url?: string; is_completed?: boolean; created_at: string;
  call_direction?: string; callback_requested?: boolean;
  agent_disposition?: string; agent_notes?: string;
  transfer_failure_reason?: string; drop_reason?: string;
  talkroute_answered?: boolean; bridge_confirmed?: boolean;
  talkroute_voicemail?: boolean;
  originating_bland_number?: string; talkroute_destination?: string;
  day_label?: string;
};

export type WorkspaceData = {
  live_now: WorkspaceCall[];
  today_completed: WorkspaceCall[];
  yesterday: WorkspaceCall[];
  archive_page: WorkspaceCall[];
  archive_total: number;
  alerts: {
    stale_in_live: number; phone_only_pct: number;
    no_recording_pct: number; talkroute_no_answer: number;
    answer_no_bridge: number;
  };
  stats: Record<string, number>;
  boundaries: { timezone: string; today_start: string; yesterday_start: string; server_now: string };
};

export type WorkspaceTab = 'today' | 'yesterday' | 'archive';
export type OutcomeFilter = 'all' | 'transfers' | 'humans' | 'bridges' | 'callbacks' | 'failed';

export interface AgentWorkspaceViewProps {
  providerUrl: string;
  sessionToken: string;
  onUnauthorized: () => void;
  expandedCall: string | null;
  setExpandedCall: (id: string | null) => void;
  onPhoneClick: (name: string, phone: string) => void;
  onSaveTransfer?: (callId: string) => void;
  savingTransferIds?: Set<string>;
  selectedRedialIds: Set<string>;
  onToggleSelect: (id: string) => void;
  onRedial: () => void;
  redialing: boolean;
  redialBatchId: string | null;
  redialTranscripts: { consumer_name: string; transcript: string; status: string }[];
  onCloseRedialPanel: () => void;
}

const TZ = 'America/New_York';
function fmtTimeET(iso: string): string { return new Date(iso).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: TZ }); }
function fmtDur(s: number): string { if (!s || s < 1) return '--'; const m = Math.floor(s / 60); const sec = s % 60; return m > 0 ? `${m}:${String(sec).padStart(2, '0')}` : `${sec}s`; }
function initials(name: string): string { if (!name) return '?'; return name.split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase(); }

function matchesFilter(call: WorkspaceCall, filter: OutcomeFilter): boolean {
  if (filter === 'all') return true;
  if (filter === 'transfers') return call.queue === 'fire_transfer' || call.queue === 'human_drop';
  if (filter === 'humans') return call.queue === 'human_drop';
  if (filter === 'bridges') return call.bridge_confirmed === true;
  if (filter === 'callbacks') return call.callback_requested === true;
  if (filter === 'failed') return !!call.transfer_failure_reason || !!call.drop_reason;
  return true;
}

/* ── Call Card ─────────────────────────────────────────────────────── */
function CallBadges({ call, isLive }: { call: WorkspaceCall; isLive?: boolean }) {
  return (
    <div className="ws-badges">
      {isLive && <span className="ws-badge ws-badge-live">LIVE</span>}
      {call.queue === 'fire_transfer' && <span className="ws-badge ws-badge-fire">TRANSFER</span>}
      {call.queue === 'human_drop' && <span className="ws-badge ws-badge-human">HUMAN</span>}
      {call.queue === 'voice_message' && <span className="ws-badge ws-badge-vm">VM</span>}
      {call.queue === 'no_answer' && <span className="ws-badge ws-badge-na">NO ANS</span>}
      {call.bridge_confirmed && <span className="ws-badge ws-badge-bridge">BRIDGED</span>}
      {call.talkroute_voicemail && <span className="ws-badge ws-badge-trvm">AGENT VOICEMAIL</span>}
      {call.callback_requested && <span className="ws-badge ws-badge-cb">CALLBACK</span>}
      {call.transfer_failure_reason && <span className="ws-badge ws-badge-fail">FAILED</span>}
      {call.is_completed && !isLive && <span className="ws-badge ws-badge-done">DONE</span>}
    </div>
  );
}

function CallRow({ call, expanded, onToggle, onPhoneClick, onSave, saving, selectable, selected, onToggleSelect, isLive, sessionToken, onUnauthorized }: {
  call: WorkspaceCall; expanded: boolean; onToggle: () => void;
  onPhoneClick: (n: string, p: string) => void;
  onSave?: (id: string) => void; saving?: boolean;
  selectable?: boolean; selected?: boolean; onToggleSelect?: () => void;
  isLive?: boolean; sessionToken: string; onUnauthorized: () => void;
}) {
  const isHot = call.queue === 'fire_transfer' || call.queue === 'human_drop';
  return (
    <div className={`ws-call-card${isLive ? ' ws-live-card' : ''}${isHot ? ' ws-hot-card' : ''}${selected ? ' ws-selected' : ''}`}>
      <div className="ws-call-header" onClick={onToggle}>
        {selectable && (
          <button className={`ws-check${selected ? ' ws-checked' : ''}`}
            onClick={e => { e.stopPropagation(); onToggleSelect?.(); }}>
            {selected && <Check size={12} />}
          </button>
        )}
        <div className={`ws-avatar${isHot ? ' ws-avatar-hot' : ''}`}>{initials(call.consumer_name)}</div>
        <div className="ws-call-info">
          <div className="ws-call-name">{call.consumer_name || formatPhone(call.consumer_phone)}</div>
          <div className="ws-call-meta">
            <button className="ws-phone-link" onClick={e => { e.stopPropagation(); onPhoneClick(call.consumer_name, call.consumer_phone); }}>
              <Phone size={10} /> {formatPhone(call.consumer_phone)}
            </button>
            <span className="ws-call-time">{fmtTimeET(call.created_at)}</span>
          </div>
          {call.consumer_custom_fields && typeof call.consumer_custom_fields === 'object' && 'email' in call.consumer_custom_fields && Boolean(call.consumer_custom_fields.email) && (
            <div className="ws-call-email"><Mail size={10} /> {String(call.consumer_custom_fields.email).split(';')[0].trim()}</div>
          )}
        </div>
        <div className="ws-call-right">
          <CallBadges call={call} isLive={isLive} />
          <span className="ws-dur">{fmtDur(call.duration_seconds)}</span>
          {isHot && onSave && (
            <button className="ws-save-btn" onClick={e => { e.stopPropagation(); onSave(call.id); }} disabled={saving}>
              {saving ? <RefreshCw size={11} className="ws-spin" /> : <Bookmark size={11} />}
            </button>
          )}
          {isHot && (
            <button className="ws-elizabeth-btn" onClick={e => { e.stopPropagation(); onPhoneClick(call.consumer_name, call.consumer_phone); }}>
              <Send size={11} />
            </button>
          )}
          <ChevronDown size={14} className={expanded ? 'ws-chev-up' : ''} />
        </div>
      </div>
      {expanded && (
        <div className="ws-call-detail">
          {call.consumer_custom_fields && typeof call.consumer_custom_fields === 'object' && 'email' in call.consumer_custom_fields && Boolean(call.consumer_custom_fields.email) && (
            <div className="ws-detail-row ws-detail-email"><Mail size={12} /><span>All Emails</span><strong>{String(call.consumer_custom_fields.email)}</strong></div>
          )}
          {call.consumer_address && <div className="ws-detail-row"><span>Address</span><strong>{call.consumer_address}</strong></div>}
          {call.consumer_income_range && <div className="ws-detail-row"><span>Income</span><strong>{call.consumer_income_range}</strong></div>}
          {call.consumer_home_value && <div className="ws-detail-row"><span>Home Value</span><strong>{call.consumer_home_value}</strong></div>}
          {call.consumer_property_info && <div className="ws-detail-row"><span>Property</span><strong>{call.consumer_property_info}</strong></div>}
          {call.transfer_status && call.transfer_status !== 'none' && <div className="ws-detail-row"><span>Transfer</span><StatusPill variant={queueToPillVariant(call.transfer_status)}>{call.transfer_status.replace(/_/g, ' ')}</StatusPill></div>}
          {call.callback_requested && <div className="ws-detail-row"><span>Callback</span><strong className="ws-cb-flag">Requested</strong></div>}
          {call.agent_notes && <div className="ws-detail-row"><span>Notes</span><strong>{call.agent_notes}</strong></div>}
          {call.agent_disposition && <div className="ws-detail-row"><span>Disposition</span><strong>{call.agent_disposition}</strong></div>}
          {call.transfer_failure_reason && <div className="ws-detail-row ws-detail-warn"><AlertTriangle size={12} /><span>Failure</span><strong>{call.transfer_failure_reason}</strong></div>}
          {call.ai_summary && <div className="ws-detail-section"><div className="ws-detail-label">AI SUMMARY</div><p>{call.ai_summary}</p></div>}
          {call.transcript && <div className="ws-detail-section"><div className="ws-detail-label">TRANSCRIPT</div><div className="ws-transcript">{call.transcript}</div></div>}
          <RecordingPlayer url={call.recording_url} callId={call.id} sessionToken={sessionToken} onUnauthorized={onUnauthorized} />
        </div>
      )}
    </div>
  );
}

/* ── Collapsible Bucket ───────────────────────────────────────────── */
function BucketSection({ title, icon, calls, filter, defaultOpen, expandedCall, setExpandedCall, onPhoneClick, onSave, savingIds, selectable, selectedIds, onToggleSelect, sessionToken, onUnauthorized, isLive }: {
  title: string; icon: React.ReactNode;
  calls: WorkspaceCall[]; filter: OutcomeFilter; defaultOpen?: boolean;
  expandedCall: string | null; setExpandedCall: (id: string | null) => void;
  onPhoneClick: (n: string, p: string) => void;
  onSave?: (id: string) => void; savingIds?: Set<string>;
  selectable?: boolean; selectedIds?: Set<string>; onToggleSelect?: (id: string) => void;
  sessionToken: string; onUnauthorized: () => void; isLive?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen ?? false);
  const filtered = calls.filter(c => matchesFilter(c, filter));
  if (calls.length === 0 && !isLive) return null;
  return (
    <div className={`ws-bucket${isLive ? ' ws-bucket-live' : ''}`}>
      <button className="ws-bucket-header" onClick={() => setOpen(!open)}>
        <div className="ws-bucket-left">{icon}<span className="ws-bucket-title">{title}</span><span className="ws-bucket-count">{filtered.length}</span></div>
        {open ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
      </button>
      {open && (
        <div className="ws-bucket-body">
          {filtered.length === 0 ? (
            <div className="ws-empty">{isLive ? 'No active calls right now.' : `No calls${filter !== 'all' ? ' matching filter' : ''}.`}</div>
          ) : filtered.map(call => (
            <CallRow key={call.id} call={call}
              expanded={expandedCall === call.id}
              onToggle={() => setExpandedCall(expandedCall === call.id ? null : call.id)}
              onPhoneClick={onPhoneClick}
              onSave={onSave} saving={savingIds?.has(call.id)}
              selectable={selectable && (call.queue === 'fire_transfer' || call.queue === 'human_drop')}
              selected={selectedIds?.has(call.id)} onToggleSelect={() => onToggleSelect?.(call.id)}
              isLive={isLive} sessionToken={sessionToken} onUnauthorized={onUnauthorized}
            />
          ))}
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   AgentWorkspaceView — main export
   ═══════════════════════════════════════════════════════════════════ */
export function AgentWorkspaceView({
  providerUrl, sessionToken, onUnauthorized,
  expandedCall, setExpandedCall, onPhoneClick,
  onSaveTransfer, savingTransferIds, selectedRedialIds, onToggleSelect,
  onRedial, redialing, redialBatchId, redialTranscripts, onCloseRedialPanel,
}: AgentWorkspaceViewProps) {

  const [data, setData] = useState<WorkspaceData | null>(null);
  const [loading, setLoading] = useState(true);
  const [archiveOffset, setArchiveOffset] = useState(0);
  const [activeTab, setActiveTab] = useState<WorkspaceTab>('today');
  const [outcomeFilter, setOutcomeFilter] = useState<OutcomeFilter>('all');
  const pollingRef = useRef(false);
  const archivePollingRef = useRef(false);
  const mountedRef = useRef(true);

  const fetchWorkspace = useCallback(async (offset: number, isArchiveOnly?: boolean) => {
    const ref = isArchiveOnly ? archivePollingRef : pollingRef;
    if (ref.current) return;
    ref.current = true;
    try {
      const result = await authFetch(providerUrl, {
        body: { action: 'get_agent_workspace', session_token: sessionToken, archive_offset: offset },
        onUnauthorized,
      });
      if (result.ok && result.data && mountedRef.current) {
        setData(result.data as WorkspaceData);
        setLoading(false);
      }
    } catch { /* authFetch handles 401 */ }
    finally { ref.current = false; }
  }, [providerUrl, sessionToken, onUnauthorized]);

  // Live + today: 3s refresh
  useEffect(() => {
    mountedRef.current = true;
    fetchWorkspace(archiveOffset);
    const fast = setInterval(() => fetchWorkspace(archiveOffset), 3000);
    return () => { mountedRef.current = false; clearInterval(fast); };
  }, [fetchWorkspace, archiveOffset]);

  const handleArchivePage = (newOffset: number) => {
    setArchiveOffset(newOffset);
    fetchWorkspace(newOffset, true);
  };

  if (!data) {
    return loading ? (
      <div className="ws-loading"><RefreshCw size={20} className="ws-spin" /> Loading workspace...</div>
    ) : null;
  }

  const stats = data.stats;
  const alerts = data.alerts;

  const hasAlerts = alerts && (alerts.stale_in_live > 0 || alerts.talkroute_no_answer > 3 || alerts.answer_no_bridge > 0 || alerts.no_recording_pct > 60);

  const tabs: { key: WorkspaceTab; label: string; count: number }[] = [
    { key: 'today', label: 'Today', count: data.live_now.length + data.today_completed.length },
    { key: 'yesterday', label: 'Yesterday', count: data.yesterday.length },
    { key: 'archive', label: 'Archive', count: data.archive_total },
  ];

  const filters: { key: OutcomeFilter; label: string }[] = [
    { key: 'all', label: 'All' },
    { key: 'transfers', label: 'Transfers' },
    { key: 'bridges', label: 'Bridges' },
    { key: 'callbacks', label: 'Callbacks' },
    { key: 'failed', label: 'Failed' },
  ];

  return (
    <div className="ws-container">
      {/* Stats strip */}
      <div className="ws-stat-strip">
        <div className="ws-stat ws-stat-hot"><Radio size={14} /><strong>{stats?.active_calls_now ?? 0}</strong><span>ACTIVE NOW</span></div>
        <div className="ws-stat"><Flame size={14} /><strong>{stats?.fire_transfers ?? 0}</strong><span>TRANSFERS</span></div>
        <div className="ws-stat"><Phone size={14} /><strong>{stats?.live_humans ?? 0}</strong><span>HUMANS</span></div>
        <div className="ws-stat"><strong>{stats?.bridges_today ?? 0}</strong><span>BRIDGES</span></div>
        <div className="ws-stat"><strong>{stats?.today_total ?? 0}</strong><span>TOTAL TODAY</span></div>
      </div>

      {/* Redial bar */}
      {selectedRedialIds.size > 0 && (
        <div className="ws-redial-bar">
          <span>{selectedRedialIds.size} of 3 selected for power dial</span>
          <button className="ws-redial-btn" onClick={onRedial} disabled={redialing}>
            {redialing ? <><RefreshCw size={13} className="ws-spin" /> Dialing...</> : <><Phone size={13} /> Power Dial</>}
          </button>
        </div>
      )}

      {/* Redial transcript panel */}
      {redialBatchId && redialTranscripts.length > 0 && (
        <div className="ws-redial-results">
          <div className="ws-redial-results-header">
            <strong>Power Dial Results</strong>
            <button onClick={onCloseRedialPanel}>&times;</button>
          </div>
          {redialTranscripts.map((t, i) => (
            <div key={i} className="ws-redial-result-row">
              <span className="ws-redial-name">{t.consumer_name}</span>
              <span className={`ws-badge ws-badge-${t.status === 'completed' ? 'done' : 'na'}`}>{t.status}</span>
              {t.transcript && <p className="ws-redial-transcript">{t.transcript.slice(0, 200)}</p>}
            </div>
          ))}
        </div>
      )}

      {/* Alerts */}
      {hasAlerts && (
        <div className="ws-alerts">
          <AlertTriangle size={14} />
          <div className="ws-alerts-list">
            {alerts.stale_in_live > 0 && <span>{alerts.stale_in_live} stale call{alerts.stale_in_live > 1 ? 's' : ''} stuck in live queue</span>}
            {alerts.talkroute_no_answer > 3 && <span>{alerts.talkroute_no_answer} Zadarma calls unanswered today</span>}
            {alerts.answer_no_bridge > 0 && <span>{alerts.answer_no_bridge} answered but not bridged</span>}
            {alerts.no_recording_pct > 60 && <span>{Math.round(alerts.no_recording_pct)}% of calls missing recordings</span>}
          </div>
        </div>
      )}

      {/* LIVE NOW -- always visible at top */}
      <BucketSection
        title="LIVE NOW" icon={<Radio size={14} className="ws-pulse" />}
        calls={data.live_now} filter={outcomeFilter}
        defaultOpen={true} isLive
        expandedCall={expandedCall} setExpandedCall={setExpandedCall}
        onPhoneClick={onPhoneClick} onSave={onSaveTransfer} savingIds={savingTransferIds}
        selectable selectedIds={selectedRedialIds} onToggleSelect={onToggleSelect}
        sessionToken={sessionToken} onUnauthorized={onUnauthorized}
      />

      {/* Tab bar */}
      <div className="ws-tab-bar">
        <div className="ws-tabs">
          {tabs.map(t => (
            <button key={t.key} className={`ws-tab${activeTab === t.key ? ' ws-tab-active' : ''}`}
              onClick={() => setActiveTab(t.key)}>
              {t.label} <span className="ws-tab-count">{t.count}</span>
            </button>
          ))}
        </div>
        <div className="ws-filters">
          {filters.map(f => (
            <button key={f.key} className={`ws-filter${outcomeFilter === f.key ? ' ws-filter-active' : ''}`}
              onClick={() => setOutcomeFilter(f.key)}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Tab content */}
      {activeTab === 'today' && (
        <BucketSection
          title="TODAY COMPLETED" icon={<Clock size={14} />}
          calls={data.today_completed} filter={outcomeFilter}
          defaultOpen={true}
          expandedCall={expandedCall} setExpandedCall={setExpandedCall}
          onPhoneClick={onPhoneClick} onSave={onSaveTransfer} savingIds={savingTransferIds}
          selectable selectedIds={selectedRedialIds} onToggleSelect={onToggleSelect}
          sessionToken={sessionToken} onUnauthorized={onUnauthorized}
        />
      )}

      {activeTab === 'yesterday' && (
        <BucketSection
          title="YESTERDAY" icon={<Calendar size={14} />}
          calls={data.yesterday} filter={outcomeFilter}
          defaultOpen={true}
          expandedCall={expandedCall} setExpandedCall={setExpandedCall}
          onPhoneClick={onPhoneClick}
          sessionToken={sessionToken} onUnauthorized={onUnauthorized}
        />
      )}

      {activeTab === 'archive' && (
        <div className="ws-archive-section">
          <div className="ws-archive-info"><Archive size={13} /> Showing {Math.min(data.archive_page.length, 50)} of {data.archive_total} older calls</div>
          {data.archive_page.length === 0 ? (
            <div className="ws-empty">No archived calls.</div>
          ) : data.archive_page.map(call => (
            <CallRow key={call.id} call={call}
              expanded={expandedCall === call.id}
              onToggle={() => setExpandedCall(expandedCall === call.id ? null : call.id)}
              onPhoneClick={onPhoneClick} sessionToken={sessionToken} onUnauthorized={onUnauthorized}
            />
          ))}
          {data.archive_total > 50 && (
            <div className="ws-archive-pager">
              {archiveOffset > 0 && <button className="ws-page-btn" onClick={() => handleArchivePage(archiveOffset - 50)}>Previous</button>}
              {archiveOffset + 50 < data.archive_total && <button className="ws-page-btn" onClick={() => handleArchivePage(archiveOffset + 50)}>Next 50</button>}
            </div>
          )}
        </div>
      )}

      <div className="ws-tz-footer">All times Eastern ({data.boundaries?.timezone || TZ})</div>
    </div>
  );
}

