.ip17-shell {
  position: fixed;
  right: 22px;
  bottom: 18px;
  width: 375px;
  max-height: calc(100vh - 36px);
  z-index: 1200;
  background: #000000;
  color: #f5f5f7;
  border-radius: 48px;
  border: 3px solid #2a2a2e;
