    0 8px 30px rgba(0,0,0,.5),
    inset 0 1px 0 rgba(255,255,255,.05);
  overflow: hidden;
  font-size: 13px;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, sans-serif;
  display: flex;
