.ip17-enable { display: flex; align-items: center; justify-content: center; gap: 8px; margin: 10px auto; border: 0; border-radius: 20px; padding: 12px 20px; background: #34c759; color: #06140b; font-weight: 700; cursor: pointer; }
.ip17-enable:disabled { opacity: .5; cursor: wait; }
.ip17-answer-row { display: flex; align-items: center; justify-content: center; gap: 28px; margin-top: 20px; }
.ip17-answer-row .ip17-hangup-btn { margin: 0; }
.ip17-caller-detail { font-size: 13px; line-height: 1.5; color: #c7c7cc; white-space: pre-wrap; overflow-wrap: anywhere; max-height: 130px; overflow: auto; }
.ip17-tabs{display:flex;gap:5px;margin:12px 16px 6px;padding:4px;border-radius:12px;background:#17171a}.ip17-tabs button{flex:1;border:0;border-radius:8px;background:transparent;color:#a6a6ae;padding:10px;cursor:pointer;font:inherit}.ip17-tabs button[aria-current=page]{background:#303035;color:#fff}.ip17-voicemail{padding:8px 19px 28px;min-height:300px;max-height:510px;overflow:auto}.ip17-voicemail header{display:flex;align-items:center;justify-content:space-between}.ip17-voicemail h3{font-size:25px;margin:10px 0}.ip17-voicemail button{background:#232326;border:0;border-radius:8px;padding:9px;color:#84e8af;display:inline-flex;align-items:center;gap:6px;cursor:pointer}.ip17-voicemail button:disabled{opacity:.4;cursor:default}.ip17-vm-help{color:#a5a5af;font-size:12px;line-height:1.5}.ip17-vm-setup{color:#e8c484;font-size:12px;line-height:1.5;background:#302818;border-radius:10px;padding:12px}.ip17-vm-empty{text-align:center;padding:40px 12px;color:#8e8e95}.ip17-vm-empty svg{margin:auto}.ip17-voicemail article{padding:15px 0;border-top:1px solid #28282c}.ip17-voicemail article>div:first-child{display:flex;flex-direction:column;gap:5px}.ip17-voicemail article.unheard strong:before{content:'●';font-size:9px;color:#54c1ff;margin-right:6px}.ip17-voicemail time,.ip17-voicemail small{font-size:11px;color:#9c9ca3}.ip17-vm-actions{display:flex;gap:10px;justify-content:space-between;margin-top:10px}.ip17-voicemail audio{width:100%;margin-top:12px;height:36px}
