/* ─── Closed: just the floating trigger button ─── */
.ip17-shell.ip17-closed {
  width: 68px;
  height: 68px;
  max-height: 68px;
  border-radius: 50%;
  border: 2px solid #34c759;
  background: radial-gradient(circle at 40% 35%, #0d2818, #000 75%);
  box-shadow:
    0 0 20px rgba(52,199,89,.25),
    0 0 60px rgba(52,199,89,.1),
    0 8px 30px rgba(0,0,0,.6);
  cursor: pointer;
  animation: ip17-glow-idle 3s ease-in-out infinite;
}

.ip17-shell.ip17-closed:hover {
  border-color: #5bdb7d;
  box-shadow:
    0 0 30px rgba(52,199,89,.4),
    0 0 80px rgba(52,199,89,.15),
    0 8px 30px rgba(0,0,0,.6);
