.ip17-trigger-waves span:nth-child(1) { height: 5px; animation-delay: 0s; }
.ip17-trigger-waves span:nth-child(2) { height: 8px; animation-delay: .15s; }
.ip17-trigger-waves span:nth-child(3) { height: 12px; animation-delay: .3s; }

