.ip17-trigger-sip-dot.offline { background: #636366; }

/* ─── Ringing state on full phone ─── */
.ip17-shell.ip17-ringing:not(.ip17-closed) {
  animation: ip17-ring-glow 1.5s ease-in-out infinite;
  border-color: #34c759;
}

@keyframes ip17-ring-glow {
  0%, 100% { box-shadow: 0 0 0 1px #1a1a1e, 0 25px 80px rgba(0,0,0,.7), 0 0 30px rgba(52,199,89,.15); }
  50% { box-shadow: 0 0 0 1px #1a1a1e, 0 25px 80px rgba(0,0,0,.7), 0 0 60px rgba(52,199,89,.35); }
}

.ip17-shell button, .ip17-shell input {
  font: inherit;
  color: inherit;
  border: none;
  background: none;
  cursor: pointer;
  outline: none;
}

.ip17-shell .ip17-enable { background: #34c759; color: #06140b; font-weight: 700; }
.ip17-mic-status { display: flex; align-items: center; justify-content: center; gap: 5px; color: #a1d8af; font-size: 11px; margin: 6px 0; }
.ip17-mode-notice a { color: #8cf2be; text-decoration: underline; }

/* ─── Dynamic Island ─── */
.ip17-island {
  display: flex;
  justify-content: center;
  padding: 10px 20px 6px;
  cursor: pointer;
  flex-shrink: 0;
}

.ip17-island-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #1c1c1e;
  padding: 8px 16px;
  border-radius: 22px;
  min-width: 160px;
  justify-content: center;
  transition: all .2s ease;
}

.ip17-island-pill:hover { background: #2c2c2e; }

.ip17-island-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  transition: background .3s;
}

.ip17-island-dot.connected { background: #34c759; box-shadow: 0 0 8px rgba(52,199,89,.5); }
.ip17-island-dot.connecting { background: #ff9f0a; animation: ip17-dot-pulse 1.2s infinite; }
.ip17-island-dot.callback { background: #0a84ff; box-shadow: 0 0 8px rgba(10,132,255,.5); }
.ip17-island-dot.offline { background: #636366; }

@keyframes ip17-dot-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

.ip17-island-label {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -.2px;
  white-space: nowrap;
}

.ip17-island-wave {
  width: 20px;
  height: 12px;
  background: repeating-linear-gradient(90deg, #34c759 0 2px, transparent 2px 5px);
  border-radius: 2px;
  animation: ip17-wave .8s ease-in-out infinite alternate;
}

@keyframes ip17-wave {
  0% { transform: scaleY(.5); }
  100% { transform: scaleY(1); }
}

.ip17-island-close {
  color: #636366;
  display: flex;
  align-items: center;
  padding: 2px;
  transition: color .15s;
}

.ip17-island-close:hover { color: #f5f5f7; }

/* ─── Body ─── */
.ip17-body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding-bottom: 30px;
}

/* ─── Status Bar ─── */
.ip17-statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 24px 10px;
  font-size: 11px;
}

.ip17-sip-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .3px;
  text-transform: uppercase;
}

.ip17-sip-badge.connected { background: #0a2a12; color: #34c759; }
.ip17-sip-badge.connecting { background: #2a1a00; color: #ff9f0a; }
.ip17-sip-badge.callback { background: #0a1a2a; color: #0a84ff; }
.ip17-sip-badge.offline { background: #1c1c1e; color: #636366; }

.ip17-my-line {
  color: #8e8e93;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

/* ─── Debug Log Toggle ─── */
.ip17-log-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px 6px;
}

.ip17-log-toggle > button:first-child {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  color: #636366;
  transition: color .15s;
}

.ip17-log-toggle > button:first-child:hover { color: #8e8e93; }

.ip17-reconnect {
  font-size: 10px;
  font-weight: 600;
  color: #0a84ff;
  padding: 2px 8px;
  border-radius: 6px;
  background: rgba(10,132,255,.12);
  transition: background .15s;
}

.ip17-reconnect:hover { background: rgba(10,132,255,.22); }

/* ─── Debug Log Panel ─── */
.ip17-debug-log {
  max-height: 120px;
  overflow-y: auto;
  margin: 0 16px 8px;
  padding: 8px;
  background: #0c0c0e;
  border: 1px solid #1c1c1e;
  border-radius: 10px;
  font-family: 'SF Mono', 'Menlo', 'Consolas', monospace;
  font-size: 9px;
  line-height: 1.6;
}

.ip17-log-line {
  color: #8e8e93;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ip17-debug-log::-webkit-scrollbar { width: 3px; }
.ip17-debug-log::-webkit-scrollbar-track { background: transparent; }
.ip17-debug-log::-webkit-scrollbar-thumb { background: #3a3a3c; border-radius: 2px; }

/* ─── Incoming Call ─── */
.ip17-incoming {
  padding: 40px 24px 30px;
  text-align: center;
}

.ip17-avatar-ring {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, #1a3a1a 0%, #0a2a12 100%);
  border: 2px solid #34c759;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: #34c759;
  animation: ip17-avatar-pulse 1.5s ease-in-out infinite;
}

@keyframes ip17-avatar-pulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(52,199,89,.3); }
  50% { transform: scale(1.05); box-shadow: 0 0 0 16px rgba(52,199,89,0); }
}

.ip17-caller {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -.3px;
  margin: 0 0 4px;
}

.ip17-caller-num {
  color: #8e8e93;
  font-size: 15px;
  margin: 0 0 32px;
  font-variant-numeric: tabular-nums;
}

.ip17-incoming-btns {
  display: flex;
  gap: 48px;
  justify-content: center;
}

.ip17-circle-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.ip17-circle-btn > :first-child {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform .15s, box-shadow .15s;
}

.ip17-circle-btn.accept > :first-child {
  background: #34c759;
  color: #fff;
  box-shadow: 0 4px 20px rgba(52,199,89,.35);
}

.ip17-circle-btn.decline > :first-child {
  background: #ff3b30;
  color: #fff;
  box-shadow: 0 4px 20px rgba(255,59,48,.35);
}

.ip17-circle-btn:hover > :first-child { transform: scale(1.08); }

.ip17-circle-btn span {
  font-size: 12px;
  color: #8e8e93;
  font-weight: 500;
}

/* ─── Active Call ─── */
.ip17-active {
  padding: 24px 24px 16px;
  text-align: center;
}

.ip17-active-header { margin-bottom: 24px; }

.ip17-timer {
  font-size: 15px;
  color: #8e8e93;
  font-variant-numeric: tabular-nums;
  letter-spacing: .5px;
  margin-top: 4px;
}

/* ─── Mode Notice ─── */
.ip17-mode-notice {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 0 16px 8px;
  padding: 10px 12px;
  background: #0a1a2a;
  border: 1px solid #1a3a5a;
  border-radius: 12px;
  font-size: 11px;
  line-height: 1.5;
  color: #8eb8e0;
}

.ip17-mode-notice svg { flex-shrink: 0; color: #0a84ff; margin-top: 1px; }

.ip17-mode-notice button {
  margin-top: 6px;
  font-size: 10px;
  font-weight: 600;
  color: #0a84ff;
  white-space: nowrap;
}

.ip17-mode-notice button:hover { text-decoration: underline; }

.ip17-callback-notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 12px 0;
  padding: 12px 14px;
  border-radius: 10px;
  background: #0a1a2a;
  border: 1px solid #1a3a5a;
  color: #8eb8e0;
  font-size: 12px;
  line-height: 1.5;
}
.ip17-callback-notice p { margin: 0; }

.ip17-callback-badge {
  display: inline-block;
  margin-top: 6px;
  padding: 3px 10px;
  border-radius: 8px;
  background: #0a1a2a;
  color: #0a84ff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .5px;
}

.ip17-hold-badge {
  display: inline-block;
  margin-top: 8px;
  padding: 4px 12px;
  border-radius: 8px;
  background: #2a1a00;
  color: #ff9f0a;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .5px;
  animation: ip17-dot-pulse 1.5s infinite;
}

.ip17-call-controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.ip17-ctrl-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 8px;
  border-radius: 16px;
  background: #1c1c1e;
  transition: all .15s ease;
}

.ip17-ctrl-btn:hover { background: #2c2c2e; }
.ip17-ctrl-btn.active { background: #f5f5f7; color: #000; }
.ip17-ctrl-btn span { font-size: 11px; font-weight: 500; opacity: .7; }

.ip17-dtmf-pad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  padding: 0 16px 16px;
}

.ip17-dtmf-key {
  height: 40px;
  border-radius: 10px;
  background: #1c1c1e;
  font-size: 18px;
  font-weight: 400;
  color: #f5f5f7;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .1s, transform .1s;
}

.ip17-dtmf-key:active { background: #0a84ff; transform: scale(.93); }

.ip17-hangup-btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #ff3b30;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 8px auto 0;
  box-shadow: 0 4px 20px rgba(255,59,48,.35);
  transition: transform .15s;
}

.ip17-hangup-btn:hover { transform: scale(1.08); }

/* ─── Idle State ─── */
.ip17-idle { padding: 0 8px; }

.ip17-display {
  position: relative;
  padding: 16px 24px 8px;
  text-align: center;
}

.ip17-display input {
  width: 100%;
  text-align: center;
  font-size: 30px;
  font-weight: 300;
  letter-spacing: 2px;
  color: #f5f5f7;
  background: transparent;
  caret-color: #0a84ff;
  padding: 8px 0;
}

.ip17-display input::placeholder { color: #3a3a3c; font-weight: 300; }

.ip17-backspace {
  position: absolute;
  right: 24px;
  top: 50%;
  transform: translateY(-50%);
  color: #636366;
  padding: 8px;
  border-radius: 50%;
  transition: color .15s;
}

.ip17-backspace:hover { color: #f5f5f7; }

.ip17-dialpad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 4px 20px 12px;
}

.ip17-key {
  height: 60px;
  border-radius: 50%;
  background: #1c1c1e;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: background .12s, transform .1s;
}

.ip17-key:active { background: #48484a; transform: scale(.92); }

.ip17-key-digit { font-size: 24px; font-weight: 400; line-height: 1; }

.ip17-key-sub {
  font-size: 9px;
  letter-spacing: 2px;
  color: #8e8e93;
  margin-top: -1px;
  font-weight: 500;
}

.ip17-dial-row {
  display: flex;
  justify-content: center;
  padding: 4px 0 16px;
}

.ip17-dial-btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #34c759;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 20px rgba(52,199,89,.35);
  transition: transform .15s, box-shadow .15s;
}

.ip17-dial-btn:hover:not(:disabled) {
  transform: scale(1.08);
  box-shadow: 0 4px 28px rgba(52,199,89,.5);
}

.ip17-dial-btn:disabled {
  opacity: .3;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

.ip17-notice {
  padding: 12px 24px;
  text-align: center;
  color: #636366;
  font-size: 12px;
  line-height: 1.5;
}

/* ─── Recents ─── */
.ip17-recent {
  padding: 8px 16px 4px;
  border-top: 1px solid #1c1c1e;
  max-height: 180px;
  overflow-y: auto;
}

.ip17-recent-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #636366;
  font-weight: 600;
  margin-bottom: 6px;
}

.ip17-recent-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 4px;
  border-radius: 10px;
  transition: background .12s;
}

.ip17-recent-row:hover { background: #1c1c1e; }

.ip17-recent-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #1c1c1e;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ip17-recent-icon.outgoing { color: #0a84ff; }
.ip17-recent-icon.incoming { color: #34c759; }
.ip17-recent-icon.missed { color: #ff3b30; }

.ip17-recent-info { flex: 1; min-width: 0; }

.ip17-recent-info strong {
  display: block;
  font-weight: 500;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ip17-recent-info time { font-size: 10px; color: #636366; }

.ip17-callback {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #1c1c1e;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #34c759;
  flex-shrink: 0;
  transition: all .15s;
}

.ip17-callback:hover { background: #0a2a12; transform: scale(1.1); }

/* ─── Error ─── */
.ip17-error {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 24px;
  font-size: 12px;
  color: #ff453a;
  background: #1a0a0a;
  text-align: center;
}

.ip17-error button { color: #636366; font-size: 16px; padding: 0 4px; }

/* ─── Audio Recovery Banner ─── */
.ip17-audio-recovery {
  padding: 10px 20px 12px;
  background: #1a1400;
  border-bottom: 1px solid #3a3000;
  text-align: center;
}

.ip17-audio-status-msg {
  margin: 0 0 10px;
  font-size: 12px;
  line-height: 1.5;
  color: #e0c060;
}

.ip17-audio-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  margin: 0 auto;
  padding: 14px 20px;
  border: 0;
  border-radius: 14px;
  background: #ff9f0a;
  color: #1a0e00;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s, transform .1s;
}

.ip17-audio-btn:hover:not(:disabled) { background: #ffb340; transform: scale(1.02); }
.ip17-audio-btn:active:not(:disabled) { transform: scale(.97); }
.ip17-audio-btn:disabled { opacity: .6; cursor: wait; }
.ip17-audio-btn:focus-visible { outline: 2px solid #ffb340; outline-offset: 2px; }

.ip17-ctrl-warn { background: #2a1a00 !important; color: #ff9f0a !important; }
.ip17-ctrl-warn span { color: #ff9f0a !important; opacity: 1 !important; }

/* ─── Health status row ─── */
.ip17-health-row {
  display: flex;
  justify-content: center;
  gap: 6px;
  padding: 0 20px 8px;
}
.ip17-health-chip {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 8px;
  letter-spacing: .2px;
}
.ip17-health-chip.ok { background: #0a2a12; color: #34c759; }
.ip17-health-chip.err { background: #2a0a0a; color: #ff453a; }

/* ─── Audio tools row (test speaker, mic enable) ─── */
.ip17-audio-tools {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 4px 20px 8px;
}
.ip17-test-spk {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 16px;
  border: 1px solid #3a3a3c;
  border-radius: 12px;
  background: #1c1c1e;
  color: #e5e5ea;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}
.ip17-test-spk:hover:not(:disabled) { background: #2c2c2e; border-color: #4a4a4e; }
.ip17-test-spk:disabled { opacity: .5; cursor: wait; }
.ip17-enable-sm { padding: 8px 16px; font-size: 12px; margin: 0; }

/* ─── Ringtone enable button during ringing ─── */
.ip17-ring-enable {
  margin: 12px auto;
  max-width: 280px;
  font-size: 13px;
  padding: 12px 16px;
}

/* ─── Bottom home indicator ─── */
.ip17-body::after {
  content: '';
  display: block;
  width: 134px;
  height: 5px;
  background: #3a3a3c;
  border-radius: 3px;
  margin: 8px auto 0;
}

/* ─── Spin animation ─── */
@keyframes ip17spin {
  to { transform: rotate(360deg); }
}
.ip17-spin { animation: ip17spin 1s linear infinite; }

/* ─── Callback section ─── */
.ip17-callback-section {
  padding: 12px 20px;
  border-top: 1px solid #2a2a2e;
}
.ip17-callback-title {
  font-size: 13px;
  font-weight: 600;
  color: #e5e5ea;
  margin: 0 0 4px;
}
.ip17-callback-desc {
  font-size: 11px;
  color: #8e8e93;
  margin: 0 0 10px;
  line-height: 1.4;
}
.ip17-callback-row {
  display: flex;
  gap: 8px;
}
.ip17-callback-input {
  flex: 1;
  background: #1c1c1e;
  border: 1px solid #3a3a3c;
  border-radius: 10px;
  color: #e5e5ea;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
}
.ip17-callback-input:focus { border-color: #0a84ff; }
.ip17-callback-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #34c759;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: opacity 0.2s;
}
.ip17-callback-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.ip17-callback-msg {
  font-size: 11px;
  margin-top: 8px;
  text-align: center;
}
.ip17-callback-msg.success { color: #34c759; }

/* ─── Retry button ─── */
.ip17-retry-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 8px 20px;
  padding: 8px;
  border-radius: 10px;
  background: #1c1c1e;
  border: 1px solid #3a3a3c;
  color: #0a84ff;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s;
}
.ip17-retry-btn:hover { background: #2c2c2e; }

/* ─── Responsive ─── */
@media (max-width: 600px) {
  .ip17-shell {
    right: 8px;
    bottom: 8px;
    width: calc(100% - 16px);
    max-width: 375px;
    border-radius: 40px;
  }
  .ip17-shell.ip17-closed {
    width: 60px;
    height: 60px;
    max-height: 60px;
  }
}

/* ─── Scrollbar ─── */
.ip17-body::-webkit-scrollbar { width: 3px; }
.ip17-body::-webkit-scrollbar-track { background: transparent; }
.ip17-body::-webkit-scrollbar-thumb { background: #3a3a3c; border-radius: 2px; }
.ip17-recent::-webkit-scrollbar { width: 3px; }
.ip17-recent::-webkit-scrollbar-track { background: transparent; }
.ip17-recent::-webkit-scrollbar-thumb { background: #3a3a3c; border-radius: 2px; }

