import { useCallback, useEffect, useRef, useState } from 'react';
import { Phone, PhoneOff, PhoneOutgoing, PhoneIncoming, RotateCcw, X, Delete, Mic, MicOff, Volume2, VolumeX, Grid3X3, Pause, Play } from 'lucide-react';
import { formatPhone } from '@/utils/privacy';
import { authFetch } from '@/utils/auth-fetch';
import { normalizeDialNumber, type PhoneState } from '@/phone/call-controller';
import { PHONE_DIAL_EVENT, type PhoneDialRequest } from '@/phone/dial-request';
import { usePhonePresence } from '@/phone/use-phone-presence';
import './IPhone.css';
import { PhoneVoicemail } from './PhoneVoicemail';
import { PhoneActivity, usePhoneActivityCount } from './PhoneActivity';
import { useVoicemailCount } from '@/phone/useVoicemailCount';

interface IPhoneProps { agentName: string; sessionToken: string; providerUrl: string; onUnauthorized: () => void }
interface RouteData { talkroute_number?: string; zadarma_number?: string; zadarma_sip_login?: string }
interface Caller { name?: string; phone?: string; address?: string; summary?: string; transcript?: string; fields?: Record<string, unknown> }
interface RecentCall { number: string; name?: string; direction: 'outgoing' | 'incoming' | 'missed'; time: Date }
type Connection = 'idle' | 'connecting' | 'ready' | 'failed';
type AudioStatus = 'ok' | 'sound-blocked' | 'mic-denied' | 'mic-missing' | 'mic-in-use' | 'sender-ended' | 'unknown';

interface WolfPhone {
  unlockAudio: () => void;
  enableSound: () => void;
  restoreMicTrack: () => Promise<{ ok: boolean; error?: string }>;
  getMicSenderState: () => { hasConnection: boolean; hasSender: boolean; trackState: string | null };
  getRemoteStreamState: () => { hasSrcObject: boolean; trackCount: number; liveTrackCount: number; muted: boolean; paused: boolean };
  startRingtone: () => void;
  stopRingtone: () => void;
  testSpeaker: () => void;
  setOutputDevice: (deviceId: string) => Promise<boolean>;
}

const CHANNEL = 'wolf-zadarma-v1';
const CALLING_URL = 'https://wolf-of-wall-street-ssy3.bolt.host/';
const KEYS = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'];
const LETTERS = ['', 'ABC', 'DEF', 'GHI', 'JKL', 'MNO', 'PQRS', 'TUV', 'WXYZ', '', '+', ''];
const duration = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;

function audioStatusMessage(status: AudioStatus): string {
  if (status === 'sound-blocked') return 'Browser is blocking audio playback. Click the button below. If sound still does not work, check that this site is allowed to play sound and use the microphone in your browser settings (click the lock icon in the address bar).';
  if (status === 'mic-denied') return 'Microphone access was denied. Click the lock or site-settings icon in your browser address bar, allow Microphone, then click the button below.';
  if (status === 'mic-missing') return 'No microphone found. Connect a headset or microphone and click the button below.';
  if (status === 'mic-in-use') return 'Your microphone is being used by another app. Close that app and click the button below.';
  if (status === 'sender-ended') return 'Your outgoing audio stopped. Click the button below to restore it without dropping the call.';
  if (status === 'unknown') return 'An audio problem occurred. Click the button below to try again.';
  return '';
}

const HAS_SET_SINK_ID = typeof HTMLMediaElement !== 'undefined' && 'setSinkId' in HTMLMediaElement.prototype;

export function IPhone({ agentName, sessionToken, providerUrl, onUnauthorized }: IPhoneProps) {
  const [open, setOpen] = useState(true);
  const [view, setView] = useState<'keypad' | 'voicemail' | 'activity'>('keypad');
  const unreadVoicemails = useVoicemailCount(sessionToken, providerUrl);
  const unreadActivity = usePhoneActivityCount(sessionToken, providerUrl);
  const [route, setRoute] = useState<RouteData | null>(null);
  const [routeLoading, setRouteLoading] = useState(false);
  const [connection, setConnection] = useState<Connection>('idle');
  const [callState, setCallState] = useState<PhoneState>('idle');
  const [digits, setDigits] = useState('');
  const [callNumber, setCallNumber] = useState('');
  const [caller, setCaller] = useState<Caller | null>(null);
  const [seconds, setSeconds] = useState(0);
  const [muted, setMuted] = useState(false);
  const [held, setHeld] = useState(false);
  const [speakerOff, setSpeakerOff] = useState(false);
  const [showDtmf, setShowDtmf] = useState(false);
  const [error, setError] = useState('');
  const [micGranted, setMicGranted] = useState(false);
  const [audioStatus, setAudioStatus] = useState<AudioStatus>('ok');
  const [enablingSound, setEnablingSound] = useState(false);
  const [testingSpk, setTestingSpk] = useState(false);
  const [frameVersion, setFrameVersion] = useState(0);
  const [frameReady, setFrameReady] = useState(false);
  const [recents, setRecents] = useState<RecentCall[]>([]);
  const frameRef = useRef<HTMLIFrameElement>(null);
  const unauthorizedRef = useRef(onUnauthorized); unauthorizedRef.current = onUnauthorized;
  const startingRef = useRef(false);
  const automaticRecoveryUsedRef = useRef(false);
  const pendingCallRef = useRef(false);
  const pendingRequestRef = useRef<PhoneDialRequest | null>(null);
  const dialGenerationRef = useRef(0);
  const callRef = useRef<{ number: string; name?: string; direction: 'incoming' | 'outgoing'; answered: boolean } | null>(null);
  const lookupSequence = useRef(0);
  const stateRef = useRef(callState); stateRef.current = callState;
  const credentialsRef = useRef<{ key: string; sip: string } | null>(null);
  const phoneIdentityRef = useRef(0);
  const connectionRef = useRef(connection); connectionRef.current = connection;
  const companionOnly = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const inPreview = window.location.hostname !== 'wolf-of-wall-street-ssy3.bolt.host';
  const presenceError = usePhonePresence(providerUrl, sessionToken, {
    connection_state: connection, call_state: callState, microphone_granted: micGranted,
    device_kind: companionOnly ? 'companion' : 'desktop',
  }, () => unauthorizedRef.current());

  const getPhone = useCallback((): (Window & { wolfPhone?: WolfPhone }) | null => {
    return frameRef.current?.contentWindow as (Window & { wolfPhone?: WolfPhone }) | null;
  }, []);

  useEffect(() => {
    let permission: PermissionStatus | undefined;
    let disposed = false;
    const changed = () => { if (permission?.state !== 'granted') setMicGranted(false); };
    if (navigator.permissions) void navigator.permissions.query({ name: 'microphone' as PermissionName }).then(value => {
      if (disposed) return;
      permission = value; permission.addEventListener('change', changed);
      if (permission.state === 'denied') changed();
    }).catch(() => {});
    return () => { disposed = true; permission?.removeEventListener('change', changed); };
  }, []);

  const command = useCallback((cmd: string, extra: Record<string, unknown> = {}) => {
    frameRef.current?.contentWindow?.postMessage({ channel: CHANNEL, command: cmd, ...extra }, window.location.origin);
  }, []);

  const unlockAudio = useCallback(() => {
    getPhone()?.wolfPhone?.unlockAudio();
  }, [getPhone]);

  const requestMic = useCallback(async (): Promise<{ granted: boolean; error?: string; errorName?: string }> => {
    const identity = phoneIdentityRef.current;
    try {
      if (!window.isSecureContext || !navigator.mediaDevices?.getUserMedia) {
        return { granted: false, error: 'Open the published HTTPS website to use the microphone.', errorName: 'insecure' };
      }
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(track => track.stop());
      if (identity !== phoneIdentityRef.current) return { granted: false };
      setMicGranted(true);
      return { granted: true };
    } catch (e) {
      if (identity !== phoneIdentityRef.current) return { granted: false };
      setMicGranted(false);
      const name = e instanceof Error ? e.name : '';
      const message = name === 'NotAllowedError'
        ? window.self !== window.top ? 'Open the calling app in its own tab, then allow microphone access.' : 'Microphone access is blocked. Allow it in this website\'s browser settings, then retry.'
        : name === 'NotFoundError' ? 'No microphone was found. Connect a microphone or headset, then retry.'
        : name === 'NotReadableError' ? 'Your microphone is being used by another app. Close it, then retry.'
        : e instanceof Error ? e.message : 'The microphone is unavailable.';
      return { granted: false, error: message, errorName: name };
    }
  }, []);

  const enableSound = useCallback(async () => {
    setEnablingSound(true);
    try {
      const phone = getPhone();
      // Synchronous in click activation: play/resume in both frames
      phone?.wolfPhone?.enableSound();
      phone?.wolfPhone?.unlockAudio();
      const ACtx = typeof AudioContext !== 'undefined' ? AudioContext : (window as any).webkitAudioContext as typeof AudioContext | undefined;
      if (ACtx) { try { const ctx = new ACtx(); void ctx.resume().then(() => ctx.close()).catch(() => {}); } catch {} }

      if (!micGranted) {
        const mic = await requestMic();
        if (!mic.granted && mic.error) {
          const status: AudioStatus = mic.errorName === 'NotAllowedError' ? 'mic-denied'
            : mic.errorName === 'NotFoundError' ? 'mic-missing'
            : mic.errorName === 'NotReadableError' ? 'mic-in-use' : 'unknown';
          setAudioStatus(status);
          return;
        }
      }

      if (stateRef.current === 'active') {
        const senderState = phone?.wolfPhone?.getMicSenderState();
        if (senderState?.hasConnection && senderState.hasSender && senderState.trackState !== 'live') {
          const result = await phone!.wolfPhone!.restoreMicTrack();
          if (!result.ok) {
            const status: AudioStatus = result.error === 'mic-denied' ? 'mic-denied'
              : result.error === 'mic-missing' ? 'mic-missing'
              : result.error === 'mic-in-use' ? 'mic-in-use' : 'sender-ended';
            setAudioStatus(status);
            return;
          }
        }
      }

      setAudioStatus('ok');
    } finally {
      setEnablingSound(false);
    }
  }, [micGranted, requestMic, getPhone]);

  const testSpeaker = useCallback(() => {
    setTestingSpk(true);
    getPhone()?.wolfPhone?.testSpeaker();
    setTimeout(() => setTestingSpk(false), 2500);
  }, [getPhone]);

  const loadRoute = useCallback(async (signal?: AbortSignal) => {
    const identity = phoneIdentityRef.current;
    setRouteLoading(true);
    const result = await authFetch<{ route: RouteData }>(providerUrl, {
      body: { action: 'get_federal_one_v2', session_token: sessionToken }, signal,
      onUnauthorized: () => unauthorizedRef.current(),
    });
    if (signal?.aborted || identity !== phoneIdentityRef.current) return null;
    setRouteLoading(false);
    if (result.ok && result.data?.route) { setRoute(result.data.route); return result.data.route; }
    setError(result.error || 'Could not load phone settings. Retry phone setup.');
    return null;
  }, [providerUrl, sessionToken]);

  useEffect(() => {
    const abort = new AbortController();
    setRoute(null);
    void loadRoute(abort.signal);
    return () => {
      abort.abort(); phoneIdentityRef.current++; dialGenerationRef.current++; credentialsRef.current = null;
      pendingRequestRef.current?.respond({ status: 'cancelled', error: 'The phone session changed. Please sign in again.' });
      pendingRequestRef.current = null; pendingCallRef.current = false;
    };
  }, [loadRoute]);

  const lookupCaller = useCallback(async (phone: string) => {
    const sequence = ++lookupSequence.current;
    const result = await authFetch<{ caller: Caller | null }>(providerUrl, {
      body: { action: 'zadarma_caller_context', session_token: sessionToken, phone },
      onUnauthorized: () => unauthorizedRef.current(),
    });
    if (sequence === lookupSequence.current && result.ok && result.data?.caller) setCaller(result.data.caller);
  }, [providerUrl, sessionToken]);

  useEffect(() => {
    const receive = (event: MessageEvent) => {
      if (event.origin !== window.location.origin || event.source !== frameRef.current?.contentWindow || event.data?.channel !== CHANNEL) return;
      const data = event.data;
      if (data.type === 'frame-ready') setFrameReady(true);
      if (data.type === 'connection') {
        setConnection(data.state); startingRef.current = data.state === 'connecting';
        if (data.state === 'ready') setError(previous => previous.startsWith('Call did not connect') ? previous : '');
      }
      if (data.type === 'audio-blocked') { setAudioStatus('sound-blocked'); }
      if (data.type === 'audio-recovered') { setAudioStatus('ok'); }
      if (data.type === 'error') {
        setError(String(data.message)); pendingCallRef.current = false;
        pendingRequestRef.current?.respond({ status: 'failed', error: String(data.message) });
        pendingRequestRef.current = null;
      }
      const request = pendingRequestRef.current;
      if (data.type === 'dial-result' && request && request.requestId === data.requestId) {
        pendingRequestRef.current = null;
        request.respond(data.accepted ? { status: 'requested' } : { status: 'failed', error: String(data.message || 'The phone rejected the call request.') });
        if (!data.accepted) pendingCallRef.current = false;
      }
      if (data.type === 'incoming' || data.type === 'outgoing') {
        const number = String(data.number || 'Unknown caller');
        const name = typeof data.name === 'string' ? data.name : undefined;
        callRef.current = { number, name, direction: data.type === 'incoming' ? 'incoming' : 'outgoing', answered: false };
        // When a callback-dial is pending, the incoming ring is from Zadarma
        // calling our extension back. Auto-answer it and treat as outgoing.
        if (data.type === 'incoming' && callbackDialRef.current) {
          callbackDialRef.current = false;
          clearTimeout(callbackTimerRef.current);
          const dialedNumber = callbackNumberRef.current || number;
          callRef.current = { number: dialedNumber, direction: 'outgoing', answered: false };
          setCallNumber(dialedNumber); setOpen(true); setView('keypad');
          unlockAudio();
          // Delay auto-answer slightly so the SIP session fully establishes
          // before the SDK processes the answer request.
          setTimeout(() => command('answer'), 800);
          return;
        }
        setCallNumber(number); setCaller(name ? { name } : null); setOpen(true); setView('keypad');
        void lookupCaller(number);
      }
      if (data.type === 'call-state') {
        const next = data.state as PhoneState;
        stateRef.current = next; setCallState(next);
        if (next === 'active' && callRef.current) callRef.current.answered = true;
        if (next === 'idle') {
          pendingCallRef.current = false; lookupSequence.current++;
          callbackDialRef.current = false; clearTimeout(callbackTimerRef.current);
          const call = callRef.current;
          if (call) setRecents(previous => [{ number: call.number, name: call.name, time: new Date(), direction: call.direction === 'incoming' && !call.answered ? 'missed' as const : call.direction }, ...previous].slice(0, 20));
          callRef.current = null; setCaller(null); setCallNumber(''); setShowDtmf(false); setSpeakerOff(false); setSeconds(0);
          setAudioStatus('ok');
        }
      }
      if (data.type === 'controls') {
        if (typeof data.muted === 'boolean') setMuted(data.muted);
        if (typeof data.held === 'boolean') setHeld(data.held);
        if (typeof data.speakerOff === 'boolean') setSpeakerOff(data.speakerOff);
      }
    };
    window.addEventListener('message', receive);
    return () => window.removeEventListener('message', receive);
  }, [lookupCaller]);

  useEffect(() => {
    if (!frameReady || !credentialsRef.current) return;
    command('connect', credentialsRef.current);
  }, [frameReady, frameVersion, command]);

  useEffect(() => {
    if (callState !== 'active') return;
    const started = Date.now(); setSeconds(0);
    const timer = setInterval(() => setSeconds(Math.floor((Date.now() - started) / 1000)), 1000);
    return () => clearInterval(timer);
  }, [callState]);

  const enable = useCallback(async (automatic = false) => {
    if (companionOnly || startingRef.current || stateRef.current !== 'idle') return;
    const identity = phoneIdentityRef.current;
    if (!automatic) automaticRecoveryUsedRef.current = false;
    startingRef.current = true;
    if (!automatic) setError('');
    unlockAudio();
    const currentRoute = route?.zadarma_sip_login ? route : await loadRoute();
    if (identity !== phoneIdentityRef.current) return;
    if (!currentRoute?.zadarma_sip_login) {
      startingRef.current = false; setConnection('failed');
      if (currentRoute) setError('No phone extension is assigned. Ask your supervisor to check your phone assignment.');
      return;
    }
    const mic = await requestMic();
    if (!mic.granted) {
      startingRef.current = false;
      setConnection('failed');
      setError(mic.error || 'Microphone access is required.');
      return;
    }
    if (identity !== phoneIdentityRef.current) return;
    setConnection('connecting');
    const result = await authFetch<{ key: string; sip: string }>(providerUrl, {
      body: { action: 'zadarma_webrtc_key', session_token: sessionToken },
      onUnauthorized: () => unauthorizedRef.current(),
    });
    if (identity !== phoneIdentityRef.current) return;
    if (!result.ok || !result.data?.key) { startingRef.current = false; setConnection('failed'); setError(result.error || 'Zadarma authorization failed.'); return; }
    const reconnecting = credentialsRef.current !== null;
    credentialsRef.current = result.data;
    if (reconnecting) { setFrameReady(false); setFrameVersion(version => version + 1); }
    else if (frameReady) command('connect', result.data);
  }, [companionOnly, route, loadRoute, unlockAudio, requestMic, providerUrl, sessionToken, frameReady, command]);

  // A terminal incoming-call failure closes the old SDK transport. Renew the
  // phone once after it is idle so that one failed call cannot strand outbound
  // dialing. Never replay an Accept or Dial command and never loop on rejection.
  useEffect(() => {
    if (companionOnly || connection !== 'failed' || callState !== 'idle' ||
        !micGranted || !credentialsRef.current || automaticRecoveryUsedRef.current ||
        !error.startsWith('Call did not connect')) return;
    automaticRecoveryUsedRef.current = true;
    void enable(true);
  }, [companionOnly, connection, callState, micGranted, error, enable]);

  const callbackDialRef = useRef(false);
  const callbackNumberRef = useRef('');
  const callbackTimerRef = useRef<ReturnType<typeof setTimeout>>();

  const dial = useCallback(async (number: string, request?: PhoneDialRequest) => {
    setOpen(true); setView('keypad'); setError(''); unlockAudio();
    const reject = (message: string) => { setError(message); request?.respond({ status: 'failed', error: message }); };
    if (request?.signal.aborted) return;
    if (companionOnly) { reject('Use your desktop to make and receive calls.'); return; }
    if (connection !== 'ready') { setDigits(number); reject('Enable your phone and wait for Ready, then try again.'); return; }
    if (stateRef.current !== 'idle' || pendingCallRef.current) { reject('Finish the current call first.'); return; }
    const identity = phoneIdentityRef.current;
    const generation = ++dialGenerationRef.current;
    try {
      const normalized = normalizeDialNumber(number);
      pendingCallRef.current = true;
      if (request) {
        pendingRequestRef.current = request;
        request.signal.addEventListener('abort', () => {
          if (pendingRequestRef.current !== request) return;
          pendingRequestRef.current = null; pendingCallRef.current = false;
          dialGenerationRef.current++;
        }, { once: true });
      }
      const mic = await requestMic();
      if (identity !== phoneIdentityRef.current || generation !== dialGenerationRef.current) return;
      if (!mic.granted) {
        pendingCallRef.current = false; pendingRequestRef.current = null;
        reject(mic.error || 'Microphone access is required. Check the on-screen phone.');
        request?.respond({ status: 'failed', error: mic.error || 'Microphone access is required.' });
        return;
      }
      if (identity !== phoneIdentityRef.current || request?.signal.aborted || (request && Date.now() >= request.expiresAt)) {
        pendingCallRef.current = false;
        if (pendingRequestRef.current === request) pendingRequestRef.current = null;
        request?.respond({ status: 'cancelled', error: 'Call request expired or cancelled. Please try again.' });
        return;
      }
      if (stateRef.current !== 'idle') { pendingCallRef.current = false; pendingRequestRef.current = null; reject('Finish the current call first.'); return; }
      // Use server-side callback API for outbound calls. The Zadarma callback
      // rings this extension first, then connects to the destination. We auto-
      // answer the callback leg so the agent experience is seamless.
      callbackDialRef.current = true;
      callbackNumberRef.current = normalized;
      setCallNumber(normalized);
      setCaller(null);
      void lookupCaller(normalized);
      clearTimeout(callbackTimerRef.current);
      callbackTimerRef.current = setTimeout(() => {
        if (callbackDialRef.current) {
          callbackDialRef.current = false;
          pendingCallRef.current = false;
          setError('The call did not connect. Zadarma did not ring back in time. Try again.');
        }
      }, 20000);
      const result = await authFetch<{ ok: boolean; error?: string }>(providerUrl, {
        body: { action: 'zadarma_callback', session_token: sessionToken, to: normalized },
        onUnauthorized: () => unauthorizedRef.current(),
      });
      if (identity !== phoneIdentityRef.current || generation !== dialGenerationRef.current) return;
      if (!result.ok || !result.data?.ok) {
        callbackDialRef.current = false;
        clearTimeout(callbackTimerRef.current);
        pendingCallRef.current = false;
        if (pendingRequestRef.current === request) pendingRequestRef.current = null;
        reject(result.data?.error || result.error || 'The call could not be started. Try again.');
        return;
      }
      request?.respond({ status: 'requested' });
      if (pendingRequestRef.current === request) pendingRequestRef.current = null;
    } catch (e) {
      callbackDialRef.current = false;
      clearTimeout(callbackTimerRef.current);
      pendingCallRef.current = false;
      if (pendingRequestRef.current === request) pendingRequestRef.current = null;
      reject(e instanceof Error ? e.message : 'Invalid number.');
    }
  }, [companionOnly, connection, requestMic, unlockAudio, providerUrl, sessionToken, lookupCaller]);

  useEffect(() => {
    const handle = (event: Event) => {
      const detail = (event as CustomEvent<PhoneDialRequest>).detail;
      if (!event.defaultPrevented && detail?.phone && typeof detail.respond === 'function') {
        event.preventDefault();
        void dial(detail.phone, detail);
      }
    };
    window.addEventListener(PHONE_DIAL_EVENT, handle);
    return () => window.removeEventListener(PHONE_DIAL_EVENT, handle);
  }, [dial]);

  const answer = () => { unlockAudio(); command('answer'); };
  const status = connection === 'ready' ? 'Ready' : connection === 'connecting' ? 'Connecting\u2026' : connection === 'failed' ? 'Not connected' : 'Enable phone';
  const dot = connection === 'ready' ? 'connected' : connection === 'connecting' ? 'connecting' : 'offline';
  const myNumber = route?.zadarma_number || route?.talkroute_number;
  const active = callState !== 'idle';
  const showAudioBanner = audioStatus !== 'ok';
  const frame = !companionOnly && <iframe key={`${sessionToken.slice(-8)}-${frameVersion}`} ref={frameRef} src="/phone.html?build=424" title="Zadarma call connection" allow="microphone; autoplay" className="ip17-engine" />;

  // Separate status indicators
  const spkOk = audioStatus === 'ok' || audioStatus === 'mic-denied' || audioStatus === 'mic-missing' || audioStatus === 'mic-in-use';
  const micOk = micGranted && audioStatus !== 'mic-denied' && audioStatus !== 'mic-missing' && audioStatus !== 'mic-in-use';
  const connOk = connection === 'ready';

  return <>
    {frame}
    <aside className={`ip17-shell${!open ? ' ip17-closed' : ''}${callState === 'ringing-in' ? ' ip17-ringing' : ''}`} aria-label={`${agentName}'s Zadarma phone`}>
      {!open ? <button className="ip17-trigger" aria-label="Open phone" onClick={() => { unlockAudio(); setOpen(true); }}><Phone size={26} /><span className={`ip17-trigger-sip-dot ${dot}`} />{(unreadActivity + (unreadVoicemails || 0)) > 0 && <span className="ip17-vm-badge">{unreadActivity + (unreadVoicemails || 0)}</span>}</button> : <>
        <div className="ip17-island"><div className="ip17-island-pill"><div className={`ip17-island-dot ${dot}`} /><span className="ip17-island-label">{agentName.split(' ')[0]}'s Phone</span><button className="ip17-island-close" aria-label="Minimize phone" onClick={() => setOpen(false)}><X size={16} /></button></div></div>
        <div className="ip17-body">
          <div className="ip17-statusbar"><span className={`ip17-sip-badge ${dot}`}>{status} · Phone 424</span><span className="ip17-my-line">{myNumber ? formatPhone(myNumber) : 'No line assigned'}</span></div>

          {/* Separate status row: connection / speaker / mic */}
          {connection === 'ready' && <div className="ip17-health-row">
            <span className={`ip17-health-chip ${connOk ? 'ok' : 'err'}`}>Connection {connOk ? '\u2713' : '\u2717'}</span>
            <span className={`ip17-health-chip ${spkOk ? 'ok' : 'err'}`}>Speaker {spkOk ? '\u2713' : '\u2717'}</span>
            <span className={`ip17-health-chip ${micOk ? 'ok' : 'err'}`}>Mic {micOk ? '\u2713' : '\u2717'}</span>
          </div>}

          {error && <div className="ip17-error" role="alert">{error}<button aria-label="Dismiss phone error" onClick={() => setError('')}>{'\u00d7'}</button></div>}

          {showAudioBanner && <div className="ip17-audio-recovery" role="alert">
            <p className="ip17-audio-status-msg">{audioStatusMessage(audioStatus)}</p>
            <button className="ip17-audio-btn" disabled={enablingSound} onClick={() => void enableSound()}>
              <Volume2 size={20} />{enablingSound ? 'Restoring audio\u2026' : 'Enable microphone & sound'}
            </button>
            {!HAS_SET_SINK_ID && <p className="ip17-audio-hint">Your browser does not support output device selection. To change speakers, use your operating system sound settings (Windows: Sound settings; Mac: System Settings &gt; Sound &gt; Output).</p>}
          </div>}
          {presenceError && <div className="ip17-error" role="status">{presenceError}</div>}

          {!active && <nav className="ip17-tabs" aria-label="Phone views"><button aria-current={view === 'keypad' ? 'page' : undefined} onClick={() => setView('keypad')}>Keypad</button><button aria-current={view === 'activity' ? 'page' : undefined} onClick={() => setView('activity')}>Recents{unreadActivity > 0 && <span className="ip17-vm-badge">{unreadActivity}</span>}</button><button aria-current={view === 'voicemail' ? 'page' : undefined} onClick={() => setView('voicemail')}>Voicemail{unreadVoicemails != null && unreadVoicemails > 0 && <span className="ip17-vm-badge" aria-label={`${unreadVoicemails} unheard messages`}> {unreadVoicemails}</span>}</button></nav>}
          {view === 'activity' && !active ? <PhoneActivity sessionToken={sessionToken} providerUrl={providerUrl} onUnauthorized={onUnauthorized} canCall={!companionOnly && connection === 'ready'} onCall={number => void dial(number)} /> : view === 'voicemail' && !active ? <PhoneVoicemail sessionToken={sessionToken} providerUrl={providerUrl} onUnauthorized={onUnauthorized} canCall={!companionOnly && connection === 'ready'} onCall={number => void dial(number)} /> : companionOnly ? <div className="ip17-mode-notice">Your phone is for client information. Open this app on your desktop to take calls.</div> : <>
            {inPreview && !active && <div className="ip17-mode-notice">For calling and microphone access, <a href={CALLING_URL} target="_blank" rel="noopener noreferrer">open the calling app in its own tab</a>.</div>}
            {!active && connection !== 'ready' && <button className="ip17-enable" disabled={routeLoading || connection === 'connecting'} onClick={() => void enable()}><RotateCcw size={16} />{routeLoading ? 'Loading phone settings\u2026' : connection === 'connecting' ? 'Connecting\u2026' : !route ? 'Retry phone setup' : connection === 'failed' ? 'Retry connection' : 'Enable microphone & phone'}</button>}
            {/* Test speaker + mic status when idle and ready */}
            {!active && connection === 'ready' && <div className="ip17-audio-tools">
              <button className="ip17-test-spk" disabled={testingSpk} onClick={testSpeaker}><Volume2 size={14} />{testingSpk ? 'Playing\u2026' : 'Test speaker & ringtone'}</button>
              {!micGranted && audioStatus === 'ok' && <button className="ip17-enable ip17-enable-sm" onClick={() => { unlockAudio(); void requestMic(); }}><Mic size={14} />Enable microphone</button>}
              {micGranted && audioStatus === 'ok' && <span className="ip17-mic-status"><Mic size={13} />Microphone allowed</span>}
            </div>}
            {active ? <div className="ip17-active">
              <div className="ip17-active-header"><h3 className="ip17-caller">{caller?.name || formatPhone(callNumber)}</h3>{caller?.name && <p>{formatPhone(callNumber)}</p>}<p className="ip17-timer" aria-live="polite">{callState === 'ringing-in' ? 'Incoming call' : callState === 'dialing' ? 'Calling\u2026' : callState === 'answering' ? 'Connecting call\u2026' : callState === 'ending' ? 'Ending call\u2026' : `${held ? 'On hold \u00b7 ' : ''}${duration(seconds)}`}</p></div>
              {caller?.address && <p className="ip17-caller-detail">{caller.address}</p>}
              {caller?.summary && <p className="ip17-caller-detail">{caller.summary}</p>}
              {caller?.fields && Object.keys(caller.fields).length > 0 && <details className="ip17-caller-detail"><summary>Client details</summary>{Object.entries(caller.fields).map(([key, value]) => <p key={key}><strong>{key.replace(/_/g, ' ')}:</strong> {typeof value === 'object' ? JSON.stringify(value) : String(value ?? '')}</p>)}</details>}
              {caller?.transcript && <details className="ip17-caller-detail"><summary>AI conversation</summary><p>{caller.transcript}</p></details>}
              {/* Enable sound banner during ringing-in too */}
              {callState === 'ringing-in' && <button className="ip17-audio-btn ip17-ring-enable" onClick={() => void enableSound()} disabled={enablingSound}><Volume2 size={18} />{enablingSound ? 'Enabling\u2026' : 'Enable sound to hear ringtone & caller'}</button>}
              {callState === 'active' && <>
                <div className="ip17-call-controls">
                  <button className={`ip17-ctrl-btn${muted ? ' active' : ''}`} aria-pressed={muted} onClick={() => command('mute')}>{muted ? <MicOff size={22} /> : <Mic size={22} />}<span>{muted ? 'Unmute' : 'Mute'}</span></button>
                  <button className={`ip17-ctrl-btn${held ? ' active' : ''}`} aria-pressed={held} onClick={() => command('hold')}>{held ? <Play size={22} /> : <Pause size={22} />}<span>{held ? 'Resume' : 'Hold'}</span></button>
                  <button className={`ip17-ctrl-btn${speakerOff ? ' active' : ''}`} aria-pressed={speakerOff} onClick={() => command('speaker')}>{speakerOff ? <VolumeX size={22} /> : <Volume2 size={22} />}<span>{speakerOff ? 'Sound on' : 'Sound off'}</span></button>
                  <button className="ip17-ctrl-btn" onClick={() => setShowDtmf(value => !value)}><Grid3X3 size={22} /><span>Keypad</span></button>
                  <button className={`ip17-ctrl-btn${audioStatus !== 'ok' ? ' ip17-ctrl-warn' : ''}`} onClick={() => void enableSound()} disabled={enablingSound}><Volume2 size={22} /><span>{enablingSound ? 'Fixing\u2026' : 'Fix audio'}</span></button>
                </div>
                {showDtmf && <div className="ip17-dtmf-pad">{KEYS.map(key => <button key={key} className="ip17-dtmf-key" onClick={() => command('dtmf', { tone: key })}>{key}</button>)}</div>}
              </>}
              <div className="ip17-answer-row">{callState === 'ringing-in' && <button className="ip17-dial-btn" aria-label="Answer call" onClick={answer}><Phone size={28} /></button>}<button className="ip17-hangup-btn" disabled={callState === 'ending'} aria-label={callState === 'ringing-in' ? 'Decline call' : 'End call'} onClick={() => command('hangup')}><PhoneOff size={28} /></button></div>
            </div> : <>
              <div className="ip17-idle"><div className="ip17-display"><input aria-label="Number to call" value={digits} onChange={event => setDigits(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void dial(digits); }} placeholder="Enter number" type="tel" autoComplete="off" />{digits && <button className="ip17-backspace" aria-label="Delete digit" onClick={() => setDigits(value => value.slice(0, -1))}><Delete size={20} /></button>}</div>
                <div className="ip17-dialpad">{KEYS.map((key, index) => <button key={key} className="ip17-key" onClick={() => setDigits(value => value + key)}><span className="ip17-key-digit">{key}</span><span className="ip17-key-sub">{LETTERS[index]}</span></button>)}</div>
                <div className="ip17-dial-row"><button className="ip17-dial-btn" aria-label="Call number" disabled={connection !== 'ready' || !digits.trim()} onClick={() => void dial(digits)}><Phone size={28} /></button></div>
              </div>
              {recents.length > 0 && <div className="ip17-recent"><div className="ip17-recent-title">Recent calls</div>{recents.slice(0, 8).map((call, index) => <div className="ip17-recent-row" key={`${call.time.getTime()}-${index}`}><div className={`ip17-recent-icon ${call.direction}`}>{call.direction === 'outgoing' ? <PhoneOutgoing size={14} /> : call.direction === 'incoming' ? <PhoneIncoming size={14} /> : <PhoneOff size={14} />}</div><div className="ip17-recent-info"><strong>{call.name || formatPhone(call.number)}</strong><time>{call.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</time></div><button className="ip17-callback" aria-label={`Call back ${call.number}`} disabled={connection !== 'ready'} onClick={() => void dial(call.number)}><Phone size={14} /></button></div>)}</div>}
            </>}
          </>}
        </div>
      </>}
    </aside>
  </>;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { Clock, Radio, RefreshCw } from 'lucide-react';
import { authFetch } from '@/utils/auth-fetch';
import { currentInboundHealth, inboundRouteProblems, type InboundHealth } from '@/utils/inbound-health';

export interface InboundAgentConfig {
  id: string; full_name: string; bland_number: string; talkroute_number: string;
}
export interface InboundVerificationPanelProps {
  agents: InboundAgentConfig[]; providerUrl: string; sessionToken: string; onUnauthorized: () => void;
}

export function InboundVerificationPanel({ agents, providerUrl, sessionToken, onUnauthorized }: InboundVerificationPanelProps) {
  const [health, setHealth] = useState<InboundHealth | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const requestRef = useRef<AbortController | null>(null);
  const checkRoutes = useCallback(async () => {
    requestRef.current?.abort();
    const controller = new AbortController();
    requestRef.current = controller;
    setLoading(true); setError(''); setHealth(null);
    const result = await authFetch(providerUrl, {
      body: { action: 'inbound_health', session_token: sessionToken }, onUnauthorized, signal: controller.signal,
    });
    if (controller.signal.aborted) return;
    const checked = result.ok ? currentInboundHealth(result.data) : null;
    setHealth(checked);
    setError(checked ? '' : 'Current route verification is unavailable. Do not rely on saved configuration flags.');
    setLoading(false);
    requestRef.current = null;
  }, [providerUrl, sessionToken, onUnauthorized]);

  useEffect(() => {
    void checkRoutes();
    const interval = setInterval(() => void checkRoutes(), 60000);
    return () => { requestRef.current?.abort(); clearInterval(interval); };
  }, [checkRoutes]);

  return (
    <section className="panel inbound-verification-panel" aria-label="Live inbound and agent readiness">
      <div className="panel-heading">
        <div><div className="eyebrow"><Radio size={12} /> LIVE ROUTE CHECK</div><h3>Inbound routes & agent availability</h3></div>
        <button className="secondary-button" disabled={loading} onClick={() => void checkRoutes()}>
          <RefreshCw size={14} className={loading ? 'search-spinner' : ''} /> {loading ? 'Checking…' : 'Check live routes'}
        </button>
      </div>
      <div role="status" aria-live="polite">
        {error && <p>{error}</p>}
        {health && <p>{health.ready_agent_count} of {health.selected_agent_count} selected agents have campaign phone routes. Browser login is not required for active campaigns.
          {' '}{health.configuration_ready ? 'Selected routes pass the current provider checks.' : 'Selected routes need attention before opening.'}</p>}
        <div className="inbound-agent-list">
          {agents.map(agent => {
            const route = health?.results.find(r => r.agent_id === agent.id);
            const verified = route?.configuration_ready === true;
            const problems = route ? inboundRouteProblems(route) : [];
            return <div key={agent.id} className={'inbound-agent-row live-route-row ' + (verified ? 'configured' : 'not-configured')}>
              <span className="inbound-agent-name">{agent.full_name}</span>
              <span className="inbound-agent-route">{agent.bland_number ? `Bland ${agent.bland_number.slice(-4)}` : 'No inbound line'} → {agent.talkroute_number ? `Zadarma ${agent.talkroute_number.slice(-4)}` : 'No destination'}
                <br />{route ? (route.agent_ready ? 'Selected for campaign phone delivery' : 'Not selected or phone routing incomplete') : 'Availability not verified'}
                {problems.length > 0 && <><br />{problems.join(' · ')}</>}
              </span>
              <span className={'inbound-agent-badge ' + (verified ? 'configured' : 'not-configured')}>
                {verified ? 'Route verified' : route ? 'Needs repair' : loading ? 'Checking' : 'Not verified'}
              </span>
            </div>;
          })}
        </div>
        {health && <p>Provider checked {new Date(health.checked_at).toLocaleTimeString()}. Rechecks every minute; settings can change after a check.</p>}
      </div>
      <div className="inbound-evidence-notice"><div className="inbound-evidence-row pending">
        <Clock size={12} /><span><strong>Staffed phone test still required.</strong> Configuration checks do not prove ringing, pickup or two-way audio. Confirm an answered transfer through each agent's phone before normal volume.</span>
      </div></div>
    </section>
  );
}

