import { useState, useEffect, useCallback } from 'react';
import { RefreshCw, ChevronDown, ChevronUp, Activity } from 'lucide-react';
import { authFetch } from '@/utils/auth-fetch';

type QueueEntry = {
  queue: string;
  count: number;
  items?: Array<{
    id: string;
    consumer_name: string;
    phone: string;
    status: string;
    created_at: string;
  }>;
};

interface ProviderQueuePanelProps {
  providerUrl: string;
  sessionToken: string;
  onUnauthorized: () => void;
}

export function ProviderQueuePanel({ providerUrl, sessionToken, onUnauthorized }: ProviderQueuePanelProps) {
  const [queues, setQueues] = useState<QueueEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(false);

  const load = useCallback(async () => {
    const result = await authFetch(providerUrl, {
      body: { action: 'get_provider_queues', session_token: sessionToken },
      onUnauthorized,
    });
    if (result.ok && result.data) {
      const d = result.data as Record<string, unknown>;
      setQueues((d.queues || []) as QueueEntry[]);
    }
    setLoading(false);
  }, [providerUrl, sessionToken, onUnauthorized]);

  useEffect(() => {
    load();
    const t = setInterval(load, 15000);
    return () => clearInterval(t);
  }, [load]);

  const total = queues.reduce((s, q) => s + q.count, 0);

  return (
    <div style={{
      background: 'rgba(15,15,25,0.6)', border: '1px solid rgba(255,255,255,0.06)',
      borderRadius: 14, overflow: 'hidden', marginBottom: 12,
    }}>
      <div
        style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '12px 16px', cursor: 'pointer',
        }}
        onClick={() => setExpanded(v => !v)}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#fff', fontSize: 14, fontWeight: 600 }}>
          <Activity size={16} />
          <span>Provider Queues</span>
          {total > 0 && (
            <span style={{
              background: 'rgba(234,179,8,0.12)', color: '#eab308', fontSize: 11,
              fontWeight: 700, padding: '2px 8px', borderRadius: 99,
            }}>{total}</span>
          )}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'rgba(255,255,255,0.4)' }}>
          <button onClick={e => { e.stopPropagation(); setLoading(true); load(); }} style={{ background: 'none', border: 'none', color: 'inherit', cursor: 'pointer', padding: 4 }}>
            <RefreshCw size={14} className={loading ? 'ica-spin' : ''} />
          </button>
          {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </div>
      </div>
      {expanded && (
        <div style={{ padding: '0 16px 14px' }}>
          {queues.length === 0 ? (
            <div style={{ color: 'rgba(255,255,255,0.3)', fontSize: 13, textAlign: 'center', padding: 16 }}>
              {loading ? 'Loading...' : 'No active queues'}
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {queues.map(q => (
                <div key={q.queue} style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  padding: '8px 12px', background: 'rgba(255,255,255,0.03)', borderRadius: 8,
                  fontSize: 13, color: 'rgba(255,255,255,0.7)',
                }}>
                  <span style={{ textTransform: 'capitalize' }}>{q.queue.replace(/_/g, ' ')}</span>
                  <span style={{ fontWeight: 600, color: q.count > 0 ? '#eab308' : 'rgba(255,255,255,0.3)' }}>{q.count}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

src/components/RecordingPlayer.tsx:
import { useState, useRef, useCallback, useEffect } from 'react';
import { Volume2, VolumeX, RefreshCw } from 'lucide-react';
import { authFetch } from '@/utils/auth-fetch';

const SUPABASE_URL = (import.meta.env.VITE_SUPABASE_URL as string) ?? '';
const PROVIDER_URL = `${SUPABASE_URL}/functions/v1/wolf-provider`;

interface RecordingPlayerProps {
  url: string | null | undefined;
  callId?: string;
  recordingSource?: 'calls' | 'secretary_calls';
  sessionToken?: string;
  onUnauthorized?: () => void;
}

export function RecordingPlayer({ url, callId, recordingSource = 'calls', sessionToken, onUnauthorized }: RecordingPlayerProps) {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);
  const [recovering, setRecovering] = useState(false);
  const [recoveredUrl, setRecoveredUrl] = useState<string | null>(null);
  const [recoveredKey, setRecoveredKey] = useState<string | null>(null);
  const [recoveryFailed, setRecoveryFailed] = useState(false);
  const [recoveryMessage, setRecoveryMessage] = useState('');
  const attemptedRecovery = useRef(false);
  const recoveryRequest = useRef<AbortController | null>(null);
  const sourceKey = `${recordingSource}:${callId || ''}:${sessionToken || ''}:${url || ''}`;
  const activeKey = useRef<string | null>(sourceKey);
  activeKey.current = sourceKey;

  // Provider URLs require a server credential; the browser uses a short-lived
  // playback grant instead. Never send provider keys to the client.
  const directUrl = /^https:\/\/api\.bland\.ai(?:\/|$)/i.test(url || '') ? null : url;
  const activeUrl = (recoveredKey === sourceKey ? recoveredUrl : null) || directUrl;

  useEffect(() => {
    activeKey.current = sourceKey;
    attemptedRecovery.current = false;
    setRecoveredUrl(null);
    setRecoveredKey(null);
    setRecoveryFailed(false);
    setRecoveryMessage('');
    setError(false);
    setRecovering(false);
    setLoading(true);
    return () => { activeKey.current = null; recoveryRequest.current?.abort(); };
  }, [sourceKey]);

  const attemptRecovery = useCallback(async () => {
    if (attemptedRecovery.current || !callId || !sessionToken || recovering) return;
    attemptedRecovery.current = true;
    setRecovering(true);
    setError(false);
    setLoading(true);
    const controller = new AbortController();
    recoveryRequest.current = controller;

    try {
      const result = await authFetch<{ recording_url: string }>(PROVIDER_URL, {
        onUnauthorized: () => { if (activeKey.current === sourceKey) onUnauthorized?.(); },
        signal: controller.signal,
        timeoutMs: 90000,
        body: { action: 'recover_recording', session_token: sessionToken, call_id: callId, recording_source: recordingSource },
      });
      if (controller.signal.aborted || activeKey.current !== sourceKey) return;

      if (result.ok && result.data?.recording_url) {
        setError(false);
        setRecoveryFailed(false);
        setRecoveryMessage('');
        setRecoveredKey(sourceKey);
        setRecoveredUrl(result.data.recording_url);
      } else {
        setRecoveryMessage(result.error || 'Recording is unavailable from the provider.');
        setRecoveryFailed(true);
        setError(true);
        setLoading(false);
      }
    } catch {
      if (controller.signal.aborted || activeKey.current !== sourceKey) return;
      setRecoveryFailed(true);
      setError(true);
      setLoading(false);
    } finally {
      if (activeKey.current === sourceKey) setRecovering(false);
    }
  }, [callId, sessionToken, recordingSource, sourceKey, recovering, onUnauthorized]);

  useEffect(() => {
    if (!activeUrl && callId && sessionToken && !recoveryFailed && !attemptedRecovery.current && !recovering) {
      attemptRecovery();
    }
  }, [activeUrl, callId, sessionToken, recoveryFailed, recovering, attemptRecovery]);

  const handleAudioError = useCallback(() => {
    if (recovering) return;
    setLoading(false);
    if (!attemptedRecovery.current && callId && sessionToken) {
      attemptRecovery();
    } else {
      setError(true);
    }
  }, [callId, sessionToken, attemptRecovery, recovering]);

  const handleManualRetry = useCallback(() => {
    attemptedRecovery.current = false;
    setRecoveryFailed(false);
    setError(false);
    setRecoveredUrl(null);
    setLoading(true);
    attemptRecovery();
  }, [attemptRecovery]);

  if (!activeUrl && !callId) return null;

  if (!activeUrl && callId && sessionToken && !recoveryFailed && !error) {
    return (
      <div className="detail-section">
        <div className="detail-label">RECORDING</div>
        <div className="recording-loading">
          <RefreshCw size={14} className="search-spinner" />
          <span>Recovering audio...</span>
        </div>
      </div>
    );
  }

  if (error || (!activeUrl && recoveryFailed)) {
    return (
      <div className="detail-section">
        <div className="detail-label">RECORDING</div>
        <div className="recording-unavailable">
          <VolumeX size={14} />
          <span>{recoveryMessage || 'Recording not ready or unavailable. Retry after the call finishes.'}</span>
          {callId && sessionToken && (
            <button className="recording-retry-btn" onClick={handleManualRetry} disabled={recovering}>
              <RefreshCw size={12} className={recovering ? 'animate-spin' : ''} />
              Retry
            </button>
          )}
        </div>
      </div>
    );
  }

  if (!activeUrl) return null;

  return (
    <div className="detail-section">
      <div className="detail-label">RECORDING</div>
      <div className="recording-player-wrap">
        {(loading || recovering) && (
          <div className="recording-loading">
            <Volume2 size={14} className="search-spinner" />
            <span>{recovering ? 'Recovering audio...' : 'Loading audio...'}</span>
          </div>
        )}
        <audio
          key={activeUrl}
          controls
          preload="metadata"
          src={activeUrl}
          className="recording-audio"
          onLoadedMetadata={() => setLoading(false)}
          onCanPlay={() => setLoading(false)}
          onError={handleAudioError}
          style={{ width: '100%', display: 'block' }}
        />
      </div>
    </div>
  );
}

