/* ── Agent readiness summary (compact) ── */
.agent-readiness-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; margin-bottom: 20px; }
.agent-readiness-card { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border: 1px solid var(--border-subtle); border-radius: var(--radius-md); background: var(--ink-850); }
.agent-readiness-card .avatar { width: 32px; height: 32px; font-size: 10px; flex-shrink: 0; }
.agent-readiness-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.agent-readiness-info strong { font: 600 12px var(--font-sans); color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.agent-readiness-info span { font: 500 9px var(--font-mono); color: var(--text-muted); }
.agent-readiness-status { font: 700 9px var(--font-mono); padding: 3px 8px; border-radius: 3px; flex-shrink: 0; }
.agent-readiness-status.online { color: var(--sage-400); background: rgba(190, 242, 100, 0.08); border: 1px solid rgba(190, 242, 100, 0.2); }
.agent-readiness-status.offline { color: var(--text-muted); background: var(--ink-750); border: 1px solid var(--ink-600); }

/* ── Agent data-quality exception badge ── */
.agent-dq-badge {
  display: inline-flex; align-items: center; gap: 3px;
