/* ── Recent transfer failures (compact) ── */
.recent-failures-card { margin-bottom: 20px; }
.recent-failures-list { display: flex; flex-direction: column; gap: 6px; }
.recent-failure-row { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border: 1px solid rgba(236, 72, 153, 0.15); border-radius: var(--radius-sm); background: rgba(236, 72, 153, 0.03); font: 12px var(--font-sans); }
.recent-failure-row .privacy-masked { flex-shrink: 0; min-width: 90px; }
.recent-failure-reason { color: var(--rust-400); font: 500 11px var(--font-sans); flex: 1; }
.recent-failure-time { color: var(--text-muted); font: 500 10px var(--font-mono); flex-shrink: 0; }

/* ── Lead Pool Reconciled Breakdown ── */
.lead-pool-breakdown { margin-bottom: 20px; }
.lead-pool-total-row { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; flex-wrap: wrap; }
.lead-pool-total { flex-shrink: 0; min-width: 180px; }
.lead-pool-reconciliation-badge { font: 600 12px var(--font-sans); padding: 6px 14px; border-radius: 100px; }
.lead-pool-reconciliation-badge.reconciled { background: rgba(34, 139, 87, 0.12); color: var(--sage-400); border: 1px solid rgba(34, 139, 87, 0.25); }
.lead-pool-reconciliation-badge.mismatch { background: rgba(236, 72, 153, 0.12); color: var(--rust-400); border: 1px solid rgba(236, 72, 153, 0.25); }
.lead-pool-buckets { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }
.lead-bucket { padding: 16px 14px; border-radius: var(--radius-md); border: 1px solid var(--border-subtle); background: var(--surface-raised); display: flex; flex-direction: column; gap: 4px; transition: transform 0.15s ease, border-color 0.15s ease; }
.lead-bucket:hover { transform: translateY(-2px); border-color: var(--border-hover); }
.lead-bucket .bucket-label { font: 600 10px var(--font-sans); letter-spacing: 0.08em; color: var(--text-muted); text-transform: uppercase; }
.lead-bucket .bucket-value { font: 700 28px var(--font-mono); color: var(--text-primary); line-height: 1; }
.lead-bucket .bucket-hint { font: 400 10px var(--font-sans); color: var(--text-faint); }
.lead-bucket.fresh { border-left: 3px solid var(--sage-400); }
.lead-bucket.called { border-left: 3px solid var(--steel-400); }
.lead-bucket.suppressed { border-left: 3px solid var(--rust-400); }
.lead-bucket.invalid { border-left: 3px solid #c4972e; }
.lead-bucket.excluded { border-left: 3px solid var(--gold-400); }
.lead-bucket.unclassified { border-left: 3px solid var(--text-faint); }
@media (max-width: 760px) { .lead-pool-buckets { grid-template-columns: repeat(2, 1fr); } }

/* ── Talkroute Delivery Timeline ── */
.delivery-timeline-panel { margin-bottom: 20px; }
.delivery-timeline-track { display: flex; align-items: center; gap: 0; padding: 20px 0 16px; overflow-x: auto; }
