.delivery-stage.confirmed { border-color: rgba(34, 139, 87, 0.3); background: rgba(34, 139, 87, 0.04); }
.delivery-stage.failed { border-color: rgba(236, 72, 153, 0.3); background: rgba(236, 72, 153, 0.04); }
.delivery-stage.pending { border-color: rgba(226, 188, 109, 0.3); background: rgba(226, 188, 109, 0.04); }
