.delivery-stage-icon { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.delivery-stage.confirmed .delivery-stage-icon { background: rgba(34, 139, 87, 0.15); color: var(--sage-400); }
.delivery-stage.failed .delivery-stage-icon { background: rgba(236, 72, 153, 0.15); color: var(--rust-400); }
.delivery-stage.pending .delivery-stage-icon { background: rgba(226, 188, 109, 0.15); color: var(--gold-400); }
.delivery-stage.idle .delivery-stage-icon { background: var(--surface-lowered); color: var(--text-faint); }
.delivery-stage-info { display: flex; flex-direction: column; gap: 1px; }
