.delivery-stage-value { font: 700 22px var(--font-mono); color: var(--text-primary); line-height: 1; }
.delivery-stage-connector { width: 32px; height: 2px; background: var(--border-subtle); flex-shrink: 0; }
.delivery-timeline-footer { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
.delivery-failures { padding: 12px 14px; border-radius: var(--radius-sm); border: 1px solid rgba(236, 72, 153, 0.15); background: rgba(236, 72, 153, 0.03); }
.delivery-failures-header { display: flex; align-items: center; gap: 8px; font: 600 12px var(--font-sans); color: var(--rust-400); margin-bottom: 8px; }
.delivery-failure-reasons { display: flex; flex-direction: column; gap: 4px; }
.delivery-failure-reason { font: 400 11px var(--font-sans); color: var(--text-muted); padding-left: 22px; }
.delivery-unverified { display: flex; align-items: center; gap: 8px; font: 500 11px var(--font-sans); color: var(--gold-400); padding: 10px 14px; border-radius: var(--radius-sm); border: 1px solid rgba(226, 188, 109, 0.15); background: rgba(226, 188, 109, 0.03); }
.delivery-all-verified { display: flex; align-items: center; gap: 8px; font: 600 12px var(--font-sans); color: var(--sage-400); padding: 10px 14px; border-radius: var(--radius-sm); border: 1px solid rgba(34, 139, 87, 0.15); background: rgba(34, 139, 87, 0.03); }
.delivery-evidence-notice { display: flex; align-items: flex-start; gap: 10px; margin-top: 12px; padding: 12px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border-subtle); background: var(--surface-lowered); }
.delivery-evidence-icon { color: var(--sage-400); flex-shrink: 0; margin-top: 1px; }
.delivery-evidence-text { font: 400 11px var(--font-sans); color: var(--text-muted); line-height: 1.5; }
.delivery-evidence-text strong { color: var(--text-secondary); }
.delivery-live-test-pending { display: flex; align-items: center; gap: 4px; margin-top: 6px; color: var(--gold-400); font-weight: 500; }

/* ── Inbound Verification Panel ── */
.inbound-verification-panel { margin-bottom: 20px; }
.inbound-config-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.inbound-config-section { display: flex; flex-direction: column; gap: 10px; }
.inbound-config-header { display: flex; align-items: center; gap: 8px; font: 600 12px var(--font-sans); color: var(--text-secondary); }
.inbound-agent-list { display: flex; flex-direction: column; gap: 6px; }
.inbound-agent-row { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: var(--radius-sm); border: 1px solid var(--border-subtle); background: var(--surface-raised); font: 12px var(--font-sans); }
.inbound-agent-row.configured { border-left: 3px solid var(--sage-400); }
.inbound-agent-row.not-configured { border-left: 3px solid var(--text-faint); opacity: 0.7; }
.inbound-agent-name { font-weight: 600; color: var(--text-primary); flex-shrink: 0; min-width: 100px; }
.inbound-agent-route { color: var(--text-muted); flex: 1; }
.inbound-agent-badge { font: 600 10px var(--font-sans); padding: 2px 8px; border-radius: 100px; }
.inbound-agent-badge.configured { background: rgba(34, 139, 87, 0.12); color: var(--sage-400); }
.inbound-agent-badge.not-configured { background: var(--surface-lowered); color: var(--text-faint); }
.inbound-webhook-events { display: flex; flex-direction: column; gap: 6px; }
.inbound-webhook-event { display: flex; align-items: center; gap: 6px; font: 500 11px var(--font-sans); color: var(--text-secondary); padding: 6px 10px; border-radius: var(--radius-sm); border: 1px solid var(--border-subtle); background: var(--surface-raised); }
.inbound-webhook-event svg { color: var(--sage-400); }
.inbound-evidence-notice { display: flex; flex-direction: column; gap: 8px; margin-top: 14px; padding: 12px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border-subtle); background: var(--surface-lowered); }
.inbound-evidence-row { display: flex; align-items: flex-start; gap: 8px; font: 400 11px var(--font-sans); color: var(--text-muted); line-height: 1.5; }
.inbound-evidence-row.software svg { color: var(--sage-400); flex-shrink: 0; margin-top: 1px; }
.inbound-evidence-row.pending svg { color: var(--gold-400); flex-shrink: 0; margin-top: 1px; }
.inbound-evidence-row strong { color: var(--text-secondary); }

@media (max-width: 760px) {
  .delivery-timeline-track { gap: 0; padding: 16px 0; }
  .delivery-stage { padding: 10px 12px; }
