/* ═══════════════════════════════════════════════════════════════════════════
   v222 COMMAND CENTER HERO & DESIGN REFINEMENTS
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Command Center Hero ── */
.command-center-hero {
  position: relative;
  height: 240px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 24px;
  border: 1px solid var(--border-subtle);
  background: var(--ink-900);
}
.command-center-hero-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.6) brightness(0.35) contrast(1.15);
  animation: ken-burns 40s ease-in-out infinite alternate;
}
.command-center-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(7,10,15,0.92) 0%, rgba(7,10,15,0.55) 45%, rgba(7,10,15,0.85) 100%);
}
.command-center-hero-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 100%;
  padding: 32px 40px;
  max-width: 720px;
}
.command-center-hero-eyebrow {
  font: 600 11px var(--font-sans);
  letter-spacing: 0.14em;
  color: var(--gold-400);
  text-transform: uppercase;
  margin-bottom: 10px;
}
.command-center-hero-title {
  font: 700 42px/1.1 var(--font-display);
  color: var(--gold-100);
  margin: 0 0 12px;
  letter-spacing: -0.01em;
}
.command-center-hero-subtitle {
  font: 400 14px/1.6 var(--font-sans);
  color: var(--text-secondary);
  margin: 0;
  max-width: 560px;
}

/* ── Refined KPI emphasis ── */
.kpi-item {
  position: relative;
  overflow: hidden;
}
.kpi-item::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, currentColor, transparent);
  opacity: 0.3;
}
.kpi-item.accent-gold::after { color: var(--gold-400); }
.kpi-item.accent-sage::after { color: var(--sage-400); }
.kpi-item.accent-rust::after { color: var(--rust-400); }
.kpi-item.accent-steel::after { color: var(--steel-400); }

/* ── Refined buttons: 44px touch targets ── */
.toggle-btn, .conc-btn, .dash-tab, .perf-tab, .privacy-reveal-btn {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ── Refined focus states ── */
button:focus-visible, input:focus-visible, select:focus-visible, a:focus-visible {
  outline: 2px solid var(--gold-400);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ── Refined empty states ── */
.empty-state {
  padding: 32px 20px;
  text-align: center;
  font: 400 13px/1.6 var(--font-sans);
  color: var(--text-muted);
}

/* ── Refined loading skeletons ── */
.skeleton, .skeleton-card {
  background: linear-gradient(90deg, var(--ink-800) 0%, var(--ink-750) 50%, var(--ink-800) 100%);
  background-size: 200% 100%;
  animation: skeleton-pulse 1.8s ease-in-out infinite;
  border-radius: var(--radius-md);
}

/* ── Refined agent status presentation ── */
.agent-readiness-card {
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.agent-readiness-card:hover {
  transform: translateY(-1px);
  border-color: var(--border-gold);
}
.agent-readiness-status.online {
  position: relative;
  padding-left: 20px;
}
.agent-readiness-status.online::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--sage-400);
  box-shadow: 0 0 8px rgba(125, 211, 160, 0.4);
}
.agent-readiness-status.offline {
  position: relative;
  padding-left: 20px;
}
.agent-readiness-status.offline::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-faint);
}

/* ── Refined error states ── */
.error-banner, .login-error {
  border-left: 3px solid var(--rust-400);
  background: rgba(236, 72, 153, 0.06);
}

/* ── 402px mobile refinements ── */
@media (max-width: 402px) {
  .command-center-hero { height: 200px; }
  .command-center-hero-content { padding: 20px 20px; }
  .command-center-hero-title { font-size: 28px; }
  .command-center-hero-subtitle { font-size: 12px; }
  .kpi-strip { grid-template-columns: repeat(2, 1fr); gap: 8px; }
  .kpi-value { font-size: 24px; }
  .kpi-label { font-size: 9px; }
  .kpi-hint { font-size: 9px; }
  .lead-pool-buckets { grid-template-columns: 1fr; }
  .delivery-timeline-track { flex-direction: column; align-items: stretch; gap: 8px; }
  .delivery-stage-connector { display: none; }
  .delivery-stage { width: 100%; }
  .perf-table { font-size: 11px; }
  .perf-table th, .perf-table td { padding: 8px 6px; }
  .agent-control-row { flex-direction: column; align-items: stretch; gap: 12px; }
  .agent-control-right { width: 100%; }
}

/* ── No horizontal overflow guarantee ── */
.app-shell, .dashboard-content, .kpi-strip, .lead-pool-buckets, .delivery-timeline-track {
  max-width: 100%;
  overflow-x: auto;
}

/* ── Load More button ── */
.load-more-wrap { display: flex; justify-content: center; padding: 16px 0; }
.load-more-btn { min-height: 44px; }

/* ── Transfer truth label ── */
.transfer-truth-label .transfer-truth {
  color: var(--gold-400);
  font: 400 11px var(--font-sans);
  font-style: italic;
}

/* ── Mobile dashboard tabs ── */
@media (max-width: 760px) {
  .dash-tabs { overflow-x: auto; flex-wrap: nowrap; gap: 2px; }
  .dash-tab { padding: 10px 14px; font-size: 11px; white-space: nowrap; min-height: 44px; }
  .campaign-status-card { flex-direction: column; align-items: flex-start; }
  .campaign-status-actions { width: 100%; }
  .campaign-status-actions button { flex: 1; }
}

/* ═══════════════════════════════════════════════════════════════════════════
   LIVE OPERATIONS HEALTH MAP
   ═══════════════════════════════════════════════════════════════════════════ */

.healthmap-panel {
  background: var(--glass-bg);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-xl);
  padding: 24px 28px 20px;
  margin-bottom: 24px;
  backdrop-filter: blur(12px);
}

.healthmap-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.healthmap-header h3 {
  font: 600 18px var(--font-sans);
  color: var(--text-primary);
  margin: 4px 0 0;
}

.healthmap-controls {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.healthmap-filters {
  display: flex;
  gap: 2px;
  background: var(--ink-850);
  border-radius: var(--radius-lg);
  padding: 3px;
  border: 1px solid var(--border-subtle);
}
.healthmap-filter-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 14px;
  border-radius: var(--radius-md);
  font: 600 11px var(--font-mono);
  letter-spacing: 0.06em;
  color: var(--text-muted);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  min-height: 44px;
}
.healthmap-filter-btn:hover { color: var(--text-secondary); background: rgba(255,255,255,0.03); }
.healthmap-filter-btn.active {
  color: var(--gold-400);
  background: color-mix(in srgb, var(--gold-400) 8%, transparent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--gold-400) 10%, transparent);
}
.healthmap-live-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #ef4444;
  animation: healthmap-pulse 2s ease-in-out infinite;
}
@keyframes healthmap-pulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 4px rgba(239,68,68,0.5); }
  50% { opacity: 0.5; box-shadow: 0 0 8px rgba(239,68,68,0.8); }
}

.healthmap-updated {
  display: flex;
  align-items: center;
  gap: 5px;
  font: 500 10px var(--font-mono);
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

/* ── Topology (Desktop + iPad) ── */
.healthmap-topology { display: block; }
.healthmap-timeline { display: none; }

.healthmap-main-track {
  display: flex;
  align-items: center;
  gap: 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  padding: 8px 0 16px;
}
.healthmap-stage-group {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.healthmap-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 12px 10px;
  min-width: 90px;
  border-radius: var(--radius-lg);
  border: 1.5px solid var(--border-subtle);
  background: var(--ink-850);
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16,1,0.3,1);
}
.healthmap-node:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.2);
}
.healthmap-node:focus-visible {
  outline: 2px solid var(--gold-400);
  outline-offset: 2px;
}

/* State colors */
.healthmap-node.green { border-color: rgba(239,68,68,0.4); }
.healthmap-node.green .healthmap-node-icon-wrap { color: #ef4444; }
.healthmap-node.yellow { border-color: rgba(226,188,109,0.4); }
.healthmap-node.yellow .healthmap-node-icon-wrap { color: #e2bc6d; }
.healthmap-node.red { border-color: rgba(232,98,58,0.4); }
.healthmap-node.red .healthmap-node-icon-wrap { color: #e8623a; }
.healthmap-node.gray { border-color: var(--border-subtle); opacity: 0.6; }
.healthmap-node.gray .healthmap-node-icon-wrap { color: var(--text-muted); }

.healthmap-node-icon-wrap {
  width: 32px; height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
}
.healthmap-node.green .healthmap-node-icon-wrap { background: rgba(239,68,68,0.1); }
.healthmap-node.yellow .healthmap-node-icon-wrap { background: rgba(226,188,109,0.1); }
.healthmap-node.red .healthmap-node-icon-wrap { background: rgba(232,98,58,0.1); }

.healthmap-node-label {
  font: 600 9px var(--font-mono);
  letter-spacing: 0.08em;
  color: var(--text-muted);
  text-transform: uppercase;
  text-align: center;
  line-height: 1.3;
}
.healthmap-node-value {
  font: 700 16px var(--font-sans);
  color: var(--text-primary);
}

/* Connector */
.healthmap-connector {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0 4px;
  color: var(--border-default);
}
.healthmap-connector.green { color: rgba(239,68,68,0.5); }
.healthmap-connector.yellow { color: rgba(226,188,109,0.4); }
.healthmap-connector.red { color: rgba(232,98,58,0.4); }
.healthmap-connector-line {
  width: 16px;
  height: 1.5px;
  background: currentColor;
}

/* Side nodes */
.healthmap-side-track {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--border-subtle);
  flex-wrap: wrap;
}
.healthmap-node.side {
  flex-direction: row;
  min-width: auto;
  padding: 8px 14px;
  gap: 8px;
}
.healthmap-node.side .healthmap-node-icon-wrap { width: 24px; height: 24px; }
.healthmap-node.side .healthmap-node-label { font-size: 9px; }
.healthmap-node.side .healthmap-node-value { font-size: 12px; }

/* ── Timeline (Mobile) ── */
.healthmap-timeline-item {
  position: relative;
}
.healthmap-timeline-node {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  background: var(--ink-850);
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;
}
.healthmap-timeline-node:hover { background: rgba(255,255,255,0.02); }
.healthmap-timeline-node:focus-visible { outline: 2px solid var(--gold-400); outline-offset: 2px; }
.healthmap-timeline-node .healthmap-node-icon-wrap { flex-shrink: 0; }
.healthmap-timeline-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.healthmap-timeline-node .healthmap-node-label { font-size: 10px; }
.healthmap-timeline-node .healthmap-node-value { font-size: 15px; }
.healthmap-chevron { color: var(--text-muted); flex-shrink: 0; }

/* State colors on timeline */
.healthmap-timeline-node.green { border-color: rgba(239,68,68,0.3); }
.healthmap-timeline-node.green .healthmap-node-icon-wrap { color: #ef4444; }
.healthmap-timeline-node.yellow { border-color: rgba(226,188,109,0.3); }
.healthmap-timeline-node.yellow .healthmap-node-icon-wrap { color: #e2bc6d; }
.healthmap-timeline-node.red { border-color: rgba(232,98,58,0.3); }
.healthmap-timeline-node.red .healthmap-node-icon-wrap { color: #e8623a; }
.healthmap-timeline-node.gray { border-color: var(--border-subtle); opacity: 0.7; }
.healthmap-timeline-node.gray .healthmap-node-icon-wrap { color: var(--text-muted); }

.healthmap-timeline-connector {
  width: 2px;
  height: 8px;
  margin: 0 auto;
  background: var(--border-subtle);
}
.healthmap-timeline-connector.green { background: rgba(239,68,68,0.3); }
.healthmap-timeline-connector.yellow { background: rgba(226,188,109,0.3); }
.healthmap-timeline-connector.red { background: rgba(232,98,58,0.3); }

.healthmap-timeline-side {
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--border-subtle);
}
.healthmap-timeline-side-label {
  font: 600 9px var(--font-mono);
  letter-spacing: 0.1em;
  color: var(--text-muted);
  text-transform: uppercase;
  margin-bottom: 8px;
}
.healthmap-timeline-side .healthmap-timeline-node { margin-bottom: 6px; }

/* State badge */
.healthmap-state-badge {
  font: 600 9px var(--font-mono);
  letter-spacing: 0.06em;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}
.healthmap-state-badge.green { color: #ef4444; background: rgba(239,68,68,0.1); }
.healthmap-state-badge.yellow { color: #e2bc6d; background: rgba(226,188,109,0.1); }
.healthmap-state-badge.red { color: #e8623a; background: rgba(232,98,58,0.1); }
.healthmap-state-badge.gray { color: var(--text-muted); background: rgba(255,255,255,0.04); }

/* ── Drawer ── */
.healthmap-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10,14,11,0.7);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
  animation: fadeIn 0.2s;
}
.healthmap-drawer {
  width: 100%;
  max-width: 380px;
  height: 100%;
  background: var(--ink-900);
  border-left: 1px solid var(--border-default);
  padding: 28px 24px;
  overflow-y: auto;
  animation: slideInRight 0.3s cubic-bezier(0.16,1,0.3,1);
  position: relative;
}
@keyframes slideInRight {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}
.healthmap-drawer-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
  margin-top: 8px;
}
.healthmap-drawer-header h3 {
  font: 600 18px var(--font-sans);
  color: var(--text-primary);
  margin: 0;
}
.healthmap-drawer-header .healthmap-node-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.healthmap-drawer-header .healthmap-node-icon.green { color: #ef4444; background: rgba(239,68,68,0.12); }
.healthmap-drawer-header .healthmap-node-icon.yellow { color: #e2bc6d; background: rgba(226,188,109,0.12); }
.healthmap-drawer-header .healthmap-node-icon.red { color: #e8623a; background: rgba(232,98,58,0.12); }
.healthmap-drawer-header .healthmap-node-icon.gray { color: var(--text-muted); background: rgba(255,255,255,0.06); }
.healthmap-drawer-value {
  font: 700 32px var(--font-sans);
  color: var(--text-primary);
  margin-bottom: 12px;
}
.healthmap-drawer-detail {
  font: 400 14px/1.6 var(--font-sans);
  color: var(--text-secondary);
  margin-bottom: 20px;
}
.healthmap-recommendation {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px 16px;
  background: rgba(226,188,109,0.06);
  border: 1px solid rgba(226,188,109,0.2);
  border-radius: var(--radius-lg);
  margin-bottom: 16px;
}
.healthmap-recommendation svg { color: #e2bc6d; flex-shrink: 0; margin-top: 2px; }
.healthmap-recommendation span { font: 400 13px/1.5 var(--font-sans); color: var(--text-secondary); }

.healthmap-disclaimer {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 12px 14px;
  background: rgba(155,200,221,0.04);
  border: 1px solid rgba(155,200,221,0.12);
  border-radius: var(--radius-md);
  margin-top: 20px;
}
.healthmap-disclaimer svg { color: var(--neon-blue); flex-shrink: 0; margin-top: 1px; }
.healthmap-disclaimer span { font: 400 11px/1.5 var(--font-sans); color: var(--text-muted); }

.healthmap-footer {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-subtle);
  font: 400 10px/1.4 var(--font-sans);
  color: var(--text-muted);
}
.healthmap-footer svg { flex-shrink: 0; }

/* ── Per-agent breakdown table ── */
.healthmap-agents-section {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--border-subtle);
}
.healthmap-agents-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  background: none;
  border: none;
  color: var(--text-secondary);
  font: 600 12px var(--font-mono);
  letter-spacing: 0.05em;
  cursor: pointer;
  padding: 8px 4px;
  min-height: 44px;
  width: 100%;
  text-align: left;
}
.healthmap-agents-toggle:hover { color: var(--text-primary); }
.healthmap-toggle-chevron { transition: transform 0.2s; flex-shrink: 0; margin-left: auto; }
.healthmap-toggle-chevron.open { transform: rotate(90deg); }
.healthmap-agents-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  margin-top: 8px;
}
.healthmap-agents-table {
  width: 100%;
  border-collapse: collapse;
  font: 400 12px var(--font-sans);
}
.healthmap-agents-table th {
  font: 600 9px var(--font-mono);
  letter-spacing: 0.08em;
  color: var(--text-muted);
  text-transform: uppercase;
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}
.healthmap-agents-table td {
  padding: 10px 10px;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}
.healthmap-agent-name { color: var(--text-primary); font-weight: 600; }
.healthmap-bridged-cell { color: #ef4444; font-weight: 600; }
.healthmap-failed-cell { color: #e8623a; font-weight: 600; }
.healthmap-agent-row.green td:first-child { border-left: 3px solid rgba(239,68,68,0.4); }
.healthmap-agent-row.yellow td:first-child { border-left: 3px solid rgba(226,188,109,0.4); }
.healthmap-agent-row.red td:first-child { border-left: 3px solid rgba(232,98,58,0.4); }
.healthmap-agent-row.gray td:first-child { border-left: 3px solid var(--border-subtle); }
.healthmap-agent-row:hover td { background: rgba(255,255,255,0.02); }

/* ── Agent Cockpit ── */
.agent-cockpit {
  background: var(--glass-bg);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 24px;
  backdrop-filter: blur(20px);
}
.cockpit-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}
.cockpit-greeting h2 { font: 600 20px var(--font-sans); color: var(--text-primary); margin: 0; }
.cockpit-subtitle { font: 400 12px var(--font-mono); color: var(--text-muted); margin-top: 2px; }
.cockpit-avail-toggle {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 16px; border-radius: 20px; border: 1px solid var(--border-subtle);
  font: 600 11px var(--font-mono); letter-spacing: 0.06em;
  cursor: pointer; transition: all 0.2s; min-height: 44px;
  background: transparent;
}
.cockpit-avail-toggle.online { border-color: rgba(239,68,68,0.4); color: #ef4444; }
.cockpit-avail-toggle.offline { border-color: rgba(232,98,58,0.3); color: var(--rust-400); }
.cockpit-avail-toggle:hover { transform: translateY(-1px); }
.cockpit-avail-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--rust-400); flex-shrink: 0;
}
.cockpit-avail-dot.pulse { background: #ef4444; animation: pulseGlow 2s ease-in-out infinite; }
@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(239,68,68,0.4); }
  50% { box-shadow: 0 0 0 6px rgba(239,68,68,0); }
}

.cockpit-pipeline {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px;
  margin-bottom: 20px;
}
.cockpit-stat {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 14px 8px; border-radius: 10px;
  background: rgba(255,255,255,0.02); border: 1px solid var(--border-subtle);
  transition: border-color 0.2s;
}
.cockpit-stat:hover { border-color: var(--border-gold); }
.cockpit-stat-icon { color: var(--text-muted); }
.cockpit-stat-value { font: 700 22px var(--font-sans); color: var(--text-primary); letter-spacing: -0.03em; }
.cockpit-stat-label { font: 500 8px var(--font-mono); letter-spacing: 0.1em; color: var(--text-muted); text-transform: uppercase; text-align: center; }
.cockpit-stat-steel .cockpit-stat-value { color: var(--steel-300); }
.cockpit-stat-gold .cockpit-stat-value { color: var(--gold-300); }
.cockpit-stat-rust .cockpit-stat-value { color: var(--rust-400); }
.cockpit-stat-sage .cockpit-stat-value { color: var(--sage-400); }
.cockpit-stat-error .cockpit-stat-value { color: #e8623a; }

.cockpit-actions {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;
  margin-bottom: 20px;
}
.cockpit-action {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 14px 8px; border-radius: 10px;
  background: rgba(255,255,255,0.02); border: 1px solid var(--border-subtle);
  color: var(--text-secondary); font: 500 10px var(--font-mono);
  letter-spacing: 0.06em; cursor: pointer; transition: all 0.2s;
  min-height: 44px; position: relative;
}
.cockpit-action:hover { border-color: var(--border-gold); color: var(--text-primary); transform: translateY(-1px); }
.cockpit-action.active { border-color: var(--gold-400); color: var(--gold-300); background: rgba(255,255,255,0.04); }
.cockpit-badge {
  position: absolute; top: 6px; right: 6px;
  background: var(--rust-400); color: #fff; font: 700 9px var(--font-sans);
  min-width: 16px; height: 16px; border-radius: 8px;
  display: flex; align-items: center; justify-content: center; padding: 0 4px;
}

.cockpit-recent { border-top: 1px solid var(--border-subtle); padding-top: 14px; }
.cockpit-recent-toggle {
  display: flex; align-items: center; gap: 8px;
  background: none; border: none; color: var(--text-secondary);
  font: 600 11px var(--font-mono); letter-spacing: 0.05em;
  cursor: pointer; padding: 8px 4px; min-height: 44px; width: 100%; text-align: left;
}
.cockpit-recent-toggle:hover { color: var(--text-primary); }
.cockpit-chevron { transition: transform 0.2s; flex-shrink: 0; margin-left: auto; }
.cockpit-chevron.open { transform: rotate(90deg); }
.cockpit-recent-list { margin-top: 8px; display: flex; flex-direction: column; gap: 4px; }
.cockpit-recent-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: 8px;
  background: rgba(255,255,255,0.02);
}
.cockpit-recent-name { font: 500 12px var(--font-sans); color: var(--text-primary); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cockpit-recent-status { font: 700 8px var(--font-mono); letter-spacing: 0.1em; padding: 2px 6px; border-radius: 4px; }
.cockpit-recent-status.hot { background: rgba(232,98,58,0.15); color: var(--rust-400); }
.cockpit-recent-status.warm { background: rgba(226,188,109,0.15); color: var(--gold-300); }
.cockpit-recent-time { font: 400 10px var(--font-mono); color: var(--text-dim); white-space: nowrap; }

.cockpit-footer {
  display: flex; align-items: center; gap: 6px; margin-top: 14px;
  font: 400 9px var(--font-mono); color: var(--text-dim); letter-spacing: 0.04em;
}

/* Cockpit responsive */
@media (max-width: 760px) {
  .cockpit-pipeline { grid-template-columns: repeat(3, 1fr); }
  .cockpit-actions { grid-template-columns: repeat(2, 1fr); }
  .cockpit-stat-value { font-size: 18px; }
}
@media (max-width: 430px) {
  .agent-cockpit { padding: 16px; border-radius: 12px; }
  .cockpit-header { flex-direction: column; align-items: flex-start; }
  .cockpit-greeting h2 { font-size: 17px; }
  .cockpit-pipeline { grid-template-columns: repeat(2, 1fr); gap: 6px; }
  .cockpit-stat { padding: 10px 6px; }
  .cockpit-stat-value { font-size: 16px; }
  .cockpit-actions { grid-template-columns: repeat(2, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  .cockpit-avail-dot.pulse { animation: none; }
  .cockpit-action, .cockpit-stat, .cockpit-avail-toggle { transition: none; }
  .cockpit-chevron { transition: none; }
}

/* ── Responsive: switch topology → timeline at phone widths ── */
@media (max-width: 760px) {
  .healthmap-topology { display: none; }
  .healthmap-timeline { display: block; }
  .healthmap-panel { padding: 16px 14px 14px; }
