.retry-header-left { flex: 1; min-width: 200px; }
.retry-header-actions { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
.retry-state-badge { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; border-radius: 20px; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.05em; }
.retry-state-badge.running { background: rgba(239,68,68,0.15); color: #ef4444; }
.retry-state-badge.stopped { background: rgba(107,140,168,0.15); color: #6b8ca8; }
.retry-error { background: rgba(194,94,58,0.12); border: 1px solid rgba(194,94,58,0.3); border-radius: 8px; padding: 0.75rem 1rem; color: #c25e3a; font-size: 0.8rem; display: flex; align-items: center; gap: 0.5rem; }
.retry-kpi-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 0.75rem; }
.retry-kpi { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1rem; text-align: center; display: flex; flex-direction: column; gap: 2px; }
.retry-kpi-value { font-size: 1.5rem; font-weight: 700; color: var(--color-text-primary, #e8e0d4); }
.retry-kpi-label { font-size: 0.65rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-secondary, #8a8578); }
.retry-kpi-pct { font-size: 0.7rem; color: var(--color-text-secondary, #8a8578); }
.retry-kpi.highlight-green .retry-kpi-value { color: #7a9b8e; }
.retry-kpi.highlight-gold .retry-kpi-value { color: #d9aa57; }
.retry-progress-container { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1rem; }
.retry-progress-bar { height: 8px; background: rgba(255,255,255,0.06); border-radius: 4px; overflow: hidden; }
.retry-progress-fill { height: 100%; background: linear-gradient(90deg, #6b8ca8, #7a9b8e); border-radius: 4px; transition: width 0.6s ease; }
.retry-progress-label { font-size: 0.75rem; color: var(--color-text-secondary, #8a8578); margin-top: 0.5rem; text-align: center; }
.retry-funnel { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1.25rem; }
.retry-section-heading { font-size: 0.7rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-secondary, #8a8578); display: flex; align-items: center; gap: 6px; margin-bottom: 0.75rem; }
.retry-funnel-row { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.4rem; }
.retry-funnel-label { width: 100px; font-size: 0.72rem; font-weight: 600; color: var(--color-text-secondary, #8a8578); text-align: right; flex-shrink: 0; }
.retry-funnel-bar-track { flex: 1; height: 20px; background: rgba(255,255,255,0.04); border-radius: 4px; overflow: hidden; }
.retry-funnel-bar-fill { height: 100%; border-radius: 4px; transition: width 0.5s ease; }
.retry-funnel-value { width: 40px; font-size: 0.8rem; font-weight: 700; color: var(--color-text-primary, #e8e0d4); }
.retry-funnel-drop { font-size: 0.65rem; color: #c25e3a; width: 40px; }
.retry-funnel-side { display: flex; flex-wrap: wrap; align-items: center; gap: 0.35rem; margin-top: 0.75rem; padding-top: 0.75rem; border-top: 1px solid rgba(255,255,255,0.06); }
.retry-side-label { font-size: 0.7rem; color: var(--color-text-secondary, #8a8578); display: flex; align-items: center; gap: 4px; }
.retry-side-value { font-size: 0.8rem; font-weight: 700; color: var(--color-text-primary, #e8e0d4); }
.retry-exclusions { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1.25rem; }
.retry-exclusion-row { display: flex; justify-content: space-between; padding: 0.4rem 0; border-bottom: 1px solid rgba(255,255,255,0.04); font-size: 0.8rem; color: var(--color-text-secondary, #8a8578); }
.retry-excl-val { font-weight: 700; color: var(--color-text-primary, #e8e0d4); }
.retry-alerts-section { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1rem; }
.retry-section-toggle { background: none; border: none; color: var(--color-text-secondary, #8a8578); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; display: flex; align-items: center; gap: 6px; cursor: pointer; padding: 0; }
.retry-alerts-list { display: flex; flex-direction: column; gap: 0.4rem; margin-top: 0.5rem; }
.retry-alert { display: flex; align-items: flex-start; gap: 0.5rem; padding: 0.6rem 0.75rem; border-radius: 6px; font-size: 0.78rem; line-height: 1.4; }
.retry-alert-warn { background: rgba(217,170,87,0.1); color: #d9aa57; }
.retry-alert-error { background: rgba(194,94,58,0.1); color: #c25e3a; }
.retry-alert-info { background: rgba(107,140,168,0.1); color: #6b8ca8; }
.retry-agents-section { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1rem; }
.retry-agent-table-wrap { overflow-x: auto; margin-top: 0.5rem; }
.retry-agent-table { width: 100%; border-collapse: collapse; font-size: 0.78rem; }
.retry-agent-table th { text-align: left; padding: 0.5rem 0.75rem; font-size: 0.65rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-text-secondary, #8a8578); border-bottom: 1px solid rgba(255,255,255,0.08); }
.retry-agent-table td { padding: 0.5rem 0.75rem; border-bottom: 1px solid rgba(255,255,255,0.04); color: var(--color-text-primary, #e8e0d4); }
.retry-agent-name { font-weight: 600; }
.retry-bridge-yes { color: #ef4444; font-weight: 700; }
.retry-conversions { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 10px; padding: 1.25rem; }
.retry-conversion-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 0.75rem; }
.retry-conv-card { text-align: center; padding: 0.75rem; border-radius: 8px; background: rgba(255,255,255,0.02); }
.retry-conv-label { display: block; font-size: 0.65rem; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; color: var(--color-text-secondary, #8a8578); margin-bottom: 0.25rem; }
.retry-conv-value { font-size: 1.25rem; font-weight: 700; color: #d9aa57; }
@media (max-width: 768px) {
  .retry-header { flex-direction: column; }
  .retry-kpi-strip { grid-template-columns: repeat(3, 1fr); }
  .retry-funnel-label { width: 70px; font-size: 0.65rem; }
  .retry-conversion-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .retry-kpi-strip { grid-template-columns: repeat(2, 1fr); }
  .retry-conversion-grid { grid-template-columns: 1fr; }
}

/* ── Incoming Transfer Panel ──────────────────────────────────────────── */
.itp-panel {
  background: linear-gradient(135deg, rgba(220,80,60,0.12), rgba(255,140,50,0.08));
  border: 1px solid rgba(220,80,60,0.35);
  border-radius: 16px;
  padding: 20px;
  margin-bottom: 24px;
  animation: itp-slide-in 0.3s ease-out;
}
@keyframes itp-slide-in {
  from { opacity: 0; transform: translateY(-12px); }
  to { opacity: 1; transform: translateY(0); }
}
.itp-panel-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 16px;
}
.itp-panel-header-left {
  display: flex; align-items: center; gap: 10px;
}
.itp-header-icon { color: #dc503c; }
.itp-panel-header-left strong {
  font-size: 12px; letter-spacing: 0.08em; color: #dc503c;
  font-weight: 700;
}
.itp-count {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 22px; height: 22px; border-radius: 11px;
  background: #dc503c; color: #fff; font-size: 11px; font-weight: 700;
  padding: 0 6px;
}
.itp-loading-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: #dc503c; animation: itp-blink 1s ease infinite;
}
@keyframes itp-blink { 0%,100%{opacity:0.3} 50%{opacity:1} }
.itp-error {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 14px; border-radius: 10px;
  background: rgba(220,80,60,0.15); color: #e8a090;
  font-size: 13px; margin-bottom: 12px;
}
.itp-cards { display: flex; flex-direction: column; gap: 12px; }
.itp-card {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px; padding: 16px;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.itp-card:hover {
  border-color: rgba(220,80,60,0.4);
  box-shadow: 0 0 20px rgba(220,80,60,0.1);
}
.itp-card-phone-only { border-left: 3px solid rgba(255,180,50,0.5); }
.itp-card-header {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 12px;
}
.itp-card-header-left { display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; }
.itp-card-header-right { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
.itp-pulse {
  width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0;
}
.itp-status-pending {
  background: #dc503c;
  box-shadow: 0 0 8px rgba(220,80,60,0.6);
  animation: itp-pulse-glow 1.5s ease infinite;
}
@keyframes itp-pulse-glow {
  0%,100% { box-shadow: 0 0 6px rgba(220,80,60,0.4); }
  50% { box-shadow: 0 0 16px rgba(220,80,60,0.8); }
}
.itp-status-connected { background: #f87171; box-shadow: 0 0 8px rgba(248,113,113,0.5); }
.itp-status-other { background: #8892a4; }
.itp-card-title { min-width: 0; }
.itp-card-title strong {
  display: block; font-size: 15px; font-weight: 600;
  color: rgba(255,255,255,0.95); white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis;
}
.itp-card-phone {
  font-size: 13px; color: rgba(255,255,255,0.55);
  font-family: 'SF Mono', 'Fira Code', monospace; letter-spacing: 0.02em;
}
.itp-elapsed {
  display: flex; align-items: center; gap: 4px;
  font-size: 11px; color: rgba(255,255,255,0.4);
  white-space: nowrap;
}
.itp-btn-icon {
  display: flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: 8px;
  background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.5); cursor: pointer; transition: all 0.15s;
}
.itp-btn-icon:hover { background: rgba(255,255,255,0.1); color: rgba(255,255,255,0.8); }
.itp-dismiss:hover { background: rgba(220,80,60,0.2); color: #dc503c; }
.itp-phone-only-label {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; color: rgba(255,180,50,0.7);
  margin-top: 8px; padding: 8px 12px; border-radius: 8px;
  background: rgba(255,180,50,0.08);
}
.itp-actions {
  display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap;
}
.itp-action-btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 14px; border-radius: 8px; font-size: 12px;
  font-weight: 600; color: rgba(255,255,255,0.7);
  background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1);
  cursor: pointer; transition: all 0.15s; white-space: nowrap;
}
.itp-action-btn:hover { background: rgba(255,255,255,0.12); color: #fff; }
.itp-details {
  margin-top: 12px; padding-top: 12px;
  border-top: 1px solid rgba(255,255,255,0.06);
  display: flex; flex-direction: column; gap: 8px;
}
.itp-detail-row {
  display: flex; align-items: flex-start; gap: 8px;
  font-size: 13px; color: rgba(255,255,255,0.7);
  line-height: 1.5;
}
.itp-detail-icon { flex-shrink: 0; color: rgba(255,255,255,0.35); margin-top: 2px; }
.itp-custom-fields { display: flex; flex-direction: column; gap: 6px; }
@media (max-width: 640px) {
  .itp-panel { padding: 14px; }
  .itp-card { padding: 12px; }
  .itp-card-title strong { font-size: 14px; }
}

/* ═══════════════════════════════════════════════════════════════════
   Agent Workspace View
   ═══════════════════════════════════════════════════════════════════ */
.ws-container { display: flex; flex-direction: column; gap: 8px; }
.ws-loading { display: flex; align-items: center; gap: 10px; justify-content: center; padding: 48px 24px; color: var(--text-muted); font-size: 13px; }
.ws-spin { animation: spin 1s linear infinite; }

/* Stats strip */
.ws-stat-strip { display: flex; gap: 4px; padding: 8px; background: var(--glass-bg); border: 1px solid var(--border-subtle); border-radius: 10px; overflow-x: auto; }
.ws-stat { display: flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 8px; font-size: 11px; color: var(--text-secondary); white-space: nowrap; flex: 1; justify-content: center; }
.ws-stat strong { font-size: 18px; font-weight: 700; color: var(--text-primary); }
.ws-stat span { text-transform: uppercase; letter-spacing: 0.6px; font-weight: 600; font-size: 9px; }
.ws-stat-hot { background: rgba(239, 68, 68, 0.08); border: 1px solid rgba(239, 68, 68, 0.2); }
.ws-stat-hot strong { color: #ef4444; }

/* Redial bar */
.ws-redial-bar { display: flex; align-items: center; justify-content: space-between; padding: 10px 16px; background: linear-gradient(135deg, rgba(239,68,68,0.08), rgba(251,146,60,0.08)); border: 1px solid rgba(239,68,68,0.2); border-radius: 10px; font-size: 12px; color: var(--text-primary); font-weight: 600; }
.ws-redial-btn { display: flex; align-items: center; gap: 6px; padding: 8px 16px; background: #ef4444; color: #fff; border: none; border-radius: 8px; font-size: 12px; font-weight: 700; cursor: pointer; transition: background 0.2s; }
.ws-redial-btn:hover:not(:disabled) { background: #dc2626; }
.ws-redial-btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* Redial results */
.ws-redial-results { background: var(--glass-bg); border: 1px solid var(--border-subtle); border-radius: 10px; padding: 12px 16px; }
.ws-redial-results-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; font-size: 12px; }
.ws-redial-results-header button { background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 18px; }
.ws-redial-result-row { padding: 8px 0; border-top: 1px solid var(--border-subtle); display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.ws-redial-name { font-weight: 600; font-size: 12px; }
.ws-redial-transcript { font-size: 11px; color: var(--text-muted); width: 100%; margin: 4px 0 0; }

/* Alerts */
.ws-alerts { display: flex; align-items: flex-start; gap: 10px; padding: 10px 16px; background: rgba(245, 158, 11, 0.06); border: 1px solid rgba(245, 158, 11, 0.2); border-radius: 10px; color: #f59e0b; font-size: 11px; }
.ws-alerts-list { display: flex; flex-direction: column; gap: 3px; }
.ws-alerts-list span { color: var(--text-secondary); }

/* Bucket (collapsible section) */
.ws-bucket { border: 1px solid var(--border-subtle); border-radius: 10px; overflow: hidden; background: var(--glass-bg); }
.ws-bucket-live { border-color: rgba(239, 68, 68, 0.25); }
.ws-bucket-header { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 12px 16px; background: none; border: none; cursor: pointer; color: var(--text-primary); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px; }
.ws-bucket-left { display: flex; align-items: center; gap: 8px; }
.ws-bucket-title { font-size: 12px; }
.ws-bucket-count { background: var(--border-subtle); color: var(--text-secondary); font-size: 10px; padding: 2px 8px; border-radius: 10px; font-weight: 600; }
.ws-bucket-body { padding: 0 8px 8px; display: flex; flex-direction: column; gap: 4px; }

/* Empty state */
.ws-empty { padding: 32px 24px; text-align: center; color: var(--text-muted); font-size: 12px; }

/* Call card */
.ws-call-card { border: 1px solid var(--border-subtle); border-radius: 8px; overflow: hidden; transition: border-color 0.2s, box-shadow 0.2s; }
.ws-call-card:hover { border-color: var(--text-muted); }
.ws-live-card { border-color: rgba(239, 68, 68, 0.3); animation: ws-live-glow 2s ease-in-out infinite alternate; }
.ws-hot-card { border-left: 3px solid #ef4444; }
.ws-selected { border-color: #3b82f6; box-shadow: 0 0 0 1px rgba(59,130,246,0.3); }
@keyframes ws-live-glow { from { box-shadow: 0 0 0 0 rgba(239,68,68,0); } to { box-shadow: 0 0 8px 0 rgba(239,68,68,0.15); } }

.ws-call-header { display: flex; align-items: center; gap: 10px; padding: 10px 14px; cursor: pointer; min-height: 48px; }
.ws-check { width: 20px; height: 20px; border-radius: 5px; border: 2px solid var(--border-subtle); background: none; display: flex; align-items: center; justify-content: center; cursor: pointer; flex-shrink: 0; color: var(--text-muted); transition: all 0.15s; }
.ws-checked { background: #3b82f6; border-color: #3b82f6; color: #fff; }
.ws-avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--border-subtle); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: var(--text-secondary); flex-shrink: 0; }
.ws-avatar-hot { background: rgba(239,68,68,0.15); color: #ef4444; }
.ws-call-info { flex: 1; min-width: 0; }
.ws-call-name { font-size: 13px; font-weight: 600; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ws-call-meta { display: flex; align-items: center; gap: 10px; font-size: 11px; color: var(--text-muted); margin-top: 2px; }
.ws-call-email { display: flex; align-items: center; gap: 4px; font-size: 12.5px; font-weight: 600; color: #38bdf8; margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: 0.01em; }
.ws-phone-link { background: none; border: none; color: var(--neon); cursor: pointer; display: flex; align-items: center; gap: 3px; font-size: 11px; padding: 0; }
.ws-phone-link:hover { text-decoration: underline; }
.ws-call-time { opacity: 0.7; }
.ws-call-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.ws-dur { font-size: 11px; font-weight: 600; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.ws-save-btn, .ws-elizabeth-btn { width: 26px; height: 26px; border-radius: 6px; border: 1px solid var(--border-subtle); background: none; color: var(--text-muted); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.15s; }
.ws-save-btn:hover { color: #f59e0b; border-color: #f59e0b; }
.ws-elizabeth-btn:hover { color: var(--neon); border-color: var(--neon); }
.ws-chev-up { transform: rotate(180deg); }

/* Badges */
.ws-badges { display: flex; gap: 4px; flex-wrap: wrap; }
.ws-badge { font-size: 9px; font-weight: 700; letter-spacing: 0.5px; padding: 2px 6px; border-radius: 4px; white-space: nowrap; text-transform: uppercase; }
.ws-badge-live { background: #ef4444; color: #fff; animation: ws-badge-pulse 1.5s ease-in-out infinite; }
.ws-badge-fire { background: rgba(239,68,68,0.12); color: #ef4444; }
.ws-badge-human { background: rgba(251,146,60,0.12); color: #fb923c; }
.ws-badge-vm { background: rgba(107,114,128,0.12); color: #6b7280; }
.ws-badge-na { background: rgba(107,114,128,0.08); color: #9ca3af; }
.ws-badge-bridge { background: rgba(239,68,68,0.12); color: #ef4444; }
.ws-badge-trvm { background: rgba(245,158,11,0.12); color: #f59e0b; }
.ws-badge-cb { background: rgba(59,130,246,0.12); color: #3b82f6; }
.ws-badge-fail { background: rgba(239,68,68,0.12); color: #ef4444; }
.ws-badge-done { background: rgba(239,68,68,0.08); color: #ef4444; }
@keyframes ws-badge-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }

/* Call detail panel */
.ws-call-detail { padding: 12px 14px; border-top: 1px solid var(--border-subtle); background: rgba(0,0,0,0.02); }
.ws-detail-row { display: flex; align-items: center; gap: 10px; padding: 4px 0; font-size: 12px; }
.ws-detail-row > span { color: var(--text-muted); min-width: 70px; font-size: 10px; text-transform: uppercase; letter-spacing: 0.5px; }
.ws-detail-row > strong { color: var(--text-primary); font-weight: 500; }
.ws-detail-warn { color: #ef4444; }
.ws-detail-warn strong { color: #ef4444; }
.ws-cb-flag { color: #3b82f6; }
.ws-detail-section { margin-top: 8px; }
.ws-detail-label { font-size: 9px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 4px; }
.ws-detail-section p { font-size: 12px; line-height: 1.5; color: var(--text-secondary); margin: 0; }
.ws-transcript { font-size: 11px; line-height: 1.6; color: var(--text-secondary); max-height: 200px; overflow-y: auto; white-space: pre-wrap; background: rgba(0,0,0,0.03); padding: 8px; border-radius: 6px; }

/* Tab bar */
.ws-tab-bar { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; padding: 4px 0; }
.ws-tabs { display: flex; gap: 4px; }
.ws-tab { padding: 7px 14px; border-radius: 8px; border: 1px solid var(--border-subtle); background: none; color: var(--text-muted); font-size: 12px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.15s; }
.ws-tab:hover { color: var(--text-primary); border-color: var(--text-muted); }
.ws-tab-active { background: var(--text-primary); color: var(--bg-primary); border-color: var(--text-primary); }
.ws-tab-count { font-size: 10px; opacity: 0.7; }
.ws-filters { display: flex; gap: 4px; }
.ws-filter { padding: 5px 10px; border-radius: 6px; border: none; background: none; color: var(--text-muted); font-size: 10px; font-weight: 600; cursor: pointer; text-transform: uppercase; letter-spacing: 0.5px; transition: all 0.15s; }
.ws-filter:hover { color: var(--text-primary); }
.ws-filter-active { background: rgba(59,130,246,0.1); color: #3b82f6; }

/* Day group (week view) */
.ws-week-section { display: flex; flex-direction: column; gap: 4px; }
.ws-day-group { border: 1px solid var(--border-subtle); border-radius: 8px; overflow: hidden; }
.ws-day-header { display: flex; align-items: center; gap: 8px; width: 100%; padding: 10px 14px; background: none; border: none; cursor: pointer; font-size: 12px; font-weight: 600; color: var(--text-primary); }

/* Archive */
.ws-archive-section { display: flex; flex-direction: column; gap: 4px; }
.ws-archive-info { font-size: 11px; color: var(--text-muted); padding: 8px 0; display: flex; align-items: center; gap: 6px; }
.ws-archive-pager { display: flex; gap: 8px; justify-content: center; padding: 12px 0; }
.ws-page-btn { padding: 7px 18px; border-radius: 8px; border: 1px solid var(--border-subtle); background: none; color: var(--text-primary); font-size: 12px; font-weight: 600; cursor: pointer; transition: all 0.15s; }
.ws-page-btn:hover { border-color: var(--text-primary); }

/* Timezone footer */
.ws-tz-footer { text-align: center; font-size: 10px; color: var(--text-muted); padding: 8px 0; opacity: 0.6; }

/* Pulse animation for live icon */
.ws-pulse { animation: ws-pulse-anim 1.5s ease-in-out infinite; }
@keyframes ws-pulse-anim { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }

/* Responsive */
@media (max-width: 768px) {
  .ws-stat-strip { gap: 2px; padding: 6px; }
  .ws-stat { padding: 6px 8px; }
  .ws-stat strong { font-size: 15px; }
  .ws-stat span { font-size: 8px; }
  .ws-tab-bar { flex-direction: column; }
  .ws-tabs { overflow-x: auto; flex-wrap: nowrap; }
  .ws-filters { overflow-x: auto; }
  .ws-call-header { padding: 8px 10px; gap: 8px; }
  .ws-badges { gap: 3px; }
  .ws-badge { font-size: 8px; padding: 1px 5px; }
}
@media (max-width: 480px) {
  .ws-stat-strip { flex-wrap: wrap; }
  .ws-stat { flex: 0 0 auto; min-width: 80px; }
  .ws-call-meta { flex-wrap: wrap; gap: 6px; }
  .ws-call-right { gap: 4px; }
  .ws-save-btn, .ws-elizabeth-btn { width: 24px; height: 24px; }
}

/* ═══════════════════════════════════════════════════════════════════
   Admin Charts V2 — quality alerts, agent rate strip, layout
   ═══════════════════════════════════════════════════════════════════ */
.v2-charts { display: flex; flex-direction: column; gap: 16px; }
.chart-loading { display: flex; align-items: center; gap: 10px; justify-content: center; padding: 48px; color: var(--text-muted); font-size: 13px; }
.chart-error { display: flex; align-items: center; gap: 8px; padding: 16px; color: #ef4444; font-size: 12px; background: rgba(239,68,68,0.06); border: 1px solid rgba(239,68,68,0.15); border-radius: 10px; }

/* Chart tooltip (shared) */
.chart-tooltip { background: rgba(20,26,23,0.95); border: 1px solid rgba(217,170,87,0.3); border-radius: 10px; padding: 10px 14px; font-size: 12px; backdrop-filter: blur(10px); box-shadow: 0 8px 24px rgba(0,0,0,0.4); }
.chart-tip-label { color: #d9aa57; font-weight: 700; margin-bottom: 4px; }
.chart-tip-row { font-size: 11px; display: flex; align-items: center; gap: 6px; }
.chart-tip-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex-shrink: 0; }
.chart-tip-row strong { color: #e8e6e1; }

/* Quality alert cards grid */
.qa-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 8px; }
.qa-card { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: 10px; border: 1px solid var(--border-subtle); background: var(--glass-bg); transition: border-color 0.2s; }
.qa-card:hover { border-color: var(--text-muted); }
.qa-warn { border-color: rgba(245,158,11,0.3); background: rgba(245,158,11,0.04); }
.qa-warn .qa-card-icon { color: #f59e0b; }
.qa-card-icon { color: var(--text-muted); flex-shrink: 0; }
.qa-card-body { min-width: 0; }
.qa-card-value { font-size: 16px; font-weight: 700; color: var(--text-primary); line-height: 1.2; }
.qa-card-label { font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; font-weight: 600; }

/* Agent rate strip */
.agent-rate-strip { display: flex; gap: 8px; padding: 10px 4px 4px; overflow-x: auto; }
.agent-rate-card { flex: 0 0 auto; min-width: 100px; padding: 8px 12px; border-radius: 8px; border: 1px solid var(--border-subtle); text-align: center; }
.agent-rate-name { font-size: 11px; font-weight: 600; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.agent-rate-val { font-size: 20px; font-weight: 700; color: #2dd4bf; margin: 2px 0; }
.agent-rate-label { font-size: 9px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }

@media (max-width: 768px) {
  .qa-grid { grid-template-columns: repeat(2, 1fr); }
  .agent-rate-card { min-width: 85px; padding: 6px 8px; }
  .agent-rate-val { font-size: 16px; }
}
@media (max-width: 480px) {
  .qa-grid { grid-template-columns: 1fr 1fr; gap: 6px; }
  .qa-card { padding: 10px; gap: 8px; }
  .qa-card-value { font-size: 14px; }
}

/* Live provider evidence must remain readable when a route fails. */
.live-route-row { flex-wrap: wrap; align-items: flex-start; }
.live-route-row.not-configured { opacity: 1; border-left-color: var(--gold-400); }
.live-route-row .inbound-agent-route { min-width: 160px; line-height: 1.6; }
.live-route-row .inbound-agent-badge.not-configured { color: var(--gold-400); }

/* ── Incoming Call Alert Overlay ── */
.ica-overlay { position:fixed; top:0; right:0; z-index:1000; width:min(480px,100vw); max-height:100vh; overflow-y:auto; padding:16px; pointer-events:none; }
.ica-container { pointer-events:auto; display:flex; flex-direction:column; gap:12px; }
.ica-top-bar { display:flex; align-items:center; justify-content:space-between; padding:10px 16px; background:rgba(15,15,25,0.95); border:1px solid rgba(234,179,8,0.3); border-radius:12px; backdrop-filter:blur(12px); }
.ica-top-left { display:flex; align-items:center; gap:8px; color:#eab308; font-size:13px; }
.ica-alert-count { background:#eab308; color:#000; font-size:11px; font-weight:700; padding:2px 7px; border-radius:99px; }
.ica-audio-toggle { display:flex; align-items:center; gap:6px; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.1); border-radius:8px; padding:5px 10px; color:rgba(255,255,255,0.6); font-size:12px; cursor:pointer; transition:all 0.2s; }
.ica-audio-toggle:hover { background:rgba(255,255,255,0.1); }
.ica-audio-on { color:#ef4444; border-color:rgba(239,68,68,0.3); }

.ica-card { background:rgba(15,15,25,0.95); border:1px solid rgba(234,179,8,0.25); border-radius:14px; padding:0; backdrop-filter:blur(12px); overflow:hidden; box-shadow:0 8px 32px rgba(0,0,0,0.4),0 0 0 1px rgba(234,179,8,0.1); animation:ica-slideIn 0.3s ease-out; }
.ica-card-active { border-color:rgba(234,179,8,0.4); }
.ica-card-resolved { border-color:rgba(255,255,255,0.1); opacity:0.75; }
@keyframes ica-slideIn { from { opacity:0; transform:translateX(40px); } to { opacity:1; transform:translateX(0); } }

.ica-card-header { display:flex; align-items:flex-start; justify-content:space-between; padding:14px 16px 10px; gap:10px; }
.ica-header-left { display:flex; align-items:flex-start; gap:10px; }
.ica-pulse { width:36px; height:36px; border-radius:10px; background:rgba(234,179,8,0.15); display:flex; align-items:center; justify-content:center; color:#eab308; flex-shrink:0; animation:ica-pulseAnim 2s infinite; }
.ica-pulse-resolved { animation:none; background:rgba(255,255,255,0.06); color:rgba(255,255,255,0.4); }
@keyframes ica-pulseAnim { 0%,100%{box-shadow:0 0 0 0 rgba(234,179,8,0.3)} 50%{box-shadow:0 0 0 8px rgba(234,179,8,0)} }
.ica-header-title { font-size:13px; font-weight:700; color:#eab308; letter-spacing:0.5px; text-transform:uppercase; }
.ica-header-sub { font-size:12px; color:rgba(255,255,255,0.5); margin-top:2px; display:flex; align-items:center; gap:6px; flex-wrap:wrap; }
.ica-direction { background:rgba(255,255,255,0.06); padding:1px 6px; border-radius:4px; font-size:10px; }
.ica-header-right { display:flex; align-items:center; gap:6px; flex-shrink:0; }
.ica-elapsed { display:flex; align-items:center; gap:4px; font-size:12px; color:rgba(255,255,255,0.5); background:rgba(255,255,255,0.04); padding:3px 8px; border-radius:6px; }
.ica-btn-icon { background:none; border:none; color:rgba(255,255,255,0.4); cursor:pointer; padding:4px; border-radius:6px; transition:all 0.15s; }
.ica-btn-icon:hover { color:#fff; background:rgba(255,255,255,0.1); }
.ica-dismiss:hover { color:#ef4444; }

.ica-status-badges { display:flex; gap:4px; padding:0 16px 10px; flex-wrap:wrap; }
.ica-badge { display:flex; align-items:center; gap:3px; font-size:10px; padding:3px 8px; border-radius:6px; }
.ica-badge-active { background:rgba(239,68,68,0.12); color:#ef4444; border:1px solid rgba(239,68,68,0.2); }
.ica-badge-inactive { background:rgba(255,255,255,0.03); color:rgba(255,255,255,0.25); border:1px solid rgba(255,255,255,0.05); }

.ica-client { padding:0 16px 10px; }
