.ica-history { padding:0 16px 10px; }
.ica-history-title { font-size:11px; font-weight:600; color:rgba(255,255,255,0.4); margin-bottom:4px; display:flex; align-items:center; gap:4px; }
.ica-history-list { display:flex; flex-direction:column; gap:2px; }
.ica-history-item { display:flex; align-items:center; gap:8px; font-size:11px; color:rgba(255,255,255,0.4); }
