.ica-error { display:flex; align-items:center; gap:6px; margin:0 16px 8px; padding:8px 10px; background:rgba(239,68,68,0.1); border:1px solid rgba(239,68,68,0.2); border-radius:8px; color:#ef4444; font-size:12px; }
