.inbox-error { display:flex; align-items:center; gap:4px; color:#ef4444; font-size:12px; margin-bottom:8px; }
.inbox-error button { background:none; border:none; color:#ef4444; cursor:pointer; }

.inbox-actions { display:flex; flex-direction:column; gap:6px; }
