/* ── Federal One 2.0 Agent Command Center ─────────────────────────────── */
.f1-command-center {
  --f1-gold:#d8b66c; --f1-ink:#070b14; --f1-panel:rgba(13,19,31,.9);
  position:relative; overflow:hidden; border:1px solid rgba(216,182,108,.18);
  border-radius:26px; padding:26px; color:#edf2f8;
  background:
    radial-gradient(circle at 84% -20%,rgba(61,101,148,.24),transparent 38%),
    radial-gradient(circle at 8% 8%,rgba(216,182,108,.09),transparent 26%),
    linear-gradient(145deg,#0b111d 0%,#080c15 54%,#0b101a 100%);
  box-shadow:0 24px 70px rgba(0,0,0,.34),inset 0 1px rgba(255,255,255,.04);
}
.f1-command-center::before { content:""; position:absolute; inset:0; pointer-events:none; opacity:.13; background-image:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px); background-size:34px 34px; mask-image:linear-gradient(to bottom,black,transparent 72%); }
.f1-command-hero,.f1-readiness-rail,.f1-command-grid { position:relative; z-index:1; }
.f1-command-hero { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; margin-bottom:22px; }
.f1-command-copy { max-width:720px; }
.f1-overline { display:inline-flex; align-items:center; gap:7px; margin-bottom:10px; color:var(--f1-gold); font-size:10px; line-height:1; font-weight:800; letter-spacing:.18em; }
.f1-command-copy h2 { margin:0; color:#f7f9fc; font-family:Georgia,'Times New Roman',serif; font-size:clamp(2rem,4vw,3.55rem); line-height:.98; letter-spacing:-.045em; font-weight:500; }
.f1-command-copy h2 em { color:var(--f1-gold); font-style:italic; }
.f1-command-copy p { margin:12px 0 0; color:rgba(229,236,246,.52); font-size:14px; }
.f1-availability { display:flex; align-items:center; gap:11px; min-width:160px; padding:12px 14px; border:1px solid rgba(255,255,255,.1); border-radius:14px; background:rgba(255,255,255,.045); color:#fff; cursor:pointer; text-align:left; transition:.2s ease; }
.f1-availability:hover { transform:translateY(-1px); border-color:rgba(216,182,108,.3); }
.f1-availability > span { width:10px; height:10px; border-radius:50%; box-shadow:0 0 0 5px rgba(255,255,255,.04); }
.f1-availability.is-ready > span { background:#46d993; box-shadow:0 0 0 5px rgba(70,217,147,.12),0 0 16px rgba(70,217,147,.5); }
.f1-availability.is-away > span { background:#efad59; }
.f1-availability div { display:flex; flex-direction:column; gap:2px; }
.f1-availability small,.f1-readiness-item small,.f1-panel-heading small,.f1-primary-action small { color:rgba(229,236,246,.36); font-size:8px; font-weight:800; letter-spacing:.15em; }
.f1-availability strong { font-size:13px; }
.f1-readiness-rail { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:1px; overflow:hidden; margin-bottom:20px; border:1px solid rgba(255,255,255,.07); border-radius:16px; background:rgba(255,255,255,.07); }
.f1-simple-dialer { position:relative; z-index:1; display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:13px; width:100%; min-height:68px; margin:0 0 14px; padding:12px 17px; border:1px solid rgba(63,240,175,.24); border-radius:14px; color:#ecfff8; background:linear-gradient(90deg,rgba(39,210,151,.14),rgba(3,19,19,.86)); text-align:left; cursor:pointer; }
.f1-simple-dialer > span { display:grid; place-items:center; width:40px; height:40px; border-radius:11px; color:#071710; background:#69f3bf; box-shadow:0 0 26px rgba(56,235,169,.18); }.f1-simple-dialer div { display:flex; flex-direction:column; gap:3px; }.f1-simple-dialer small { color:rgba(153,255,216,.52); font:700 8px var(--font-mono); letter-spacing:.16em; }.f1-simple-dialer strong { font-size:14px; }.f1-simple-dialer.running { border-color:rgba(255,200,92,.32); background:linear-gradient(90deg,rgba(255,180,55,.11),rgba(3,19,19,.86)); }.f1-simple-dialer:disabled { opacity:.5; cursor:not-allowed; }
.f1-simple-error { position:relative; z-index:1; margin:-7px 0 14px; padding:9px 12px; border:1px solid rgba(255,132,112,.2); border-radius:9px; color:#ffb2a5; background:rgba(80,20,16,.26); font-size:10px; }
.f1-readiness-item { display:flex; align-items:center; gap:10px; min-height:67px; padding:12px 14px; background:rgba(8,13,22,.88); }
.f1-readiness-icon { display:grid; place-items:center; width:31px; height:31px; border-radius:9px; color:var(--f1-gold); background:rgba(216,182,108,.08); border:1px solid rgba(216,182,108,.12); }
