.f1-readiness-item strong { color:rgba(242,246,251,.8); font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.f1-readiness-item.ready .f1-readiness-icon { color:#46d993; background:rgba(70,217,147,.08); border-color:rgba(70,217,147,.16); }
.f1-readiness-item.warn .f1-readiness-icon { color:#efad59; }
.f1-command-grid { display:grid; grid-template-columns:minmax(0,1.75fr) minmax(300px,.78fr); gap:18px; }
.f1-command-main,.f1-collaboration-rail { display:flex; flex-direction:column; gap:16px; min-width:0; }
.f1-primary-actions { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }
.f1-primary-action { position:relative; display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:12px; min-height:112px; padding:16px; border:1px solid rgba(255,255,255,.07); border-radius:17px; overflow:hidden; color:#f5f7fb; text-align:left; cursor:pointer; background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(255,255,255,.02)); transition:.22s ease; }
.f1-primary-action::after { content:""; position:absolute; right:-32px; bottom:-48px; width:100px; height:100px; border-radius:50%; background:currentColor; opacity:.035; }
.f1-primary-action:hover { transform:translateY(-3px); border-color:rgba(216,182,108,.28); box-shadow:0 14px 26px rgba(0,0,0,.22); }
.f1-primary-action > div { display:flex; flex-direction:column; gap:3px; min-width:0; }
.f1-primary-action strong { font-family:Georgia,'Times New Roman',serif; font-size:18px; font-weight:500; }
.f1-primary-action p { margin:1px 0 0; color:rgba(229,236,246,.4); font-size:10px; line-height:1.35; }
.f1-action-icon { display:grid; place-items:center; width:45px; height:45px; border-radius:13px; color:var(--f1-gold); background:rgba(216,182,108,.09); border:1px solid rgba(216,182,108,.13); }
.f1-primary-action.secretary .f1-action-icon { color:#7fb5e7; background:rgba(75,130,182,.11); border-color:rgba(75,130,182,.17); }
.f1-primary-action.intelligence .f1-action-icon { color:#8acbc6; background:rgba(74,162,154,.11); border-color:rgba(74,162,154,.17); }
.f1-primary-action > svg { color:rgba(255,255,255,.25); }
.f1-metric-panel,.f1-activity-panel,.f1-workroom-card,.f1-team-card { border:1px solid rgba(255,255,255,.07); border-radius:17px; background:rgba(12,18,29,.78); box-shadow:inset 0 1px rgba(255,255,255,.025); }
.f1-metric-panel,.f1-activity-panel,.f1-workroom-card,.f1-team-card { padding:16px; }
.f1-panel-heading { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:14px; }
.f1-panel-heading > div { display:flex; flex-direction:column; gap:4px; }
.f1-panel-heading strong { color:rgba(245,248,252,.88); font-size:13px; }
.f1-panel-heading > span { color:#55dca0; font-size:8px; font-weight:800; letter-spacing:.12em; }
.f1-panel-heading > button { display:flex; align-items:center; gap:4px; border:0; background:transparent; color:rgba(229,236,246,.44); font-size:10px; cursor:pointer; }
.f1-metric-grid { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:7px; }
.f1-metric { display:flex; flex-direction:column; gap:5px; min-width:0; padding:12px 10px; border:1px solid rgba(255,255,255,.05); border-radius:11px; background:rgba(255,255,255,.025); }
.f1-metric svg { color:var(--f1-gold); }
.f1-metric strong { margin-top:2px; color:#f8fafc; font-family:Georgia,'Times New Roman',serif; font-size:22px; font-weight:500; }
.f1-metric span { color:rgba(229,236,246,.4); font-size:9px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.f1-empty-pulse { display:flex; align-items:center; justify-content:center; gap:9px; min-height:80px; border:1px dashed rgba(255,255,255,.08); border-radius:12px; color:rgba(229,236,246,.35); font-size:11px; }
.f1-activity-row { width:100%; display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:11px; padding:10px 4px; border:0; border-top:1px solid rgba(255,255,255,.045); background:transparent; color:#fff; text-align:left; cursor:pointer; }
.f1-client-monogram { display:grid; place-items:center; width:34px; height:34px; border-radius:10px; color:var(--f1-gold); background:rgba(216,182,108,.08); font-size:10px; font-weight:800; }
.f1-activity-row div { display:flex; flex-direction:column; gap:3px; min-width:0; }
.f1-activity-row div strong { font-size:12px; }
.f1-activity-row div small { color:rgba(229,236,246,.38); font-size:9px; }
.f1-activity-row > span:last-child { padding:4px 7px; border-radius:6px; font-size:8px; font-weight:800; letter-spacing:.08em; }
.f1-activity-row .hot { color:#ffb86f; background:rgba(245,137,50,.1); }.f1-activity-row .warm { color:#7fb5e7; background:rgba(75,130,182,.1); }
.f1-camera-stage { position:relative; display:grid; place-items:center; min-height:158px; overflow:hidden; border-radius:13px; border:1px solid rgba(255,255,255,.07); background:radial-gradient(circle at 50% 25%,rgba(62,94,128,.24),transparent 45%),#060a11; }
.f1-camera-stage video { display:none; width:100%; aspect-ratio:16/9; object-fit:cover; transform:scaleX(-1); }
.f1-camera-stage.live video { display:block; }
.f1-camera-placeholder { display:flex; flex-direction:column; align-items:center; gap:6px; color:rgba(233,239,247,.48); text-align:center; }
.f1-camera-placeholder svg { color:var(--f1-gold); }.f1-camera-placeholder strong { font-size:11px; }.f1-camera-placeholder span { font-size:9px; color:rgba(233,239,247,.3); }
.f1-camera-live { position:absolute; top:9px; left:9px; display:flex; align-items:center; gap:5px; padding:5px 7px; border-radius:6px; color:#fff; background:rgba(4,11,17,.72); backdrop-filter:blur(10px); font-size:7px; font-weight:800; letter-spacing:.1em; }
.f1-camera-live i { width:6px; height:6px; border-radius:50%; background:#46d993; box-shadow:0 0 9px #46d993; }
.f1-camera-button { width:100%; display:flex; align-items:center; justify-content:center; gap:7px; margin-top:10px; padding:10px; border:1px solid rgba(216,182,108,.24); border-radius:10px; color:#f1d596; background:rgba(216,182,108,.08); font-size:10px; font-weight:750; cursor:pointer; }
.f1-camera-button.stop { color:#f1a5a5; border-color:rgba(239,110,110,.2); background:rgba(239,110,110,.07); }
.f1-chat-feed { display:flex; flex-direction:column; gap:9px; min-height:150px; max-height:220px; overflow:auto; padding-right:3px; }
.f1-chat-empty { display:grid; place-items:center; flex:1; min-height:120px; padding:20px; border:1px dashed rgba(255,255,255,.07); border-radius:11px; color:rgba(229,236,246,.3); text-align:center; font-size:10px; }
.f1-chat-message { padding:9px 10px; border-radius:10px 10px 10px 3px; background:rgba(255,255,255,.045); }
.f1-chat-message.mine { margin-left:20px; border-radius:10px 10px 3px 10px; background:rgba(216,182,108,.09); }
.f1-chat-message > div { display:flex; justify-content:space-between; gap:8px; }.f1-chat-message strong { color:var(--f1-gold); font-size:9px; }.f1-chat-message time { color:rgba(229,236,246,.27); font-size:8px; }
.f1-chat-message p { margin:4px 0 0; color:rgba(239,243,249,.72); font-size:10px; line-height:1.45; }
.f1-chat-error { margin:7px 0; color:#f09b9b; font-size:9px; }
.f1-chat-compose { display:grid; grid-template-columns:1fr auto; gap:7px; margin-top:10px; }
.f1-chat-compose input { min-width:0; padding:10px 11px; border:1px solid rgba(255,255,255,.08); border-radius:10px; outline:0; color:#eef3f9; background:rgba(255,255,255,.035); font:inherit; font-size:10px; }
.f1-chat-compose input:focus { border-color:rgba(216,182,108,.28); }.f1-chat-compose button { display:grid; place-items:center; width:36px; border:1px solid rgba(216,182,108,.22); border-radius:10px; color:var(--f1-gold); background:rgba(216,182,108,.08); cursor:pointer; }
.f1-mobile-companion { margin:0 auto; max-width:520px; padding:38px 20px 24px; text-align:center; }
.f1-mobile-orb { display:grid; place-items:center; width:54px; height:54px; margin:0 auto 18px; border:1px solid rgba(216,182,108,.25); border-radius:18px; color:var(--f1-gold); background:linear-gradient(145deg,rgba(216,182,108,.13),rgba(216,182,108,.03)); box-shadow:0 14px 35px rgba(0,0,0,.25); }
.f1-mobile-companion h2 { margin:0; color:#f7f9fc; font-family:Georgia,'Times New Roman',serif; font-size:29px; font-weight:500; }.f1-mobile-companion p { margin:12px auto 24px; color:rgba(229,236,246,.5); font-size:12px; line-height:1.6; }
.f1-mobile-active-client { display:flex; flex-direction:column; gap:5px; margin:0 0 18px; padding:18px; border:1px solid rgba(239,68,68,.2); border-radius:14px; color:#fef2f2; background:rgba(26,7,7,.8); text-align:left; }.f1-mobile-active-client small { color:#f87171; font:800 8px var(--font-mono); letter-spacing:.14em; }.f1-mobile-active-client strong { font-size:18px; }.f1-mobile-active-client span { color:rgba(254,226,226,.5); font-size:12px; }.f1-mobile-active-client button { display:flex; align-items:center; justify-content:space-between; margin-top:9px; padding:10px 12px; border:0; border-radius:9px; color:#200000; background:#f87171; font-weight:800; }.f1-mobile-active-client.empty { opacity:.7; }
.f1-mobile-note { display:grid; grid-template-columns:1fr auto; gap:6px; margin-top:6px; }.f1-mobile-note input { min-width:0; padding:10px; border:1px solid rgba(92,255,195,.16); border-radius:8px; color:#eafff7; background:rgba(0,8,9,.8); }.f1-mobile-note button { display:grid; place-items:center; margin:0; padding:10px; }.f1-mobile-note-row { margin:5px 0 0!important; padding:8px; border-left:2px solid rgba(71,232,172,.36); color:rgba(225,246,239,.6)!important; background:rgba(255,255,255,.02); font-size:10px!important; }
.f1-mobile-actions { display:flex; flex-direction:column; gap:9px; }.f1-mobile-actions button { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:11px; padding:15px; border:1px solid rgba(255,255,255,.08); border-radius:14px; color:#f3f6fa; background:rgba(255,255,255,.04); text-align:left; cursor:pointer; }.f1-mobile-actions button svg:first-child { color:var(--f1-gold); }

/* SourceView lives inside the critical lead action sheet. */
.sourceview-icon { color:#87cec7!important; background:rgba(70,161,153,.12)!important; }
.sourceview-panel { margin-top:12px; padding:14px; border:1px solid rgba(118,200,193,.16); border-radius:13px; background:rgba(8,19,24,.66); }
.sourceview-heading { display:flex; align-items:center; justify-content:space-between; gap:10px; }.sourceview-heading > div { display:flex; flex-direction:column; gap:3px; }.sourceview-heading small { color:#78c7c0; font-size:8px; font-weight:800; letter-spacing:.13em; }.sourceview-heading strong { color:#f2f7f8; font-size:12px; }.sourceview-heading > span { padding:4px 7px; border-radius:6px; color:#efc378; background:rgba(239,195,120,.1); font-size:7px; font-weight:800; letter-spacing:.11em; }
.sourceview-panel > p { margin:10px 0; color:rgba(231,242,243,.45); font-size:9px; line-height:1.5; }.sourceview-links { display:flex; gap:6px; margin-bottom:11px; }.sourceview-links a { display:flex; align-items:center; gap:5px; padding:7px 9px; border:1px solid rgba(255,255,255,.08); border-radius:8px; color:#d9eeec; background:rgba(255,255,255,.035); text-decoration:none; font-size:9px; }
.sourceview-panel label { display:flex; flex-direction:column; gap:5px; margin-top:8px; color:rgba(231,242,243,.5); font-size:9px; }.sourceview-panel input { width:100%; padding:9px 10px; border:1px solid rgba(255,255,255,.08); border-radius:8px; outline:0; color:#f2f7f8; background:rgba(255,255,255,.035); font:inherit; font-size:10px; }.sourceview-panel input:focus { border-color:rgba(118,200,193,.3); }.sourceview-save { width:100%; margin-top:10px; padding:9px; border:1px solid rgba(118,200,193,.25); border-radius:8px; color:#bce7e3; background:rgba(70,161,153,.11); font-size:9px; font-weight:750; cursor:pointer; }.sourceview-notice { margin-top:8px; color:#efc378; font-size:9px; }

@media (max-width:1100px) {
  .f1-command-grid { grid-template-columns:1fr; }.f1-collaboration-rail { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }.f1-metric-grid { grid-template-columns:repeat(3,minmax(0,1fr)); }
}
@media (max-width:820px) {
  .f1-command-center { padding:18px; border-radius:20px; }.f1-command-hero { align-items:flex-start; flex-direction:column; }.f1-readiness-rail { grid-template-columns:repeat(2,minmax(0,1fr)); }.f1-primary-actions { grid-template-columns:1fr; }.f1-collaboration-rail { grid-template-columns:1fr; }
}
@media (max-width:760px) {
  .f1-command-center { padding:0; border:0; background:transparent; box-shadow:none; }.f1-command-center::before { display:none; }
}

/* Federal One 2.1 — simple command deck. This replaces the legacy sidebar. */
.f1-v2-shell {
  display:block;
  padding:0;
  background:#010807;
}
.f1-command-bar {
  position:sticky; top:0; z-index:150; display:grid; grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center; gap:18px; min-height:76px; padding:10px clamp(16px,3vw,44px);
  border-bottom:1px solid rgba(84,255,187,.16);
  background:linear-gradient(180deg,rgba(0,15,12,.96),rgba(0,9,8,.9));
