/* ═══════════════════════════════════════════════════════════════════════════
   FEDERAL ONE 2.0 — MATRIX OPERATIONS GRID
   Full replacement shell shared by public access and authenticated screens.
   ═══════════════════════════════════════════════════════════════════════════ */

@keyframes matrix-fall {
  0% { transform:translate3d(0,-115%,0); filter:blur(.2px); }
  50% { transform:translate3d(5px,15%,0); filter:blur(0); }
  100% { transform:translate3d(-4px,120%,0); filter:blur(.4px); }
}
@keyframes matrix-scan-right { from { transform:translateX(-130%); } to { transform:translateX(130%); } }
@keyframes matrix-scan-left { from { transform:translateX(130%); } to { transform:translateX(-130%); } }
@keyframes matrix-diagonal-forward { from { transform:translate3d(-70vw,70vh,0) rotate(-34deg) scale(.7); } to { transform:translate3d(130vw,-70vh,0) rotate(-34deg) scale(1.25); } }
@keyframes matrix-diagonal-back { from { transform:translate3d(110vw,65vh,0) rotate(31deg) scale(1.2); } to { transform:translate3d(-90vw,-65vh,0) rotate(31deg) scale(.7); } }
@keyframes matrix-core-pulse { 0%,100% { opacity:.38; transform:translate(-50%,-50%) scale(.9); } 50% { opacity:.72; transform:translate(-50%,-50%) scale(1.08); } }
@keyframes matrix-panel-in { from { opacity:0; transform:translateY(18px) scale(.97); } to { opacity:1; transform:translateY(0) scale(1); } }
@keyframes matrix-tunnel-zoom { 0% { opacity:0; transform:translate(-50%,-50%) scale(.08) rotate(0deg); } 24% { opacity:.48; } 100% { opacity:0; transform:translate(-50%,-50%) scale(2.3) rotate(12deg); } }
@keyframes signal-crawl { from { transform:translateY(-40%); } to { transform:translateY(40%); } }
@keyframes matrix-bloom-pulse {
  0%,100% { opacity:.35; transform:translate(-50%,-50%) scale(.92); }
  50% { opacity:.7; transform:translate(-50%,-50%) scale(1.1); }
}
@keyframes matrix-scanline-drift {
  from { transform:translateY(0); }
  to { transform:translateY(6px); }
}
@keyframes matrix-floor-shimmer {
  0%,100% { opacity:.9; }
  50% { opacity:1; }
}

/* --- Login corridor (v2 canvas-based) --- */
.matrix-field-v2 {
  position:absolute; inset:0; z-index:-2; overflow:hidden; background:#010806;
}
.matrix-rain-canvas {
  position:absolute; inset:0; z-index:1;
}
.matrix-floor-grid {
  position:absolute; left:-30%; right:-30%; bottom:-55%; height:100%;
  z-index:2; transform-origin:center top; transform:rotateX(72deg);
  background-image:
    linear-gradient(rgba(255,58,42,.18) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,58,42,.18) 1px, transparent 1px);
  background-size:44px 44px;
  mask-image:linear-gradient(to bottom, transparent 5%, black 30%, black 65%, transparent 95%);
  animation:matrix-floor-shimmer 6s ease-in-out infinite;
}
.matrix-floor-grid::before {
  content:""; position:absolute; inset:0;
  background:radial-gradient(ellipse 50% 40% at 50% 20%, rgba(255,58,42,.14), transparent 70%);
}
.matrix-bloom {
  position:absolute; left:50%; top:50%; width:min(60vw,700px); aspect-ratio:1;
  z-index:3; border-radius:50%; transform:translate(-50%,-50%);
  background:radial-gradient(circle, rgba(255,58,42,.22), rgba(255,58,42,.08) 30%, transparent 65%);
  filter:blur(28px); animation:matrix-bloom-pulse 5.5s ease-in-out infinite;
  pointer-events:none;
}
.matrix-scanlines {
  position:absolute; inset:0; z-index:4; pointer-events:none;
  background:repeating-linear-gradient(
    0deg,
    transparent 0px, transparent 3px,
    rgba(255,58,42,.025) 3px, rgba(255,58,42,.025) 4px
  );
  animation:matrix-scanline-drift 3s linear infinite;
}
.matrix-depth-fog {
  position:absolute; inset:0; z-index:5; pointer-events:none;
  background:
    radial-gradient(ellipse at 50% 50%, transparent 12%, rgba(0,8,6,.35) 45%, rgba(1,3,2,.92) 100%);
}

/* ops-density corridor (post-login, dimmed) */
.matrix-field-ops { opacity:.45; pointer-events:none; position:fixed; z-index:0; filter:saturate(1.2) contrast(1.05); }
.matrix-field-ops .matrix-floor-grid { opacity:.35; }
.matrix-field-ops .matrix-bloom { opacity:.2; }
.matrix-field-ops .matrix-scanlines { opacity:.4; }


/* --- Login access card (glass overlay) --- */
.matrix-access-page {
  position:relative; isolation:isolate; display:grid; place-items:center;
  min-height:100svh; overflow:hidden; padding:24px;
  color:#eafff6; background:#010706;
}
.matrix-access-page::before {
  content:""; position:absolute; inset:0; z-index:-1; pointer-events:none;
  background:
    radial-gradient(circle at 50% 49%,rgba(255,58,42,.07),transparent 8%),
    radial-gradient(ellipse at 50% 53%,rgba(0,152,98,.12),transparent 30%);
}
.matrix-access-page::after {
  content:""; position:absolute; inset:0; z-index:5; pointer-events:none;
  background:radial-gradient(ellipse at center,transparent 15%,rgba(0,7,6,.3) 50%,rgba(0,2,2,.85) 100%);
}

.matrix-access-card {
  position:relative; z-index:10; width:min(380px,calc(100vw - 38px)); padding:38px 34px 32px;
  border:1px solid rgba(255,58,42,.12); border-radius:6px; text-align:center;
  background:rgba(2,18,14,.38);
  box-shadow:0 0 0 1px rgba(255,58,42,.03) inset, 0 32px 80px rgba(0,0,0,.5), 0 0 80px rgba(0,229,143,.06);
  backdrop-filter:blur(24px) saturate(1.2);
  animation:matrix-panel-in .7s cubic-bezier(.16,1,.3,1) both;
}
.matrix-access-card::before,.matrix-access-card::after { content:""; position:absolute; width:18px; height:18px; border-color:rgba(255,58,42,.28); opacity:1; }
.matrix-access-card::before { top:-1px; left:-1px; border-left:1px solid; border-top:1px solid; }
.matrix-access-card::after { right:-1px; bottom:-1px; border-right:1px solid; border-bottom:1px solid; }

.matrix-access-brand {
  margin:0 0 4px; color:rgba(255,58,42,.72);
  font:300 13px/1 var(--font-mono); letter-spacing:.5em; text-transform:uppercase;
}
.matrix-access-title {
  display:block; margin-bottom:6px; color:rgba(255,58,42,.7);
  font:300 11px var(--font-mono); letter-spacing:.42em; text-transform:uppercase;
}
.matrix-access-kicker {
  display:block; margin-bottom:25px; color:rgba(174,255,225,.55);
  font:300 9px var(--font-mono); letter-spacing:.32em;
}
.matrix-access-form { display:flex; flex-direction:column; gap:18px; }
.matrix-access-form .pin-input-row { justify-content:center; gap:12px; }
.matrix-access-form .pin-input-box {
  width:56px; height:66px;
  border:1px solid rgba(255,58,42,.32); border-radius:4px;
  color:#dffff3;
  background:rgba(0,20,15,.5);
  box-shadow:0 0 24px rgba(255,58,42,.06), inset 0 0 18px rgba(255,58,42,.04);
  font:800 24px var(--font-mono);
  transition:border-color .2s, box-shadow .2s;
}
.matrix-access-form .pin-input-box:focus {
  border-color:rgba(255,58,42,.7);
  box-shadow:0 0 28px rgba(255,58,42,.18), inset 0 0 22px rgba(255,58,42,.06);
  outline:0;
}
.matrix-enter {
  min-height:44px; border:1px solid rgba(255,58,42,.35); border-radius:3px;
  color:#03120d;
  background:linear-gradient(90deg,#28e89a,#7affc8,#28e89a);
  background-size:200% 100%;
  font:700 10px var(--font-mono); letter-spacing:.25em;
  transition:.2s ease;
}
.matrix-enter:hover:not(:disabled) { transform:translateY(-2px); background-position:100% 0; box-shadow:0 0 34px rgba(255,58,42,.2); }
.matrix-enter:disabled { opacity:.55; cursor:wait; }
.matrix-access-error { color:#ff9f9f; font:600 10px var(--font-mono); }
.matrix-access-card.has-error { border-color:rgba(255,105,105,.35); }
.matrix-access-card.setup-card { width:min(400px,calc(100vw - 38px)); }
.matrix-access-form.stacked { text-align:left; }
.matrix-access-form.stacked label { color:rgba(174,255,225,.45); font:300 8px var(--font-mono); letter-spacing:.18em; }
.matrix-pin-single {
  width:100%; height:58px; border:1px solid rgba(255,58,42,.2); border-radius:3px;
  outline:0; color:#dffff3; background:rgba(0,20,15,.5);
  text-align:center; font:600 25px var(--font-mono); letter-spacing:.65em;
  transition:border-color .2s, box-shadow .2s;
}
.matrix-pin-single:focus {
  border-color:rgba(255,58,42,.55);
  box-shadow:0 0 22px rgba(255,58,42,.12);
}

/* Authenticated operations shell */
