.f1-team-health { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin:-2px 0 16px; }.f1-health-service,.f1-health-agent { display:grid; grid-template-columns:auto 1fr; align-items:center; gap:10px; min-height:58px; padding:10px 13px; border:1px solid rgba(239,68,68,.1); border-radius:11px; background:rgba(3,18,18,.82); }.f1-team-health > div > span { width:8px; height:8px; border-radius:50%; }.f1-team-health > div > span.ok { background:#39efaa; box-shadow:0 0 12px #39efaa; }.f1-team-health > div > span.warn { background:#ffbe55; box-shadow:0 0 10px rgba(255,190,85,.7); }.f1-team-health > div > span.bad { background:#ff6d79; }.f1-team-health div div { display:flex; flex-direction:column; gap:3px; min-width:0; }.f1-team-health small { overflow:hidden; color:rgba(172,236,214,.48); font:700 8px var(--font-mono); letter-spacing:.1em; text-overflow:ellipsis; white-space:nowrap; }.f1-team-health strong { overflow:hidden; color:#effcf7; font-size:10px; text-overflow:ellipsis; white-space:nowrap; }

.sourceview-intro { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:14px; margin-bottom:16px; padding:16px 18px; border:1px solid rgba(239,68,68,.14); border-radius:12px; background:linear-gradient(90deg,rgba(239,68,68,.08),rgba(2,15,16,.62)); }.sourceview-intro-icon { display:grid; place-items:center; width:43px; height:43px; border-radius:10px; color:var(--matrix,#33eaa2); border:1px solid rgba(239,68,68,.18); background:rgba(239,68,68,.06); }.sourceview-intro div:nth-child(2) { display:flex; flex-direction:column; gap:3px; }.sourceview-intro small { color:#62eab7; font:800 8px var(--font-mono); letter-spacing:.16em; }.sourceview-intro strong { color:#ecfbf6; font-size:13px; }.sourceview-intro p { margin:1px 0 0; color:rgba(215,240,232,.45); font-size:10px; }.sourceview-intro > span { color:#8cffd4; font:800 8px var(--font-mono); letter-spacing:.12em; }
.contact-intelligence-action { width:100%; display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:11px; margin:15px 0 4px; padding:13px; border:1px solid rgba(239,68,68,.15); border-radius:10px; color:#defff2; background:rgba(239,68,68,.055); text-align:left; }.contact-intelligence-action > svg:first-child { color:#48e8ac; }.contact-intelligence-action span { display:flex; flex-direction:column; gap:3px; }.contact-intelligence-action small { color:rgba(207,238,228,.42); font-size:9px; }
.contact-name-link { display:block; padding:0; border:0; color:#effff8; background:none; font:700 13px var(--font-sans); text-align:left; cursor:pointer; }
.contact-name-link:hover { color:#78ffca; text-shadow:0 0 12px rgba(239,68,68,.45); }
.sourceview-panel { border-color:rgba(239,68,68,.17); background:rgba(2,17,17,.82); }.sourceview-links { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }.sourceview-links a { justify-content:space-between; min-height:47px; border-color:rgba(239,68,68,.11); background:rgba(239,68,68,.035); }.sourceview-links a > span { display:flex; flex-direction:column; gap:3px; }.sourceview-links a strong { font-size:9px; }.sourceview-links a small { color:rgba(206,238,227,.38); font-size:8px; }.sourceview-saved { margin-top:14px; padding-top:12px; border-top:1px solid rgba(239,68,68,.09); }.sourceview-saved-head { display:flex; justify-content:space-between; margin-bottom:8px; color:#e8faf4; font-size:10px; }.sourceview-saved-head span { color:#47e6aa; }.sourceview-loading,.sourceview-empty { padding:12px; color:rgba(212,240,230,.38); font-size:9px; text-align:center; }.sourceview-finding { display:grid; grid-template-columns:1fr auto; align-items:center; gap:10px; padding:10px 0; border-top:1px solid rgba(255,255,255,.045); color:#e8faf4; text-decoration:none; }.sourceview-finding div { display:flex; flex-direction:column; gap:3px; }.sourceview-finding strong { overflow-wrap:anywhere; font-size:9px; }.sourceview-finding small { color:rgba(205,237,226,.36); font-size:8px; text-transform:capitalize; }
.sourceview-search-all { display:flex; align-items:center; justify-content:center; gap:8px; width:100%; min-height:46px; margin:12px 0; border:1px solid rgba(67,255,186,.35); border-radius:9px; color:#03140d; background:linear-gradient(90deg,#32e7a2,#99ffd8); font:800 10px var(--font-mono); letter-spacing:.07em; cursor:pointer; }
.sourceview-search-all:disabled { opacity:.6; cursor:wait; }
.sourceview-known { margin:12px 0; padding:12px; border:1px solid rgba(67,255,186,.14); border-radius:10px; background:rgba(49,234,166,.045); }
.sourceview-known-title { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:10px; }
.sourceview-known-title strong { color:#eafff7; font-size:11px; }.sourceview-known-title small { color:rgba(197,239,224,.38); font-size:8px; }
.sourceview-known-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
.sourceview-known-grid > div { min-height:58px; padding:9px; border:1px solid rgba(91,255,197,.08); border-radius:8px; background:rgba(0,9,8,.55); }
.sourceview-known-grid span { display:block; margin-bottom:6px; color:#55e9af; font:800 7px var(--font-mono); letter-spacing:.12em; }
.sourceview-known-grid strong { display:block; overflow-wrap:anywhere; color:rgba(237,255,249,.76); font-size:9px; line-height:1.45; }
.direct-call-result { margin-top:12px; padding:12px; border:1px solid rgba(92,255,195,.14); border-radius:10px; background:rgba(2,17,18,.8); }.direct-call-result > strong { display:block; margin-bottom:9px; color:#eafff7; font-size:11px; }.direct-call-result > div { display:flex; flex-wrap:wrap; gap:6px; }.direct-call-result button { padding:8px 10px; border:1px solid rgba(74,238,177,.16); border-radius:8px; color:#cffff0; background:rgba(239,68,68,.055); font-size:9px; cursor:pointer; }.direct-call-result button:hover { border-color:rgba(74,238,177,.42); background:rgba(239,68,68,.12); }

