  .f1-v2-shell { padding:0; }.f1-v2-shell .content-area { border:0; border-radius:0; }.f1-v2-shell .sidebar { position:fixed; top:0; height:100vh; border-radius:0; }.f1-v2-shell .content-wrap { padding:20px 15px 42px; }.f1-v2-shell .topbar { padding:0 15px; }
