/* Final cascade for the 2.1 command deck after all legacy compatibility rules. */
.f1-v2-shell { display:block; padding:0; gap:0; background:#010807; }
.f1-v2-shell > .content-area { position:relative; z-index:2; width:100%; min-height:calc(100vh - 76px); border:0; border-radius:0; overflow:visible; background:linear-gradient(180deg,rgba(8,0,0,.7),rgba(8,0,0,.86)); }
.f1-v2-shell .f1-status-strip { height:48px; padding:0 clamp(18px,4vw,58px); background:rgba(10,0,0,.5); }
.f1-v2-shell .content-wrap { max-width:1480px; margin:0 auto; padding:clamp(24px,4vw,56px) clamp(18px,4vw,58px) 70px; }
@media (max-width:760px) {
  .f1-v2-shell .f1-status-strip { height:43px; padding:0 15px; }
