}

/* ── Extra Info page ───────────────────────────────────────────────── */
.extra-info-page { max-width:900px; margin:0 auto; }
.extra-info-header h2 { font-size:20px; font-weight:700; color:#fee2e2; margin:0 0 4px; }
.extra-info-header p { font-size:13px; color:rgba(160,220,190,.6); margin:0 0 20px; }

.extra-info-fields { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:16px; }
.extra-info-field label { display:block; font-size:11px; font-weight:600; color:rgba(160,220,190,.55); text-transform:uppercase; letter-spacing:.5px; margin-bottom:4px; }
.extra-info-field .required { color:#ff6b6b; }
.extra-info-input {
  width:100%; padding:9px 12px; border:1px solid rgba(255,58,42,.18); border-radius:8px;
  background:rgba(20,0,0,.6); color:#fee2e2; font:14px var(--font-mono); outline:none;
  transition:border-color .2s;
}
.extra-info-input:focus { border-color:rgba(255,58,42,.45); }
.extra-info-input::placeholder { color:rgba(120,200,170,.35); }

.extra-info-actions { display:flex; gap:10px; margin-bottom:16px; flex-wrap:wrap; }
.extra-info-btn {
  display:inline-flex; align-items:center; gap:6px; padding:8px 18px; border-radius:8px;
  font:600 13px var(--font-mono); cursor:pointer; transition:background .2s,border-color .2s; white-space:nowrap;
  border:1px solid rgba(255,58,42,.25); background:rgba(255,58,42,.06); color:#fca5a5;
}
.extra-info-btn.primary { background:rgba(255,58,42,.12); border-color:rgba(255,58,42,.35); }
.extra-info-btn.primary:hover:not(:disabled) { background:rgba(255,58,42,.22); }
.extra-info-btn.accent { background:rgba(0,180,255,.1); border-color:rgba(0,180,255,.3); color:#7ad4ff; }
.extra-info-btn.accent:hover:not(:disabled) { background:rgba(0,180,255,.2); }
.extra-info-btn:disabled { opacity:.4; cursor:default; }
.extra-info-error { display:flex; align-items:center; gap:6px; padding:10px 14px; border-radius:8px; background:rgba(255,60,60,.1); color:#ff6b6b; font-size:13px; margin-bottom:16px; }

.extra-info-known-section { padding:14px 16px; border-radius:10px; background:rgba(30,0,0,.55); border:1px solid rgba(255,58,42,.12); margin-bottom:16px; }
.extra-info-section-label { font-size:10px; font-weight:700; letter-spacing:1px; color:rgba(160,220,190,.5); text-transform:uppercase; margin-bottom:10px; }
.extra-info-known-grid { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
.extra-info-known-grid > div { display:flex; align-items:baseline; gap:6px; font-size:12px; color:rgba(200,255,230,.6); }
.extra-info-known-grid > div span { color:rgba(160,220,190,.45); min-width:70px; }
.extra-info-known-grid > div strong { color:#fecaca; font-weight:500; word-break:break-word; }
.extra-info-records-count { margin-top:8px; font-size:11px; color:rgba(160,220,190,.35); }

.extra-info-groups { display:flex; flex-direction:column; gap:6px; margin-bottom:16px; }
.extra-info-group { border-radius:8px; border:1px solid rgba(255,58,42,.1); overflow:hidden; background:rgba(20,0,0,.4); }
.extra-info-group.highlight { border-color:rgba(255,58,42,.3); background:rgba(40,0,0,.55); }
.extra-info-group-header {
  width:100%; display:flex; align-items:center; gap:8px; padding:10px 14px; border:none; background:none;
  color:#fca5a5; font:600 13px var(--font-mono); cursor:pointer; text-align:left;
}
.extra-info-group-header:hover { background:rgba(255,58,42,.05); }
.extra-info-group-count { margin-left:auto; font-size:11px; opacity:.5; font-weight:400; }
.extra-info-links { display:grid; grid-template-columns:repeat(auto-fill,minmax(230px,1fr)); gap:4px; padding:4px 10px 10px; }
.extra-info-link {
  display:flex; align-items:center; gap:7px; padding:7px 10px; border-radius:6px; color:rgba(200,255,230,.75);
  font-size:12px; text-decoration:none; transition:background .15s,color .15s;
}
.extra-info-link:hover { background:rgba(255,58,42,.08); color:#fecaca; }
.extra-info-external { opacity:.3; margin-left:auto; flex-shrink:0; }
.extra-info-link:hover .extra-info-external { opacity:.7; }

.extra-info-paste-section { padding:14px 16px; border-radius:10px; background:rgba(30,0,0,.45); border:1px solid rgba(255,58,42,.1); margin-bottom:16px; }
.extra-info-paste-hint { font-size:12px; color:rgba(160,220,190,.5); margin:0 0 10px; }
.extra-info-textarea {
  width:100%; padding:10px 12px; border:1px solid rgba(255,58,42,.15); border-radius:8px;
  background:rgba(0,15,8,.7); color:#fee2e2; font:13px var(--font-mono); outline:none; resize:vertical;
  transition:border-color .2s; min-height:80px;
}
.extra-info-textarea:focus { border-color:rgba(255,58,42,.4); }
.extra-info-textarea::placeholder { color:rgba(120,200,170,.3); }
.extra-info-paste-actions { display:flex; align-items:center; gap:10px; margin-top:10px; }
.extra-info-save-notice { font-size:12px; }
.extra-info-save-notice.success { color:#fca5a5; }
.extra-info-save-notice.fail { color:#ff6b6b; }

.extra-info-findings { margin-bottom:16px; }
.extra-info-finding {
  display:flex; align-items:flex-start; gap:8px; padding:8px 12px; border-radius:6px; font-size:12px;
  border:1px solid rgba(255,58,42,.06); background:rgba(20,0,0,.35); margin-bottom:4px;
}
.extra-info-finding .finding-value { color:#fecaca; flex:1; white-space:pre-wrap; word-break:break-word; }
.extra-info-finding .finding-meta { color:rgba(160,220,190,.35); font-size:11px; white-space:nowrap; }

.contact-intelligence-action.extra-info-card-btn { border-color:rgba(0,180,255,.25); }
.contact-intelligence-action.extra-info-card-btn:hover { background:rgba(0,180,255,.12); border-color:rgba(0,180,255,.4); }

.sourceview-thatsthem { border:1px solid rgba(255,58,42,.25) !important; background:rgba(40,0,0,.4) !important; }

@keyframes spin { to { transform:rotate(360deg); } }
.spin { animation:spin .8s linear infinite; }

/* ── Turn 3: Extra Info quick-access elements ─────────────────────── */

/* Command-bar green button */
.f1-extra-info-quick {
  display:inline-flex; align-items:center; gap:5px;
  padding:5px 12px; border-radius:6px; font-size:12px; font-weight:600;
  background:rgba(255,58,42,.12); color:#fca5a5;
  border:1px solid rgba(255,58,42,.3); cursor:pointer;
  transition:background .15s, border-color .15s;
}
