/* ── Camera Widget ─────────────────────────────────────────────────── */
@keyframes camPulse { 0%,100% { opacity:.4; } 50% { opacity:1; } }
.cam-pulse { animation:camPulse 1.2s ease-in-out infinite; }

/* ── Shared card styles ─────────────────────────────────────────── */
.cam-agent-card {
  border-radius:12px; overflow:hidden; position:relative;
  background:rgba(30,0,0,.5); border:1px solid rgba(255,58,42,.1);
  transition:border-color .3s;
}
.cam-agent-card.self { border-color:rgba(255,58,42,.3); }
.cam-agent-card.live { border-color:rgba(255,58,42,.25); }
.cam-agent-card.empty { border-style:dashed; }

.cam-agent-vid {
  width:100%; aspect-ratio:4/3; background:#0a0a0a;
  display:flex; align-items:center; justify-content:center;
  position:relative; overflow:hidden;
}
.cam-agent-vid video {
  width:100%; height:100%; object-fit:cover; transform:scaleX(-1);
}
.cam-agent-vid .cam-snapshot {
  width:100%; height:100%; object-fit:cover; transform:scaleX(-1);
}
.cam-no-feed {
  display:flex; flex-direction:column; align-items:center; gap:6px;
  color:rgba(160,220,190,.35); font-size:12px; padding:12px;
}
.cam-agent-label {
  display:flex; align-items:center; gap:6px;
  padding:6px 10px; font-size:11px; font-weight:600; color:#fecaca;
}
.cam-agent-name { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.cam-timer {
  display:inline-flex; align-items:center; gap:3px;
  font-size:10px; font-weight:600; color:#ff3a2a; opacity:.8;
  font-variant-numeric:tabular-nums; flex-shrink:0;
}
.cam-dot {
  width:8px; height:8px; border-radius:50%; flex-shrink:0;
  background:rgba(160,220,190,.2);
}
.cam-dot.on { background:#ff3a2a; box-shadow:0 0 6px rgba(255,58,42,.4); }

.cam-live-badge {
  position:absolute; bottom:6px; left:6px;
  padding:2px 6px; border-radius:4px; font-size:9px; font-weight:700; letter-spacing:1px;
  background:rgba(255,40,40,.85); color:#fff;
  animation:camPulse 2s ease-in-out infinite; z-index:2;
}

.cam-tile-connect {
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px;
  width:100%; height:100%; border:none; background:transparent;
  color:#fca5a5; cursor:pointer; font-size:12px; font-weight:600;
  transition:background .2s;
}
.cam-tile-connect:hover { background:rgba(255,58,42,.06); }
.cam-tile-connect svg { opacity:.6; }

.cam-retry-btn {
  padding:4px 12px; border-radius:6px; border:1px solid rgba(255,100,100,.3);
  background:rgba(255,60,60,.1); color:#ff8080; font-size:10px; cursor:pointer;
  margin-top:4px;
}
.cam-retry-btn:hover { background:rgba(255,60,60,.2); }

.cam-disconnect-btn {
  margin-left:auto; width:22px; height:22px; border-radius:5px; border:none;
  background:rgba(255,60,60,.15); color:#ff8080; cursor:pointer;
  display:flex; align-items:center; justify-content:center;
  transition:background .15s; flex-shrink:0;
}
.cam-disconnect-btn:hover { background:rgba(255,60,60,.3); }

/* ── Minimized button (both roles) ───────────────────────────────── */
.cam-minimized {
  position:fixed; top:80px; right:16px; z-index:10000;
  width:40px; height:40px; border-radius:10px;
  background:rgba(14,0,0,.92); border:1.5px solid rgba(255,58,42,.25);
  color:#fca5a5; cursor:pointer;
  display:flex; align-items:center; justify-content:center; gap:4px;
  box-shadow:0 4px 16px rgba(0,0,0,.4);
  transition:background .2s, border-color .2s;
}
.cam-minimized:hover { background:rgba(30,0,0,.95); border-color:rgba(255,58,42,.45); }
.cam-minimized-count {
  font-size:10px; font-weight:700; color:#ff3a2a;
  min-width:14px; height:14px; border-radius:7px;
  background:rgba(255,58,42,.15); display:flex; align-items:center; justify-content:center;
}

/* ── Admin panel: fixed right-side team grid ─────────────────────── */
.cam-admin-panel {
  position:fixed; top:70px; right:12px; z-index:10000;
  width:280px; max-height:calc(100vh - 90px); overflow-y:auto;
  background:rgba(14,0,0,.95); border:1px solid rgba(255,58,42,.12);
  border-radius:14px; padding:12px;
  box-shadow:0 12px 40px rgba(0,0,0,.5), 0 0 0 1px rgba(0,0,0,.3);
  backdrop-filter:blur(14px);
}
.cam-admin-hdr {
  display:flex; align-items:center; gap:8px; margin-bottom:10px; color:#fecaca;
}
.cam-admin-hdr h3 { flex:1; margin:0; font-size:14px; font-weight:700; }
.cam-admin-online {
  font-size:10px; font-weight:600; color:#ff3a2a;
  padding:2px 8px; border-radius:8px;
  background:rgba(255,58,42,.1);
}
.cam-admin-hdr button {
  width:26px; height:26px; border-radius:6px; border:1px solid rgba(255,58,42,.15);
  background:rgba(255,58,42,.04); color:#fca5a5; cursor:pointer;
  display:flex; align-items:center; justify-content:center;
  transition:background .15s;
}
.cam-admin-hdr button:hover { background:rgba(255,58,42,.12); }

.cam-admin-grid {
  display:flex; flex-direction:column; gap:10px;
}

/* ── Agent floating pip ──────────────────────────────────────────── */
.cam-widget-agent {
  position:fixed; top:80px; right:16px; z-index:10000;
  width:180px;
}
.cam-widget-agent .cam-agent-vid { aspect-ratio:4/3; }
.cam-minimize-inline {
  margin-left:auto; width:20px; height:20px; border-radius:5px; border:none;
  background:rgba(255,58,42,.08); color:#fca5a5; cursor:pointer;
  display:flex; align-items:center; justify-content:center;
  transition:background .15s; flex-shrink:0;
}
.cam-minimize-inline:hover { background:rgba(255,58,42,.2); }

@media (max-width:600px) {
  .cam-admin-panel { width:calc(100vw - 24px); right:12px; top:60px; }
  .cam-widget-agent { width:140px; }
}

