import { useCallback, useEffect, useRef, useState } from 'react';
import { authFetch } from '@/utils/auth-fetch';

type Presence = {
  connection_state: 'idle' | 'connecting' | 'ready' | 'failed';
  call_state: 'idle' | 'dialing' | 'ringing-in' | 'answering' | 'active' | 'ending';
  microphone_granted: boolean;
  device_kind: 'desktop' | 'companion';
};

// Readiness reflects a registered desktop phone with microphone permission.
// Monotonic sequence numbers prevent delayed responses reviving stale status.
export function usePhonePresence(url: string, token: string, state: Presence, onUnauthorized: () => void) {
  const [instanceId] = useState(() => crypto.randomUUID());
  const [error, setError] = useState('');
  const sequence = useRef(0);
  const latest = useRef(state); latest.current = state;
  const unauthorized = useRef(onUnauthorized); unauthorized.current = onUnauthorized;
  const mounted = useRef(false);
  const send = useCallback(async () => {
    const currentSequence = ++sequence.current;
    const result = await authFetch<{ ok: boolean }>(url, {
      body: { action: 'phone_presence_update', session_token: token, instance_id: instanceId, sequence: currentSequence, ...latest.current },
      timeoutMs: 10000, onUnauthorized: () => unauthorized.current(),
    });
    if (mounted.current && currentSequence === sequence.current) {
      setError(result.ok ? '' : 'Phone status could not sync. Retrying status updates…');
    }
  }, [url, token, instanceId]);

  useEffect(() => {
    mounted.current = true;
    const timer = setInterval(() => { void send(); }, 20000);
    const resume = () => { if (!document.hidden) void send(); };
    const offline = () => {
      void fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, keepalive: true,
        body: JSON.stringify({ action: 'phone_presence_update', session_token: token, instance_id: instanceId,
          sequence: ++sequence.current, ...latest.current, connection_state: 'idle', call_state: 'idle', microphone_granted: false }),
      }).catch(() => {});
    };
    document.addEventListener('visibilitychange', resume);
    window.addEventListener('online', resume);
    window.addEventListener('pageshow', resume);
    window.addEventListener('pagehide', offline);
    return () => {
      mounted.current = false;
      clearInterval(timer);
      document.removeEventListener('visibilitychange', resume);
      window.removeEventListener('online', resume);
      window.removeEventListener('pageshow', resume);
      window.removeEventListener('pagehide', offline);
      offline();
    };
  }, [url, token, instanceId, send]);

  useEffect(() => { void send(); }, [send, state.connection_state, state.call_state, state.microphone_granted, state.device_kind]);
  return error;
}

src/phone/useVoicemailCount.ts:
import { useEffect, useState } from 'react';
import { authFetch } from '@/utils/auth-fetch';

// Keep the badge available even while the desktop calling connection is offline.
export function useVoicemailCount(sessionToken: string, providerUrl: string) {
  const [count, setCount] = useState<number | null>(null);
  useEffect(() => {
    let alive = true;
    let running = false;
    setCount(null);
    const refresh = async () => {
      if (running || document.visibilityState === 'hidden') return;
      running = true;
      try {
        const result = await authFetch<{messages: {heard_at?: string | null}[]}>(providerUrl, {
          body: {action: 'mailbox_list', session_token: sessionToken},
          onUnauthorized: () => {},
        });
        if (alive) setCount(result.ok && result.data ? result.data.messages.filter(m => !m.heard_at).length : null);
      } finally { running = false; }
    };
    void refresh();
    const timer = window.setInterval(() => void refresh(), 30000);
    const onChange = () => { void refresh(); };
    document.addEventListener('visibilitychange', onChange);
    window.addEventListener('f1-voicemail-heard', onChange);
    return () => {
      alive = false;
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', onChange);
      window.removeEventListener('f1-voicemail-heard', onChange);
    };
  }, [sessionToken, providerUrl]);
  return count;
}

src/utils/attendance.ts:
/**
 * Attendance interval math — pure functions, no I/O.
 *
 * An "interval" is { start: number; end: number } where both are epoch-ms.
 * These utilities merge overlapping/adjacent intervals into a minimal union,
 * clamp them to day/week boundaries in a named timezone, and sum durations.
 */

// ── Types ───────────────────────────────────────────────────────────
export interface Interval {
  start: number; // epoch-ms
  end: number;   // epoch-ms
}

export type PresenceState = 'online' | 'disconnected' | 'signed-out' | 'unknown';

export interface AttendanceSummary {
  presenceState: PresenceState;
  lastConfirmedAt: number | null;     // epoch-ms of last heartbeat
  currentSessionSeconds: number;
  todayTotalSeconds: number;
  weekTotalSeconds: number;
  isLegacyEstimate: boolean;          // true when data predates heartbeat system
}

// ── Interval union ──────────────────────────────────────────────────

/** Sort intervals by start ascending, break ties by end descending. */
export function sortIntervals(intervals: Interval[]): Interval[] {
  return [...intervals].sort((a, b) => a.start - b.start || b.end - a.end);
}

/**
 * Merge overlapping/adjacent intervals into a minimal set.
 * Input does NOT need to be sorted — we sort internally.
 * Discards zero-width or negative intervals.
 */
export function unionIntervals(intervals: Interval[]): Interval[] {
  const valid = intervals.filter(i => i.end > i.start);
  if (valid.length === 0) return [];
  const sorted = sortIntervals(valid);
  const merged: Interval[] = [{ ...sorted[0] }];
  for (let i = 1; i < sorted.length; i++) {
    const cur = sorted[i];
    const last = merged[merged.length - 1];
    if (cur.start <= last.end) {
      last.end = Math.max(last.end, cur.end);
    } else {
      merged.push({ ...cur });
    }
  }
  return merged;
}

/** Clamp intervals to a [windowStart, windowEnd) range. */
export function clampIntervals(intervals: Interval[], windowStart: number, windowEnd: number): Interval[] {
  const result: Interval[] = [];
  for (const iv of intervals) {
    const s = Math.max(iv.start, windowStart);
    const e = Math.min(iv.end, windowEnd);
    if (e > s) result.push({ start: s, end: e });
  }
  return result;
}

/** Sum total milliseconds across intervals (assumes already merged). */
export function sumIntervalMs(intervals: Interval[]): number {
  let total = 0;
  for (const iv of intervals) total += iv.end - iv.start;
  return total;
}

/** Sum total seconds across intervals (assumes already merged). */
export function sumIntervalSeconds(intervals: Interval[]): number {
  return Math.floor(sumIntervalMs(intervals) / 1000);
}

// ── Timezone-aware day/week boundaries ──────────────────────────────

/**
 * Get the start-of-day in a named timezone as epoch-ms.
 * Uses Intl to find the local date parts, then reconstructs.
 */
export function startOfDayTz(epochMs: number, tz: string): number {
  const d = new Date(epochMs);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(d);
  const get = (t: string) => parts.find(p => p.type === t)?.value || '01';
  const iso = `${get('year')}-${get('month')}-${get('day')}T00:00:00`;
  const midnight = new Date(iso);
  const offset = getTimezoneOffsetMs(midnight.getTime(), tz);
  return midnight.getTime() + offset;
}

/**
 * Get the start-of-week (Monday) in a named timezone as epoch-ms.
 */
export function startOfWeekTz(epochMs: number, tz: string): number {
  const dayStart = startOfDayTz(epochMs, tz);
  const d = new Date(dayStart);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, weekday: 'short',
  }).formatToParts(d);
  const weekday = parts.find(p => p.type === 'weekday')?.value || 'Mon';
  const dayMap: Record<string, number> = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
  const daysBack = dayMap[weekday] ?? 0;
  return dayStart - daysBack * 86400000;
}

function getTimezoneOffsetMs(epochMs: number, tz: string): number {
  const utcStr = new Date(epochMs).toLocaleString('en-US', { timeZone: 'UTC' });
  const tzStr = new Date(epochMs).toLocaleString('en-US', { timeZone: tz });
  return new Date(utcStr).getTime() - new Date(tzStr).getTime();
}

// ── Session → Interval conversion ───────────────────────────────────

export interface SessionRow {
  created_at: string;          // ISO timestamp
  invalidated_at: string | null;
  expires_at: string;
  last_heartbeat_at?: string | null;
}

/**
 * Convert a session row to an interval.
 * End is the EARLIEST of: invalidated_at, expires_at, last_heartbeat_at + staleMs, now.
 * This prevents accruing time when the user is asleep/offline.
 */
export function sessionToInterval(
  row: SessionRow,
  nowMs: number,
  staleMs: number = 90_000,
): Interval {
  const start = new Date(row.created_at).getTime();
  let end = nowMs;

  if (row.invalidated_at) {
    end = Math.min(end, new Date(row.invalidated_at).getTime());
  }
  end = Math.min(end, new Date(row.expires_at).getTime());

  if (row.last_heartbeat_at) {
    const heartbeatCap = new Date(row.last_heartbeat_at).getTime() + staleMs;
    end = Math.min(end, heartbeatCap);
  }

  return { start, end };
}

/**
 * Convert a batch of session rows to merged intervals.
 * Handles overlapping sessions from multiple tabs/devices.
 */
export function sessionsToMergedIntervals(
  rows: SessionRow[],
  nowMs: number,
  staleMs?: number,
): Interval[] {
  const intervals = rows.map(r => sessionToInterval(r, nowMs, staleMs));
  return unionIntervals(intervals);
}

// ── Attendance computation ──────────────────────────────────────────

export function computeAttendance(
  sessions: SessionRow[],
  nowMs: number,
  tz: string,
  staleMs: number = 90_000,
): AttendanceSummary {
  const merged = sessionsToMergedIntervals(sessions, nowMs, staleMs);
  const dayStart = startOfDayTz(nowMs, tz);
  const dayEnd = dayStart + 86400000;
  const weekStart = startOfWeekTz(nowMs, tz);

  const todayIntervals = clampIntervals(merged, dayStart, dayEnd);
  const weekIntervals = clampIntervals(merged, weekStart, dayEnd);

  const activeSessions = sessions.filter(s => {
    if (s.invalidated_at) return false;
    if (new Date(s.expires_at).getTime() <= nowMs) return false;
    return true;
  });

  let presenceState: PresenceState = 'signed-out';
  let lastConfirmedAt: number | null = null;
  let currentSessionSeconds = 0;
  const hasHeartbeats = sessions.some(s => s.last_heartbeat_at);

  if (activeSessions.length > 0) {
    const latestHeartbeat = activeSessions
      .filter(s => s.last_heartbeat_at)
      .map(s => new Date(s.last_heartbeat_at!).getTime())
      .reduce((a, b) => Math.max(a, b), 0);

    if (latestHeartbeat > 0) {
      lastConfirmedAt = latestHeartbeat;
      presenceState = (nowMs - latestHeartbeat <= staleMs) ? 'online' : 'disconnected';
    } else {
      presenceState = 'unknown';
    }

    const latestSession = activeSessions.reduce((a, b) =>
      new Date(a.created_at).getTime() > new Date(b.created_at).getTime() ? a : b
    );
    const iv = sessionToInterval(latestSession, nowMs, staleMs);
    currentSessionSeconds = Math.max(0, Math.floor((Math.min(iv.end, nowMs) - iv.start) / 1000));
  }

  return {
    presenceState,
    lastConfirmedAt,
    currentSessionSeconds,
    todayTotalSeconds: sumIntervalSeconds(todayIntervals),
    weekTotalSeconds: sumIntervalSeconds(weekIntervals),
    isLegacyEstimate: !hasHeartbeats,
  };
}

// ── Formatting helpers ──────────────────────────────────────────────

export function fmtAttendanceDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

export function presenceLabel(state: PresenceState): string {
  switch (state) {
    case 'online': return 'Online';
    case 'disconnected': return 'Disconnected';
    case 'signed-out': return 'Signed Out';
    case 'unknown': return 'Unknown';
  }
}

export function presenceColor(state: PresenceState): string {
  switch (state) {
    case 'online': return '#22c55e';
    case 'disconnected': return '#f59e0b';
    case 'signed-out': return '#6b7280';
    case 'unknown': return '#9ca3af';
  }
}

src/utils/auth-fetch.ts:
/**
 * Centralized authenticated fetch. Enforces:
 * - A 401 logs out only after wolf-auth confirms the same saved session is invalid.
 * - 5xx and network errors do NOT log out — caller sees error, keeps session.
 * - No action retries; a 401 makes one bounded, read-only session verification.
 * - Loading is caller-managed; this function never throws.
 */
export interface AuthFetchResult<T = unknown> {
  ok: boolean;
  status: number;
  data: T | null;
  error: string | null;
  loggedOut: boolean;
}

export interface AuthFetchOptions {
  onUnauthorized: () => void;
  body: Record<string, unknown>;
  signal?: AbortSignal;
  timeoutMs?: number;
}

export async function authFetch<T = unknown>(
  url: string,
  opts: AuthFetchOptions,
): Promise<AuthFetchResult<T>> {
  const { onUnauthorized, body, signal, timeoutMs = 15000 } = opts;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  const abort = () => controller.abort();
  if (signal?.aborted) controller.abort();
  else signal?.addEventListener('abort', abort, { once: true });

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    if (controller.signal.aborted) throw new Error('Request cancelled');

    if (res.status === 401) {
      // A feature endpoint (or gateway) can fail independently of authentication.
      // Never discard a valid login until the authentication service confirms expiry.
      const token = body.session_token;
      const authUrl = url.replace(/\/functions\/v1\/[^/?#]+(?:[?#].*)?$/, '/functions/v1/wolf-auth');
      if (typeof token !== 'string' || !token || authUrl === url) {
        return { ok: false, status: 401, data: null, error: 'Unable to verify session', loggedOut: false };
      }
      const verification = await fetch(authUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'verify', session_token: token }),
        signal: controller.signal,
      });
      if (controller.signal.aborted) throw new Error('Request cancelled');
      if (!verification.ok) {
        return { ok: false, status: 503, data: null, error: 'Session verification temporarily unavailable', loggedOut: false };
      }
      const session = await verification.json();
      if (controller.signal.aborted) throw new Error('Request cancelled');
      if (session?.valid !== false) {
        return { ok: false, status: 401, data: null, error: 'Request authorization failed; your login has been kept. Please retry.', loggedOut: false };
      }
      // An old request must not sign out an account that logged in while it ran.
      if (typeof localStorage !== 'undefined' && localStorage.getItem('sterling_session_token') !== token) {
        return { ok: false, status: 401, data: null, error: 'Previous session expired', loggedOut: false };
      }
      onUnauthorized();
      return { ok: false, status: 401, data: null, error: 'Session expired', loggedOut: true };
    }

    let parsed: T = null as T;
    let parseError: string | null = null;
    try { parsed = await res.json() as T; } catch { parseError = 'Invalid response from server'; }
    if (controller.signal.aborted) throw new Error('Request cancelled');

    if (res.status >= 500) {
      const errMsg = (parsed as unknown as Record<string, unknown>)?.error as string || parseError || `HTTP ${res.status}`;
      return { ok: false, status: res.status, data: null, error: errMsg, loggedOut: false };
    }
    if (res.status >= 400) {
      const errMsg = (parsed as unknown as Record<string, unknown>)?.error as string || parseError || `HTTP ${res.status}`;
      return { ok: false, status: res.status, data: parsed, error: errMsg, loggedOut: false };
    }
    if (parseError) {
      return { ok: false, status: res.status, data: null, error: parseError, loggedOut: false };
    }
    const errField = (parsed as unknown as Record<string, unknown>)?.error;
    if (errField && typeof errField === 'string') {
      return { ok: false, status: res.status, data: parsed, error: errField, loggedOut: false };
    }
    return { ok: true, status: res.status, data: parsed, error: null, loggedOut: false };
  } catch {
    return { ok: false, status: 0, data: null, error: 'Cannot reach the server', loggedOut: false };
  } finally {
    clearTimeout(timeout);
    signal?.removeEventListener('abort', abort);
  }
}

src/utils/contact-search.ts:
export function contactEmails(contact: { email?: string; emails?: string[]; custom_fields?: Record<string, unknown> | null }): string[] {
  const result: string[] = [];
  if (contact.email) result.push(contact.email);
  if (contact.emails) result.push(...contact.emails);
  if (contact.custom_fields) {
    for (const [key, val] of Object.entries(contact.custom_fields)) {
      if (/e-?mail/i.test(key)) {
        const values = Array.isArray(val) ? val : [val];
        for (const item of values) {
          if (typeof item === 'string' && item.includes('@') && !result.includes(item)) result.push(item);
        }
      }
    }
  }
  return [...new Set(result)];
}

export function contactFieldText(value: unknown): string {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(contactFieldText).join(', ');
  if (typeof value === 'object') {
    try { return JSON.stringify(value); } catch { return '[object]'; }
  }
  return String(value);
}

src/utils/funnel.ts:
export interface FunnelStage {
  key: string;
  label: string;
  value: number;
  color: string;
  description: string;
  isHeadline?: boolean;
  isEstimate?: boolean;
}

export interface FunnelData {
  calls_attempted: number;
  live_humans_reached: number;
  transfers_requested: number;
  talkroute_dialed: number;
  agent_answered: number;
  bridge_confirmed: number;
  likely_real_conversation: number;
  transfer_failed_unverified: number;
  data_quality_exceptions: number;
  total_minutes: number;
  productive_minutes: number;
  wasted_minutes: number;
  machine_minutes: number;
  avg_ai_leg_seconds: number;
  machines_detected: number;
  avg_machine_seconds: number;
}

export const STAGE_DEFINITIONS: Record<string, string> = {
  attempted: 'Provider accepted an outbound call in the selected window.',
  live_human: 'Outbound call classified as a live human by the call-processing system; not identity verification.',
  transfer_requested: 'Outbound call with an explicit transfer-request timestamp.',
  destination_dialed: 'The provider dialed the assigned Zadarma number.',
  agent_answered: 'An inbound Zadarma answer linked to this outbound call, excluding voicemail.',
  bridge_confirmed: 'Agent-answered call meeting the strict bridge-confirm predicate.',
  likely_real_conversation: 'Provider-confirmed bridge with at least 45 post-transfer seconds and recorded representative speech evidence.',
};

export function buildMonotonicFunnel(data: FunnelData): { stages: FunnelStage[]; exceptions: number; sideOutcome: number } {
  const attempted = Math.max(0, data.calls_attempted);
  const liveHuman = Math.max(0, data.live_humans_reached);
  const transferRequested = Math.max(0, data.transfers_requested);
  const destinationDialed = Math.max(0, data.talkroute_dialed);
  const agentAnswered = Math.max(0, data.agent_answered);
  const bridgeConfirmed = Math.max(0, data.bridge_confirmed);
  const likelyReal = Math.max(0, data.likely_real_conversation);

  const exceptions =
    Math.max(0, data.live_humans_reached - attempted) +
    Math.max(0, data.transfers_requested - liveHuman) +
    Math.max(0, data.talkroute_dialed - transferRequested) +
    Math.max(0, data.agent_answered - destinationDialed) +
    Math.max(0, data.bridge_confirmed - agentAnswered) +
    Math.max(0, data.likely_real_conversation - bridgeConfirmed);

  const stages: FunnelStage[] = [
    { key: 'attempted', label: 'Calls Attempted', value: attempted, color: 'var(--sage-400)', description: STAGE_DEFINITIONS.attempted },
    { key: 'live_human', label: 'Human-classified Calls', value: liveHuman, color: 'var(--gold-300)', description: STAGE_DEFINITIONS.live_human },
    { key: 'transfer_requested', label: 'Transfer Requested', value: transferRequested, color: 'var(--rust-400)', description: STAGE_DEFINITIONS.transfer_requested },
    { key: 'destination_dialed', label: 'Zadarma Destination Dialed', value: destinationDialed, color: 'var(--steel-300)', description: STAGE_DEFINITIONS.destination_dialed },
    { key: 'agent_answered', label: 'Agent Answer Confirmed', value: agentAnswered, color: 'var(--sage-300)', description: STAGE_DEFINITIONS.agent_answered },
    { key: 'bridge_confirmed', label: 'Bridge Confirmed', value: bridgeConfirmed, color: 'var(--sage-400)', description: STAGE_DEFINITIONS.bridge_confirmed, isHeadline: true },
    { key: 'likely_real_conversation', label: 'Post-transfer Speech (45s+)', value: likelyReal, color: 'var(--gold-200)', description: STAGE_DEFINITIONS.likely_real_conversation, isEstimate: true },
  ];

  return { stages, exceptions, sideOutcome: Math.max(0, data.transfer_failed_unverified) };
}

export function isMonotonic(data: FunnelData): boolean {
  return (
    data.calls_attempted >= data.live_humans_reached &&
    data.live_humans_reached >= data.transfers_requested &&
    data.transfers_requested >= data.talkroute_dialed &&
    data.talkroute_dialed >= data.agent_answered &&
    data.agent_answered >= data.bridge_confirmed &&
    data.bridge_confirmed >= data.likely_real_conversation
  );
}

export interface AgentPerfData {
  calls_attempted: number;
  live_humans: number;
  transfers_requested: number;
  bridge_confirmed: number;
}

export interface CappedAgentPerf {
  attempted: number;
  live: number;
  transfers: number;
  bridged: number;
  exceptions: number;
}

export function capAgentMonotonic(raw: AgentPerfData): CappedAgentPerf {
  const attempted = Math.max(0, raw.calls_attempted);
  const live = Math.max(0, raw.live_humans);
  const transfers = Math.max(0, raw.transfers_requested);
  const bridged = Math.max(0, raw.bridge_confirmed);
  const exceptions =
    Math.max(0, raw.live_humans - attempted) +
    Math.max(0, raw.transfers_requested - live) +
    Math.max(0, raw.bridge_confirmed - transfers);
  return { attempted, live, transfers, bridged, exceptions };
}

src/utils/inbound-health.ts:
type RouteResult = {
  agent_id: string;
  full_name: string;
  bland_number?: string;
  talkroute_number?: string;
  inbound_configured?: boolean;
  configuration_ready?: boolean;
  agent_ready?: boolean;
  last_verified_at?: string;
  [key: string]: unknown;
};

export type InboundHealth = {
  results: RouteResult[];
  ready_agent_count: number;
  selected_agent_count: number;
  configuration_ready: boolean;
  checked_at: string;
};

export function currentInboundHealth(data: unknown): InboundHealth | null {
  if (!data || typeof data !== 'object') return null;
  const d = data as Record<string, unknown>;
  const results = (d.results || d.agents || []) as RouteResult[];
  const ready = results.filter(r => r.configuration_ready);
  return {
    results,
    ready_agent_count: ready.length,
    selected_agent_count: results.length,
    configuration_ready: ready.length === results.length && results.length > 0,
    checked_at: (d.checked_at as string) || new Date().toISOString(),
  };
}

export function inboundRouteProblems(route: RouteResult): string[] {
  const problems: string[] = [];
  if (!route.bland_number) problems.push('No inbound line assigned');
  if (!route.talkroute_number) problems.push('No Zadarma destination');
  if (route.inbound_configured === false) problems.push('Inbound not configured');
  if (route.configuration_ready === false && route.bland_number && route.talkroute_number) {
    problems.push('Route check failed');
  }
  return problems;
}

src/utils/privacy.ts:
export function maskPhone(phone: string): string {
  if (!phone) return '—';
  const digits = phone.replace(/\D/g, '');
  if (digits.length < 4) return '••••';
  const last4 = digits.slice(-4);
  return `•••• ${last4}`;
}

export function formatPhone(phone: string): string {
  if (!phone) return '—';
  const digits = phone.replace(/\D/g, '');
  if (digits.length === 11 && digits[0] === '1') {
    return `(${digits.slice(1, 4)}) ${digits.slice(4, 7)}-${digits.slice(7)}`;
  }
  if (digits.length === 10) {
    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return phone;
}

export function maskAddress(address: string): string {
  if (!address) return '—';
  const parts = address.split(',').map(p => p.trim()).filter(Boolean);
  if (parts.length <= 1) {
    return parts[0]?.slice(0, 8) + '…' || '—';
  }
  return parts.slice(1).join(', ');
}

export function maskAddressCoarse(address: string): string {
  if (!address) return '—';
  const parts = address.split(',').map(p => p.trim()).filter(Boolean);
  if (parts.length <= 1) return 'Address on file';
  return parts.slice(1).join(', ');
}

src/utils/serial-poll.ts:
// Schedule the next refresh after the current request settles, never over it.
export function startSerialPoll(
  task: (signal: AbortSignal) => Promise<boolean | void>,
  intervalMs: number,
  options: { paused?: () => boolean; maxBackoffMs?: number } = {},
) {
  let stopped = false;
  let pending = false;
  let failures = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let controller: AbortController | undefined;
  const schedule = (delay: number) => { timer = setTimeout(() => { void run(); }, delay); };
  const run = async () => {
    if (stopped || pending) return;
    clearTimeout(timer);
    if (options.paused?.()) { schedule(intervalMs); return; }
    pending = true;
    controller = new AbortController();
    try {
      const ok = await task(controller.signal);
      failures = ok === false ? Math.min(failures + 1, 4) : 0;
    } catch { failures = Math.min(failures + 1, 4); }
    finally {
      pending = false;
      controller = undefined;
      if (!stopped) schedule(Math.min(options.maxBackoffMs ?? 60000, intervalMs * 2 ** failures));
    }
  };
  void run();
  return {
    refresh: () => { void run(); },
    stop: () => { stopped = true; clearTimeout(timer); controller?.abort(); },
  };
}

