type MetricName = 'transfers_requested' | 'talkroute_dialed' | 'agent_answered' | 'bridge_confirmed' | 'confirmed_transfer_failures' | 'transfer_failed_unverified';
export type TransferMetricSummary = Partial<Record<`${MetricName}_${'today' | 'week' | 'all'}`, number>>;
type MetricWindow = { requested: number; dialed: number; answered: number; bridged: number; failed: number; unverified: number };
export function transferMetricsForWindow(summary: TransferMetricSummary, window: 'today' | 'week' | 'all'): MetricWindow {
  return {
    requested: summary[`transfers_requested_${window}`] ?? 0,
    dialed: summary[`talkroute_dialed_${window}`] ?? 0,
    answered: summary[`agent_answered_${window}`] ?? 0,
    bridged: summary[`bridge_confirmed_${window}`] ?? 0,
    failed: summary[`confirmed_transfer_failures_${window}`] ?? 0,
    unverified: summary[`transfer_failed_unverified_${window}`] ?? 0,
  };
}

src/utils/useContactSearch.ts:
import { useEffect, useRef, useState } from 'react';
import { authFetch } from '@/utils/auth-fetch';

export function useContactSearch<T extends { id?: string; contact_key?: string }>(providerUrl: string, sessionToken: string, onUnauthorized: () => void) {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<T[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState(false);
  const [searchTotal, setSearchTotal] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const generationRef = useRef(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const queryRef = useRef('');
  const offsetRef = useRef(0);
  const sessionRef = useRef(sessionToken);
  const mountedRef = useRef(true);

  const clearTimer = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = null;
  };

  const reset = () => {
    clearTimer();
    generationRef.current += 1;
    queryRef.current = '';
    offsetRef.current = 0;
    setSearchQuery('');
    setSearchResults([]);
    setSearchTotal(0);
    setHasMore(false);
    setSearching(false);
    setSearchError(false);
  };

  useEffect(() => {
    mountedRef.current = true;
    if (sessionRef.current !== sessionToken) {
      sessionRef.current = sessionToken;
      reset();
    }
    return () => {
      mountedRef.current = false;
      clearTimer();
      generationRef.current += 1;
    };
  }, [sessionToken]);

  const doSearch = async (query: string, offset: number, generation: number) => {
    const requestSession = sessionToken;
    const result = await authFetch(providerUrl, {
      // wolf-provider's public contract is `search_text`. Keeping this name in
      // one place prevents a silent empty search when the UI and function drift.
      body: { action: 'search_contacts', session_token: requestSession, search_text: query.trim(), offset },
      onUnauthorized: () => {
        if (mountedRef.current && generation === generationRef.current && requestSession === sessionRef.current) onUnauthorized();
      },
    });
    if (!mountedRef.current || generation !== generationRef.current || requestSession !== sessionRef.current) return;
    if (result.ok && result.data) {
      const data = result.data as Record<string, unknown>;
      const rows = (data.results || data.contacts || []) as T[];
      const total = Number(data.count ?? data.total ?? rows.length);
      setSearchResults(previous => {
        const combined = offset === 0 ? rows : [...previous, ...rows];
        const seen = new Set<string>();
        return combined.filter((row, index) => {
          const key = row.contact_key || row.id || `row-${index}`;
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      });
      offsetRef.current = offset + rows.length;
      setSearchTotal(total);
      setHasMore(offset + rows.length < total);
      setSearchError(false);
    } else if (!result.loggedOut) {
      setSearchError(true);
    }
    setSearching(false);
  };

  const onSearchChange = (input: React.ChangeEvent<HTMLInputElement> | string) => {
    const query = typeof input === 'string' ? input : input.target.value;
    clearTimer();
    generationRef.current += 1;
    const generation = generationRef.current;
    queryRef.current = query;
    offsetRef.current = 0;
    setSearchQuery(query);
    setSearchResults([]);
    setSearchTotal(0);
    setHasMore(false);
    setSearchError(false);
    if (!query.trim()) {
      setSearching(false);
      return;
    }
    setSearching(true);
    timerRef.current = setTimeout(() => {
      timerRef.current = null;
      void doSearch(query, 0, generation);
    }, 300);
  };

  const onSearchKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key !== 'Enter' || !queryRef.current.trim()) return;
    clearTimer();
    generationRef.current += 1;
    const generation = generationRef.current;
    setSearching(true);
    void doSearch(queryRef.current, 0, generation);
  };

  const loadMore = () => {
    if (!queryRef.current.trim() || searching) return;
    const generation = generationRef.current;
    setSearching(true);
    void doSearch(queryRef.current, offsetRef.current, generation);
  };

  return { searchQuery, searchResults, searching, searchError, searchTotal, hasMore, onSearchChange, onSearchKeyDown, loadMore };
}

src/utils/useHeartbeat.ts:
import { useEffect, useRef } from 'react';
import { authFetch } from '@/utils/auth-fetch';
import type { PresenceState } from '@/utils/attendance';

export interface AttendanceInfo {
  presence: PresenceState;
  lastConfirmedAt: string | null;
  currentSessionSeconds: number;
  todayTotalSeconds: number;
  weekTotalSeconds: number;
  isLegacyEstimate: boolean;
  timezone: string;
  serverNow: string;
}

interface UseHeartbeatOptions {
  providerUrl: string;
  sessionToken: string;
  onUnauthorized: () => void;
  onAttendance: (info: AttendanceInfo) => void;
  onError: (msg: string) => void;
  enabled: boolean;
  intervalMs?: number;
}

/** Keep presence fresh in background tabs; cancel old-account requests on change. */
export function useHeartbeat({providerUrl,sessionToken,onUnauthorized,onAttendance,onError,
  enabled,intervalMs=30_000}: UseHeartbeatOptions) {
  const callbacks=useRef({onUnauthorized,onAttendance,onError});
  callbacks.current={onUnauthorized,onAttendance,onError};
  useEffect(()=>{
    if (!enabled || !sessionToken) return;
    let active=true;
    let pending: AbortController | null=null;
    const send=async()=>{
      if (!active || pending) return;
      const controller=new AbortController();
      pending=controller;
      try {
        const result=await authFetch(providerUrl,{
          body:{action:'heartbeat',session_token:sessionToken},signal:controller.signal,
          onUnauthorized:()=>{if(active) callbacks.current.onUnauthorized();},
        });
        if(!active || controller.signal.aborted) return;
        const raw=(result.data as Record<string,unknown> | null)?.attendance as Record<string,unknown> | undefined;
        if(result.ok && raw?.valid) {
          callbacks.current.onAttendance({
            presence:(raw.presence as PresenceState)||'unknown',
            lastConfirmedAt:raw.last_confirmed_at as string|null,
            currentSessionSeconds:Number(raw.current_session_seconds)||0,
            todayTotalSeconds:Number(raw.today_total_seconds)||0,
            weekTotalSeconds:Number(raw.week_total_seconds)||0,
            isLegacyEstimate:raw.is_legacy_estimate===true,
            timezone:(raw.timezone as string)||'America/New_York',
            serverNow:(raw.server_now as string)||new Date().toISOString(),
          });
        } else if(!result.loggedOut) callbacks.current.onError(result.error||'Attendance sync unavailable');
      } finally { if(pending===controller) pending=null; }
    };
    const visible=()=>{if(document.visibilityState==='visible') void send();};
    void send();
    const timer=setInterval(send,intervalMs);
    document.addEventListener('visibilitychange',visible);
    window.addEventListener('online',send);
    window.addEventListener('focus',send);
    return()=>{
      active=false;
      pending?.abort();
      clearInterval(timer);
      document.removeEventListener('visibilitychange',visible);
      window.removeEventListener('online',send);
      window.removeEventListener('focus',send);
    };
  },[providerUrl,sessionToken,enabled,intervalMs]);
}

